window.C=window.C||{};C["민법"]={"민1-1":{"요약":"법률행위가 유효하려면 목적이 확정·가능·적법·사회적으로 타당해야 한다는 것과, 반사회질서·불공정 무효를 묻는다.","블록":[{"종류":"소제목","글":"권리변동과 법률행위의 종류"},{"종류":"요점","등급":"B","제목":"권리변동의 종류","글":"권리가 생기고 바뀌고 없어지는 일을 통틀어 권리변동이라 한다. 원시취득은 남의 권리와 상관없이 새로 얻는 것(건물 신축·시효취득 등)이고, 승계취득은 남의 권리를 이어받는 것이다 — 매매로 사면 이전적 승계 중 특정승계, 저당권을 설정받으면 설정적 승계다."},{"종류":"요점","등급":"B","제목":"단독행위와 계약","글":"의사표시 하나로 성립하면 단독행위, 두 의사표시가 맞아야 서면 계약이다. 상대방 없는 단독행위(유언, 재단법인 설립, 소유권 포기)와 상대방 있는 단독행위(동의·철회·추인, 해제·해지, 채무면제 등)로 나뉜다."},{"종류":"요점","등급":"C","제목":"채권행위·물권행위·준물권행위","글":"채권행위는 채권·채무를 낳고(매매·임대차), 물권행위는 물권이 곧바로 변동되며(소유권이전·저당권설정), 준물권행위는 물권 말고 다른 권리가 변동된다(채권양도·채무면제)."},{"종류":"요점","등급":"C","제목":"요식행위와 불요식행위","글":"정해진 방식을 갖춰야 성립하는 게 요식행위(혼인, 유언, 법인 설립행위)고, 방식을 따로 요구하지 않는 게 불요식행위다. 법률행위는 불요식이 원칙이다."},{"종류":"소제목","글":"법률행위의 목적과 해석"},{"종류":"요점","등급":"B","제목":"목적의 확정성","글":"법률행위의 목적은 성립할 때 이미 확정돼 있어야 하는 것은 아니다. 이행기까지 확정할 수 있는 방법과 기준만 마련돼 있으면 충분하다."},{"종류":"요점","등급":"B","제목":"강행규정의 종류","글":"어기면 사법상 효력까지 무효가 되는 게 효력규정이다 — 공인중개사법령이 정한 상한을 넘겨 중개보수를 약정하면 무효다. 처벌은 받지만 사법상 효력은 원칙적으로 그대로인 게 단속규정이다 — 무허가 음식점의 판매행위, 중간생략등기 합의, 개업공인중개사와 의뢰인의 직접거래가 그렇다."},{"종류":"요점","등급":"B","제목":"반사회질서 행위(제103조)","글":"법률행위가 반사회적인지는 그 행위가 성립한 때를 기준으로 판단한다. 허위진술 대가 약정, 형사사건 성공보수 약정은 무효이지만 민사사건의 성공보수 약정은 유효하다."},{"종류":"요점","등급":"A","제목":"부동산 이중매매","글":"제2매수인이 이미 팔린 부동산인 줄 알면서 매도인의 배임행위에 적극 가담해 이뤄진 이중매매는 반사회질서로 무효다. 제2매수인이 이중매매 사실을 알았다는 것만으로는 무효가 되지 않는다."},{"종류":"요점","등급":"A","제목":"불공정한 법률행위(제104조)","글":"급부와 반대급부가 현저하게 불균형이고(객관적 요건, 법률행위 당시 기준), 피해자가 궁박·경솔·무경험 상태에서 폭리자가 이를 알고 이용했어야(주관적 요건) 성립한다. 대리인이 계약했다면 궁박은 본인을, 경솔·무경험은 대리인을 기준으로 본다. 경매에는 적용되지 않는다."},{"종류":"요점","등급":"A","제목":"반사회적 행위의 효과","글":"반사회질서·불공정 행위는 절대적 무효라서 선의의 제3자에게도 무효를 내세울 수 있다. 불공정한 법률행위에도 무효행위의 전환 법리는 적용될 수 있다."},{"종류":"요점","등급":"B","제목":"무효 사유 구별","글":"법률행위가 이뤄지는 과정에 강박이라는 불법 수단이 쓰인 것만으로는 반사회질서가 아니다 — 강박을 이유로 취소를 다툴 문제다. 강제집행을 피하려 설정한 허위 근저당권은 통정허위표시라서 무효이지 반사회질서는 아니다. 양도소득세를 피하려 낮춰 쓴 매매대금은 단속규정 위반일 뿐이다."},{"종류":"요점","등급":"B","제목":"법률행위의 해석","글":"법률행위의 해석은 당사자가 속으로 원한 것을 캐는 일이 아니라 표시행위에 담긴 객관적 의미를 밝히는 일이다. 당사자의 의사가 서로 맞았는데 표시만 잘못했다면(오표시무해) 실제 의사대로 계약이 성립하고, 착오로 취소할 일도 없다."},{"종류":"구조","제목":"권리의 발생 — 원시취득과 승계취득","갈래":[{"이름":"원시취득","항목":["건물 신축","무주물선점 · 유실물 습득 · 매장물 발견","시효취득 · 선의취득","첨부(부합·혼화·가공)"]},{"이름":"승계취득","항목":["특정승계 — 매매·교환·증여·사인증여","포괄승계 — 상속·포괄유증·회사합병","설정적 승계 — 저당권 설정"]}],"결론":"매매로 사면 특정승계, 점유취득시효가 완성돼 얻으면 원시취득이다"},{"종류":"참고","글":"원시취득 = 남의 권리를 이어받지 않고 새로 생긴 권리를 얻는 것 · 포괄승계 = 권리와 의무를 한꺼번에 이어받는 것(상속 등)"},{"종류":"구조","제목":"의사표시의 수·방향으로 가른 법률행위","갈래":[{"이름":"상대방 없는 단독행위","항목":["유언(유증)","재단법인 설립행위","소유권 포기"]},{"이름":"상대방 있는 단독행위","항목":["동의·철회·추인","취소·해제·해지","상계 · 채무면제","대리권 수여행위","시효이익 포기 · 공유지분 포기"]},{"이름":"계약","항목":["매매·증여·교환·임대차 등 — 두 의사표시가 맞아야 성립"]}],"결론":"재단법인 설립·유증은 받을 상대방이 없고, 취소·추인·해제·상계는 상대방에게 하는 단독행위다"},{"종류":"비유","글":"상대방 없는 단독행위는 혼자 써 두면 되는 유언장, 상대방 있는 단독행위는 혼자 정하지만 상대에게 알려야 하는 해제 통지다. 계약은 두 사람 뜻이 맞아야 선다."},{"종류":"참고","글":"처분행위 = 물권행위와 준물권행위를 함께 부르는 말 — 이행할 일이 남지 않는다. 처분권 없이 한 처분행위는 무효지만, 남의 물건을 파는 매매계약(채권행위)은 유효하다"},{"종류":"구조","제목":"법률행위의 목적이 갖출 네 가지","갈래":[{"이름":"확정성","항목":["이행기까지 정해질 수 있으면 충분"]},{"이름":"가능성","항목":["원시적 불능 — 무효(계약체결상 과실책임)","후발적 불능 — 유효(채무불이행·위험부담)"]},{"이름":"적법성","항목":["효력규정 위반 — 무효","단속규정 위반 — 원칙 유효"]},{"이름":"사회적 타당성","항목":["반사회질서(제103조) — 무효","불공정(제104조) — 무효"]}],"결론":"계약한 뒤에 이행이 불가능해져도 계약은 무효가 아니다 — 무효는 처음부터 불능일 때다"},{"종류":"조문","조":"제103조","글":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"종류":"조문","조":"제104조","글":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"종류":"비교","제목":"무효 이유 가리기 — 반사회질서인가, 다른 이유인가","머리":["구분","반사회질서","통정허위표시","강행(효력)규정 위반","단속규정 위반"],"행":[["효력","무효","무효","무효","원칙 유효"],["선의의 제3자에게","무효를 내세움 ○","무효를 내세움 ✕","무효를 내세움 ○","—"],["기출 예","형사사건 성공보수 · 허위진술 대가 · 보험금을 노린 다수 보험계약","강제집행을 피하려는 허위 근저당권","명의신탁약정 · 농지 임대차","양도세를 줄이려 낮춰 쓴 매매대금 · 중개사와 의뢰인의 직접거래"]],"결론":"허위표시나 강행규정 위반으로 무효여도 반사회질서는 아니다 — 비자금 소극 은닉 임치·태아 상해보험·민사사건 성공보수는 유효다"},{"종류":"비교","제목":"반사회질서(제103조)와 불공정(제104조)","머리":["구분","반사회질서 행위","불공정한 법률행위"],"행":[["관계","원칙 규정","제103조의 예시 — 한 유형"],["판단 시점","법률행위가 성립한 때","법률행위를 한 때"],["핵심 요건","내용이 선량한 풍속·사회질서에 반함","현저한 불균형 + 피해자의 궁박·경솔·무경험 + 폭리자의 이용 의사"],["적용 안 되는 곳","—","증여 같은 무상행위 · 경매"],["이미 이행한 것","돌려받지 못함(불법원인급여)","폭리자는 못 돌려받고 피해자는 돌려받음"],["추인 · 전환","추인해도 유효가 되지 않음","추인 ✕ · 무효행위의 전환은 가능"]],"결론":"둘 다 절대적 무효라 선의의 제3자에게도 무효를 내세운다"},{"종류":"비유","글":"단속규정 위반은 신호위반 딱지와 같다. 벌은 받아도 이미 한 거래는 살아 있다. 효력규정 위반은 거래 자체가 무효가 된다 — 개업공인중개사가 의뢰인과 직접 맺은 계약이 유효한 까닭이다."},{"종류":"비유","글":"반사회질서는 '무엇을' 약속했느냐(내용)의 흠이고, 강박은 '어떻게' 받아 냈느냐(과정)의 흠이다. 협박으로 맺은 계약은 강박을 이유로 취소할 문제이지 반사회질서로 무효가 되지 않는다."},{"종류":"비유","글":"이중매매의 제2매수인은 두 번째 손님이다. 이미 팔린 줄 알고 산 것만으로는 괜찮고, 파는 사람을 적극 부추겨 빼돌렸을 때 비로소 반사회질서로 무효가 된다."},{"종류":"비유","글":"대리인이 계약했다면 궁박은 본인이 처한 형편이라 본인을, 경솔·무경험은 계약하는 사람의 판단력이라 대리인을 기준으로 본다."},{"종류":"참고","글":"오표시무해 = 잘못 적은 표시는 해가 없다는 뜻. 두 사람 모두 X토지를 사고팔 생각이었다면 계약서에 Y토지로 잘못 적어도 계약은 X토지로 성립하고, 착오로 취소할 일도 없다"}]},"민1-2":{"요약":"의사와 표시가 어긋나거나(비진의·통정허위·착오) 남에게 속거나 겁먹어(사기·강박) 한 의사표시의 효력과 제3자 보호, 도달주의를 묻는다.","블록":[{"종류":"소제목","글":"비정상적 의사표시"},{"종류":"요점","등급":"B","제목":"진의 아닌 의사표시","글":"진의는 표의자가 이런 내용의 의사표시를 하겠다는 생각이지, 속으로 진짜 바라는 것이 아니다. 상대방이 진의 아님을 알았거나 알 수 있었다면 무효이지만, 선의의 제3자에게는 대항하지 못한다. 상대방과 통정(합의)이 있으면 허위표시, 없으면 비진의표시라는 점이 둘의 차이다."},{"종류":"요점","등급":"B","제목":"통정허위표시","글":"표의자와 상대방이 짜고 진의와 다른 표시를 하면 통정허위표시로 당사자 사이에서는 무효다(제108조). 증여할 뜻을 숨기고 매매로 꾸민 은닉행위라면, 꾸민 매매(가장행위)는 무효지만 숨은 증여는 유효하다. 허위표시도 채권자취소권의 대상이 될 수 있다."},{"종류":"요점","등급":"B","제목":"허위표시와 제3자","글":"허위표시가 무효라는 사실은 선의의 제3자에게 대항하지 못한다. 제3자는 당사자·포괄승계인이 아니면서 허위표시를 바탕으로 새 이해관계를 맺은 사람이다. 제3자의 선의는 추정되어 무효를 주장하는 쪽이 악의를 입증해야 하고, 무과실까지 요구하지는 않는다."},{"종류":"요점","등급":"A","제목":"착오의 요건","글":"법률행위 내용의 중요부분에 착오가 있고 표의자에게 중대한 과실이 없어야 취소할 수 있다. 중요부분인지는 표의자가, 중과실 없음은 상대방이 입증한다. 상대방이 표의자의 착오를 알고 이용했다면 중과실이 있어도 취소할 수 있다."},{"종류":"요점","등급":"A","제목":"착오의 효과","글":"착오로 한 의사표시는 취소할 수 있으나 선의의 제3자에게는 대항하지 못한다. 매도인이 채무불이행을 이유로 계약을 적법하게 해제한 뒤에도 매수인은 착오를 이유로 취소할 수 있다. 착오 규정은 강행규정이 아니라서 취소권을 배제하는 약정도 유효하다."},{"종류":"소제목","글":"사기·강박에 의한 의사표시"},{"종류":"요점","등급":"A","제목":"사기·강박의 요건","글":"부작위로도 기망할 수 있다 — 신의칙상 고지의무가 있는 사정을 알리지 않으면 묵시적 기망이다. 다만 과장광고나 시가를 말하지 않는 것은 원칙적으로 기망이 아니다. 제3자가 사기·강박을 했다면 상대방이 그 사실을 알았거나 알 수 있었을 때만 취소할 수 있는데, 상대방의 대리인은 상대방과 같은 사람으로 봐서 제3자가 아니다."},{"종류":"소제목","글":"의사표시의 효력발생"},{"종류":"요점","등급":"B","제목":"도달주의","글":"도달은 상대방이 내용을 알 수 있는 객관적 상태가 된 것이다. 실제로 받거나 읽었어야 하는 것은 아니고, 정당한 사유 없이 수령을 거절해도 도달로 본다. 보낸 뒤 도달 전이면 철회할 수 있지만 도달한 뒤에는 철회하지 못한다. 표의자가 보낸 뒤 사망하거나 제한능력자가 돼도 의사표시의 효력에는 영향이 없다."},{"종류":"요점","등급":"B","제목":"의사표시의 수령능력","글":"의사표시를 받는 사람이 제한능력자면 법정대리인이 도달 사실을 알기 전까지 표의자는 그 의사표시로 대항하지 못한다. 법정대리인이 알고 난 뒤에는 표의자가 도달을 주장할 수 있다."},{"종류":"구조","제목":"의사표시의 하자 한눈에","갈래":[{"이름":"의사와 표시가 어긋남","항목":["비진의표시(제107조) — 원칙 유효, 상대방이 알았거나 알 수 있었으면 무효","통정허위표시(제108조) — 당사자 사이에서는 언제나 무효","착오(제109조) — 중요부분 착오 + 중과실 없음이면 취소"]},{"이름":"남 때문에 비뚤어진 의사","항목":["사기·강박(제110조) — 취소, 제3자가 속였으면 상대방이 알았거나 알 수 있었을 때만"]}],"결론":"넷 다 선의의 제3자에게 대항하지 못한다"},{"종류":"참고","글":"진의 = 이런 내용의 의사표시를 하겠다는 생각(속으로 진짜 바라는 것 ✕) · 심리유보 = 진의 아닌 의사표시의 다른 이름"},{"종류":"조문","조":"제108조","글":"①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"종류":"비유","글":"통정허위표시는 둘이 짜고 치는 연극이다. 연극이니 계약은 무효지만, 연극인 줄 모르고 표를 산 관객(선의의 제3자)에게는 연극이었다고 우기지 못한다. 그 관객에게서 다시 표를 산 사람은 사정을 알았어도 보호된다(엄폐물의 법칙)."},{"종류":"비유","글":"은닉행위는 가짜 겉봉투 속 진짜 편지다. 매매로 꾸민 겉봉투는 무효여도 속에 든 증여는 유효하다."},{"종류":"비교","제목":"선의의 제3자인가 — 허위표시를 바탕으로 새 이해관계를 맺었나","머리":["허위표시","제3자 ○(보호)","제3자 ✕"],"행":[["가장매매","매수인에게서 다시 산 사람 · 가등기나 저당권을 받은 사람 · 매수인을 상대로 압류한 채권자","계약 당사자 지위를 넘겨받은 사람 · 매수인의 지위를 상속한 사람"],["가장채권(가장소비대차)","채권 양수인 · 가장채권을 가압류한 사람 · 가장채권자의 파산관재인 · 보증채무를 이행한 보증인","계약상 지위를 이전받은 사람"],["가장저당권·가장전세권","저당권 실행으로 경락받은 사람 · 가장 포기로 말소된 뒤 새 저당권자 · 가장전세권 양수인","저당권을 가장 포기했을 때의 후순위 제한물권자"],["그 밖","—","가장양도된 채권의 채무자 · 제3자를 위한 계약의 제3자 · 대리인이 허위표시했을 때의 본인"]],"결론":"허위표시 위에 새로 이해관계를 쌓은 사람이 제3자다 — 당사자 자리나 지위를 이어받은 사람은 아니다"},{"종류":"참고","글":"선의 = 그 사정을 몰랐다는 뜻(착한 마음 ✕) · 대항하지 못한다 = 그 사람에게는 무효를 내세울 수 없다 · 가장행위 = 허위표시로 꾸민 법률행위"},{"종류":"조문","조":"제109조","글":"①의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다. 그러나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. ②전항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"종류":"비교","제목":"착오 취소 — 네 관문","머리":["단계","내용"],"행":[["중요부분의 착오인가","표의자가 증명한다. 경제적 불이익이 없으면 중요부분이 아니다"],["중대한 과실이 없나","상대방이 증명한다. 상대방이 착오를 알고 이용했다면 중과실이어도 통과"],["취소를 막는 약정이 없나","착오 규정은 강행규정이 아니라서 합의로 취소권을 배제할 수 있다"],["취소","선의의 제3자에게 대항 ✕ · 3년·10년 안에 · 계약이 해제된 뒤에도 가능"]],"결론":"착오 취소로 손해를 본 상대방도 불법행위를 이유로 손해배상을 청구하지 못한다"},{"종류":"비유","글":"착오는 혼자 가격표를 잘못 읽은 것이다. 중요한 부분을 잘못 읽었고 크게 부주의하지 않았다면 물릴 수 있다. 두 사람이 똑같이 번지를 잘못 적은 경우는 착오가 아니라 오표시무해라 취소할 일이 없다."},{"종류":"참고","글":"표의자 = 의사표시를 한 사람 · 중대한 과실 = 보통 요구되는 주의를 현저히 결여한 것(크게 부주의함)"},{"종류":"조문","조":"제110조","글":"①사기나 강박에 의한 의사표시는 취소할 수 있다. ②상대방있는 의사표시에 관하여 제삼자가 사기나 강박을 행한 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 그 의사표시를 취소할 수 있다. ③전2항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"종류":"비유","글":"시세를 부풀려 말하거나 입을 다무는 것은 흥정이라 기망이 아니고, 알려야 할 사정을 숨기는 것은 속임수라 기망이다 — 단지 옆에 대규모 공동묘지가 들어서는 걸 알고도 알리지 않은 분양자가 그렇다."},{"종류":"비교","제목":"누가 속였나 — 취소할 수 있는 때","머리":["속인 사람","취소","까닭"],"행":[["상대방","언제든 ○","제110조 제1항"],["상대방의 대리인","언제든 ○","상대방과 같이 봐서 제3자가 아님"],["제3자(상대방 있는 의사표시)","상대방이 알았거나 알 수 있었을 때만 ○","제110조 제2항"],["상대방의 피용자","상대방이 알았거나 알 수 있었을 때만 ○","제3자로 볼 수 있음"]],"결론":"상대방이 과실 없이 몰랐다면 제3자의 사기를 이유로는 취소하지 못한다"},{"종류":"비유","글":"도달은 편지가 우편함에 들어간 것이다. 봉투를 뜯어 읽었는지는 묻지 않고, 정당한 이유 없이 받기를 거절해도 들어간 것으로 본다(내용을 알았는지까지 요구 ✕). 이미 부친 편지는 보낸 사람이 죽거나 제한능력자가 돼도 그대로 효력이 있다."}]},"민1-3":{"요약":"대리권의 범위와 제한, 복대리인의 지위와 책임, 무권대리에서 본인·상대방·무권대리인의 권리·책임, 표현대리 세 유형을 묻는다.","블록":[{"종류":"소제목","글":"대리권"},{"종류":"요점","등급":"B","제목":"대리권의 발생과 소멸","글":"수권행위는 방식이 필요 없는 불요식행위다. 본인의 사망, 대리인의 사망·성년후견개시·파산은 법정·임의대리 모두의 소멸사유이고, 원인된 법률관계의 종료와 수권행위의 철회는 임의대리에만 있는 소멸사유다."},{"종류":"요점","등급":"A","제목":"대리권의 범위","글":"범위를 정하지 않은 임의대리인은 보존행위(소멸시효 중단, 기한 된 채무 변제 등)는 제한 없이 할 수 있지만 처분행위(가옥 매각, 채무면제 등)는 할 수 없다. 매도인의 대리인은 중도금·잔금을 받을 수 있지만, 이미 맺은 매매계약을 해제할 수는 없다."},{"종류":"요점","등급":"A","제목":"자기계약·쌍방대리와 공동대리","글":"대리인이 본인과 자기계약을 하거나 양쪽을 다 대리하는 쌍방대리는 원칙적으로 금지되지만, 본인이 허락하면 허용된다. 대리인이 여럿이면 원칙적으로 각자 혼자 본인을 대리하고, 법률이나 약정이 있을 때만 공동대리를 한다."},{"종류":"요점","등급":"B","제목":"대리권의 남용","글":"대리권 남용행위도 원칙적으로 유권대리라 유효하다. 다만 상대방이 남용 사실을 알았거나 알 수 있었다면 비진의표시 규정(제107조 제1항)을 유추적용해 무효가 된다."},{"종류":"소제목","글":"대리행위와 효과"},{"종류":"요점","등급":"B","제목":"대리행위의 하자와 대리인의 능력","글":"대리행위의 하자 유무는 원칙적으로 대리인을 기준으로 판단한다. 대리인이 상대방을 속였다면 상대방이 취소권을 얻는다. 대리인은 행위능력자가 아니어도 되므로, 제한능력자가 대리행위를 했더라도 본인이나 법정대리인은 이를 취소하지 못한다."},{"종류":"요점","등급":"B","제목":"대리의 효과","글":"대리행위에서 생기는 법률효과는 주된 효과든 부수적 효과든 모두 본인에게 직접 귀속된다."},{"종류":"소제목","글":"복대리"},{"종류":"요점","등급":"A","제목":"복대리인의 지위와 선임","글":"복대리인은 대리인이 자기 이름으로 선임하지만 대리인의 대리인이 아니라 본인의 임의대리인이다. 대리인이 복대리인을 선임해도 대리인의 대리권은 그대로 남는다. 대리인의 능력에 따라 성패가 갈리는 사무를 맡은 사람은 본인이 묵시적으로 승낙했다는 것만으로는 복대리인을 선임할 수 없다."},{"종류":"요점","등급":"B","제목":"복대리권의 소멸","글":"복대리인의 대리권은 복대리인 자신에게 소멸사유가 생긴 때뿐 아니라, 대리인의 대리권이 소멸한 때에도 함께 소멸한다."},{"종류":"소제목","글":"무권대리"},{"종류":"요점","등급":"A","제목":"본인의 추인권","글":"본인은 상대방·전득자·무권대리인 누구에게나 추인할 수 있다. 다만 무권대리인에게 추인했다면 상대방이 그 사실을 안 때에 비로소 효력이 생기고, 그전에는 상대방이 철회할 수 있다. 일부만 하거나 내용을 바꾼 추인은 상대방이 동의하지 않는 한 무효다. 추인하면 계약은 계약 때로 소급해 유효가 되지만 제3자의 권리는 해치지 못한다."},{"종류":"요점","등급":"A","제목":"추인거절권과 무권대리인의 상속","글":"본인이 추인을 거절하면 그 행위는 본인에게 효력이 없다. 무권대리인이 본인을 상속한 뒤 본인의 지위에서 추인을 거절하는 것은 금반언 원칙에 어긋나 허용되지 않는다."},{"종류":"요점","등급":"A","제목":"상대방의 최고권·철회권","글":"최고권은 상대방의 선의·악의를 가리지 않고 쓸 수 있고, 본인이 정해진 기간 안에 확답을 발송하지 않으면 추인을 거절한 것으로 본다(발신주의). 철회권은 계약 당시 무권대리임을 몰랐던 선의의 상대방만 본인이 추인하기 전에 쓸 수 있다."},{"종류":"요점","등급":"B","제목":"무권대리인의 책임","글":"대리권을 증명하지 못하고 본인의 추인도 받지 못한 무권대리인은, 행위능력이 있는 한 상대방이 고르는 대로 계약을 이행하거나 손해를 배상(이행이익)할 책임을 진다. 상대방이 대리권 없음을 알았거나 알 수 있었다면, 또는 무권대리인이 제한능력자라면 이 책임을 지지 않는다."},{"종류":"소제목","글":"표현대리"},{"종류":"요점","등급":"A","제목":"표현대리의 성질과 성립요건","글":"표현대리가 성립해도 성질은 무권대리이지, 유권대리로 바뀌지 않는다. 그래서 유권대리를 주장했다고 표현대리 주장까지 들어 있는 것은 아니고, 표현대리가 성립해도 본인은 과실상계로 책임을 줄일 수 없다. 대리행위가 강행규정을 위반해 무효라면 표현대리도 성립하지 않는다."},{"종류":"요점","등급":"A","제목":"표현대리의 유형","글":"권한을 넘은 표현대리(제126조)와 대리권 소멸 후의 표현대리(제129조)는 둘 다 임의대리·법정대리에 모두 적용된다. 대리권이 소멸한 뒤 대리인이 선임한 복대리인이 상대방과 대리행위를 했다면 그때도 제129조의 표현대리가 성립할 수 있다."},{"종류":"비교","제목":"법정대리와 임의대리 — 대리권이 생기고 없어지는 길","머리":["구분","법정대리","임의대리"],"행":[["생기는 원인","법률 규정","본인의 수권행위(방식 제한 없음)"],["둘 다 끝나는 사유","본인 사망 · 대리인 사망 · 대리인 성년후견 개시 · 대리인 파산","본인 사망 · 대리인 사망 · 대리인 성년후견 개시 · 대리인 파산"],["임의대리만 끝나는 사유","—","원인된 법률관계 종료 · 수권행위 철회"],["범위를 정하지 않았을 때","법률이 정한 범위","보존행위 ○ · 성질을 바꾸지 않는 이용·개량 ○ · 처분 ✕"],["복대리인 선임","자기 책임으로 자유롭게","본인 승낙이나 부득이한 사유가 있을 때만"]],"결론":"대리인이 죽으면 대리권은 상속되지 않고 끝난다 — 수권행위 철회는 임의대리에만 있는 소멸 사유다"},{"종류":"비유","글":"집을 팔라고 맡긴 대리인은 팔고 돈 받아 오는 데까지다. 중도금·잔금 받기와 지급 날짜 미루기는 되지만, 대금 채무를 면제해 주거나 이미 맺은 계약을 해제하는 일은 못 한다."},{"종류":"참고","글":"수권행위 = 본인이 대리권을 주는 행위(대리인이 될 사람의 승낙은 필요 없음) · 자기계약 = 대리인이 본인을 대리해 자기와 맺는 계약 · 쌍방대리 = 한 사람이 양쪽 당사자를 다 대리하는 것"},{"종류":"조문","조":"제122조","글":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"종류":"구조","제목":"복임권과 책임 — 누가 뽑았나","갈래":[{"이름":"임의대리인","항목":["선임: 본인 승낙이나 부득이한 사유가 있을 때만","책임: 선임·감독 책임","본인이 지명해 뽑았으면: 부적임·불성실을 알고도 통지·해임을 게을리했을 때만 책임"]},{"이름":"법정대리인","항목":["선임: 자기 책임으로 자유롭게","책임: 무과실 책임","부득이한 사유로 뽑았으면: 선임·감독 책임만"]}],"결론":"본인 승낙을 받아 뽑았어도 임의대리인은 선임·감독 책임을 진다"},{"종류":"비유","글":"복대리인은 대리인이 뽑았지만 본인 명찰을 단 사람이다. 대리인의 대리인이 아니고, 뽑았다고 대리인 자리가 비지도 않는다. 다만 대리인의 대리권이 끝나면(본인 사망 등) 복대리인도 함께 끝난다."},{"종류":"비유","글":"요리사 솜씨를 믿고 맡긴 요리는 요리사가 직접 해야 한다. 대리인 능력이 성패를 가르는 일이면 본인이 말없이 넘어간 것만으로는 복대리인을 쓰지 못하고, 누가 처리해도 되는 일이면 묵시적 승낙이 있는 것으로 본다."},{"종류":"구조","제목":"무권대리 — 두 갈래","갈래":[{"이름":"협의의 무권대리","항목":["본인 — 추인권 · 추인거절권","상대방 — 최고권(선의·악의 불문) · 철회권(선의만)","무권대리인 — 제135조 이행·손해배상 책임"]},{"이름":"표현대리(본인이 책임짐)","항목":["제125조 대리권 수여 표시 — 임의대리만","제126조 권한을 넘은 대리 — 임의·법정","제129조 대리권 소멸 후 — 임의·법정"]}],"결론":"표현대리가 성립해도 성질은 무권대리다 — 본인의 추인권, 상대방의 최고권·철회권은 남고 본인의 거절권만 없다"},{"종류":"비교","제목":"무권대리 — 네 가지 권리","머리":["권리","누가","누구에게","효과·주의"],"행":[["추인","본인","상대방 · 전득자 · 무권대리인(무권대리인에게 했으면 상대방이 알기 전엔 상대방에게 내세우지 못함)","계약 때로 소급해 유효(제3자 권리는 못 해침) · 일부나 내용을 바꾼 추인은 상대방 동의가 있어야 함"],["추인 거절","본인","상대방","확정적 무효 — 다시 추인 ✕ · 상대방 최고·철회 ✕"],["최고","상대방(선의·악의 불문)","본인에게만","기간 안에 확답을 보내지 않으면 추인 거절로 봄"],["철회","선의의 상대방만","본인 또는 무권대리인","본인이 추인하기 전까지 · 철회하면 확정적 무효"]],"결론":"최고에 답이 없으면 추인이 아니라 거절이다"},{"종류":"비유","글":"무권대리 계약은 본인 서명란이 비어 있는 계약서다. 본인이 서명하면(추인) 계약한 날로 거슬러 유효가 되고, 서명을 거부하면(거절) 그대로 끝난다. 일부만 서명하거나 내용을 고쳐 서명하려면 상대방 동의가 있어야 한다."},{"종류":"비유","글":"무권대리인이 본인을 상속하면 제가 판 물건을 '본인 자격으로는 못 준다'고 뒤집는 셈이라, 추인을 거절하는 것은 신의칙(금반언)에 어긋나 허용되지 않는다."},{"종류":"참고","글":"추인 = 효력 없는 행위를 나중에 인정해 효력을 주는 의사표시 · 금반언 = 앞서 한 말이나 행동과 어긋나는 주장을 막는 원칙 · 전득자 = 상대방에게서 다시 권리를 넘겨받은 사람"},{"종류":"조문","조":"제131조","글":"대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"종류":"비유","글":"최고는 '할 거야, 말 거야?' 묻는 것이라 무권대리인 줄 알았던 상대방도 할 수 있고, 철회는 '없던 일로 하자'는 것이라 몰랐던(선의) 상대방만 할 수 있다."},{"종류":"조문","조":"제135조","글":"① 다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. ② 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 제1항을 적용하지 아니한다."},{"종류":"참고","글":"정당한 이유 = 상대방이 선의·무과실이라는 뜻 — 대리행위 당시를 기준으로 본다"}]},"민1-4":{"요약":"무효와 취소의 차이, 토지거래허가 전 유동적 무효의 법률관계, 무효행위의 추인, 취소권자·법정추인·제척기간을 묻는다.","블록":[{"종류":"소제목","글":"법률행위의 무효"},{"종류":"요점","등급":"C","제목":"전부무효와 일부무효","글":"법률행위 일부만 무효여도 원칙은 전부 무효다. 다만 그 부분이 없었어도 나머지만으로 했으리라 인정되면 나머지는 무효가 되지 않는다."},{"종류":"요점","등급":"B","제목":"유동적 무효란","글":"토지거래허가구역 안의 토지를 허가받기 전에 맺은 매매계약은 허가를 받을 때까지 무효이고(유동적 무효), 허가를 받으면 계약 때로 소급해 유효가 된다. 유동적 무효인 동안은 이행을 청구하거나 채무불이행을 이유로 해제할 수 없지만, 계약금을 준 쪽은 무효를 이유로 부당이득반환을 청구하지 못하고 매도인은 계약금 배액을 상환하고 해제할 수 있다."},{"종류":"요점","등급":"B","제목":"유동적 무효 — 협력의무","글":"허가를 전제로 계약한 당사자는 허가 절차에 협력할 의무가 있고, 협력하지 않아 손해가 생겼다면 배상을 청구할 수 있다. 다만 협력의무를 이행하지 않았다는 이유만으로 계약을 해제할 수는 없다."},{"종류":"요점","등급":"A","제목":"무효행위의 추인","글":"무효인 법률행위는 추인해도 원칙적으로 효력이 생기지 않는다. 다만 상대적 무효에서 당사자가 무효임을 알고 추인했다면 새 법률행위로 본다(제139조). 절대적 무효에는 무효행위의 추인이 인정되지 않는다. 무권리자의 처분을 권리자가 추인하면 원칙적으로 계약 때로 소급해 권리자에게 귀속된다."},{"종류":"소제목","글":"법률행위의 취소"},{"종류":"요점","등급":"B","제목":"취소권자와 상대방","글":"취소권자는 제한능력자와 착오·사기·강박으로 의사표시를 한 사람이다. 제한능력자는 법정대리인의 동의 없이도 취소권을 행사할 수 있다. 취소는 처음 의사표시를 한 그 상대방(포괄승계인·법정대리인 포함)에게 해야 하고, 상대방의 특정승계인에게는 할 수 없다."},{"종류":"요점","등급":"B","제목":"취소의 효과","글":"취소하면 처음부터 무효였던 것이 된다(소급효). 제한능력자가 취소한 경우 말고는 선의의 제3자에게 대항하지 못한다. 이미 이행한 것은 부당이득으로 반환해야 하는데, 제한능력자는 선의든 악의든 현존이익만 반환한다."},{"종류":"요점","등급":"B","제목":"취소할 수 있는 법률행위의 추인","글":"취소할 수 있는 법률행위는 취소의 원인이 끝난 뒤에 추인해야 효력이 있다. 다만 법정대리인은 원인이 끝나기 전이라도 언제든 추인할 수 있다."},{"종류":"요점","등급":"A","제목":"법정추인","글":"취소권자나 상대방이 이의 없이 전부나 일부를 이행하거나 경개·담보제공·강제집행을 하면 추인한 것으로 본다(법정추인). 이행의 청구와 취득한 권리의 양도는 취소권자가 했을 때만 법정추인 사유가 된다."},{"종류":"요점","등급":"A","제목":"취소권의 제척기간","글":"취소권은 추인할 수 있는 날부터 3년 안에, 법률행위를 한 날부터 10년 안에 행사해야 한다. 이 기간은 소멸시효기간이 아니라 제척기간이라 둘 중 하나만 지나도 취소하지 못한다."},{"종류":"비교","제목":"무효와 취소 — 한 표로","머리":["구분","무효","취소"],"행":[["처음 효력","처음부터 없음","일단 유효 → 취소하면 처음부터 무효"],["누가 주장","주장하지 않아도 당연히 효력 ✕","취소권자가 취소해야 무효"],["시간이 지나면","그대로 무효","3년·10년이 지나면 취소권 소멸 → 확정 유효"],["추인하면","원칙 효력 ✕(무효임을 알고 추인하면 새 법률행위)","확정 유효 · 법정추인도 있음"],["대표 사유","의사무능력 · 비진의(상대방 악의·과실) · 통정허위 · 원시적 불능 · 강행법규·사회질서 위반 · 불공정 · 불법조건 등","제한능력 · 착오 · 사기·강박"]],"결론":"무효는 처음부터 없는 것, 취소는 있다가 없애는 것이다"},{"종류":"참고","글":"절대적 무효 = 선의의 제3자를 포함해 누구에게나 내세우는 무효(반사회질서·불공정·강행법규 위반·의사무능력) · 상대적 무효 = 선의의 제3자에게는 내세우지 못하는 무효(비진의표시가 무효인 경우·통정허위표시)"},{"종류":"구조","제목":"토지거래허가 전 계약(유동적 무효)의 갈림길","갈래":[{"이름":"확정적 유효로","항목":["허가를 받음","허가구역 지정 해제","지정기간 만료 뒤 재지정 ✕"]},{"이름":"확정적 무효로","항목":["처음부터 허가를 배제·잠탈하려는 계약","불허가처분","양쪽이 허가신청을 하지 않기로 합의","정지조건부 매매에서 허가 전 조건 불성취 확정"]},{"이름":"유동적 무효인 동안","항목":["이행청구 ✕ · 채무불이행을 이유로 한 해제 ✕","낸 계약금의 부당이득반환청구 ✕","계약금 배액 상환 해제 ○","협력의무 이행 청구 ○ · 협력 안 해 생긴 손해배상 ○ · 협력의무 위반을 이유로 한 해제 ✕","비진의·허위표시·착오·사기·강박을 이유로 무효·취소 주장 ○"]}],"결론":"약정한 기간 안에 허가를 못 받았다는 사정만으로는 확정적 무효가 되지 않는다"},{"종류":"비유","글":"유동적 무효는 결재를 기다리는 서류다. 결재(허가)가 나면 처음 날짜로 효력이 생기고, 반려(불허가)되면 확정적으로 무효가 된다. 결재가 나기 전에는 서류대로 이행하라고 요구할 수 없다."},{"종류":"조문","조":"제139조","글":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"종류":"비교","제목":"무효를 살리는 세 길","머리":["구분","일부무효(제137조)","무효행위의 전환(제138조)","무효행위의 추인(제139조)"],"행":[["무엇","일부가 무효면 원칙은 전부 무효, 나머지만이라도 했으리라 인정되면 나머지 유효","무효인 행위가 다른 행위의 요건을 갖추면 그 다른 행위로 효력","무효임을 알고 추인하면 새 법률행위로 봄"],["기준","당사자의 가정적 의사","무효를 알았다면 다른 행위를 원했으리라는 의사","무효 원인이 끝난 뒤 · 무효임을 알고"],["효력 시점","성립 당시부터 나머지 유효","성립 당시부터 다른 행위로","추인한 때부터(소급 ✕ — 제3자 권리를 해치지 않는 범위에서 약정으로 소급 가능)"],["안 되는 것","—","—","반사회질서 · 강행법규 위반 · 불공정은 추인해도 ✕"]],"결론":"불공정한 법률행위도 전환은 되지만 추인은 안 된다"},{"종류":"비유","글":"무효행위의 추인은 깨진 약속을 고치는 게 아니라 새로 약속하는 것이라 처음으로 거슬러 가지 않는다. 반면 무권대리의 추인과 무권리자 처분의 추인은 비어 있던 서명을 채우는 것이라 계약한 때로 거슬러 간다."},{"종류":"비유","글":"취소는 처음 거래한 창구에 가서 물리는 일이다. 상대방이 물건을 딴 사람에게 넘겼어도 취소 의사표시는 원래 상대방에게 한다. 제한능력자는 법정대리인 동의 없이 혼자 물릴 수 있다."},{"종류":"참고","글":"특정승계인 = 매매·증여처럼 권리를 하나씩 넘겨받은 사람 · 포괄승계인 = 상속인처럼 권리·의무를 통째로 이어받은 사람"},{"종류":"조문","조":"제141조","글":"취소된 법률행위는 처음부터 무효인 것으로 본다. 다만, 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환(償還)할 책임이 있다."},{"종류":"비유","글":"취소는 되감기 버튼이다. 누르면 취소한 날부터가 아니라 처음부터 무효가 된다. 되돌려 줄 때 제한능력자는 선의든 악의든 남아 있는 이익만 돌려주면 된다."},{"종류":"참고","글":"현존이익 = 받은 이익 가운데 지금 남아 있는 것(유흥비로 써 버린 돈은 빠짐)"},{"종류":"조문","조":"제145조","글":"취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다. 1. 전부나 일부의 이행 2. 이행의 청구 3. 경개 4. 담보의 제공 5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 6. 강제집행"},{"종류":"구조","제목":"법정추인 여섯 사유 — 누가 하면 추인이 되나","갈래":[{"이름":"취소권자가 하든 상대방이 하든","항목":["전부나 일부의 이행","경개","담보의 제공","강제집행"]},{"이름":"취소권자가 할 때만","항목":["이행의 청구","취득한 권리의 전부나 일부 양도"]}],"결론":"취소 원인이 끝난 뒤 이의를 달지 않고 하면, 추인할 뜻이나 취소권이 있다는 인식이 없어도 추인한 것으로 본다"},{"종류":"비유","글":"추인은 반품권을 스스로 버리는 일이라 반품 사유(속음·겁먹음·제한능력)에서 벗어난 뒤에 해야 효력이 있다. 반품(취소) 자체는 강박 상태에서도 할 수 있고, 법정대리인은 언제든 추인할 수 있다."}]},"민1-5":{"요약":"조건이 붙은 법률행위의 종류별 효력과 조건을 붙일 수 없는 행위, 기한의 이익의 귀속과 상실을 묻는다.","블록":[{"종류":"소제목","글":"조건"},{"종류":"요점","등급":"B","제목":"조건의 의의","글":"조건은 법률행위의 효력이 생기거나 없어지는 것을 장래의 불확실한 사실에 걸어 두는 부관이다. 과거의 사실은 조건이 되지 못하고, 법률이 이미 요구하는 법정조건도 부관으로서의 조건이 아니다. 조건의사가 있어도 겉으로 표시하지 않았다면 조건이 아니라 법률행위의 동기일 뿐이다. 정지조건은 조건이 성취되면 효력이 생긴다."},{"종류":"요점","등급":"A","제목":"가장조건","글":"성질상 조건이 아닌 것을 가장조건이라 한다. 불법조건이 붙으면 조건만이 아니라 법률행위 전체가 무효다. 기성조건이 해제조건이면, 불능조건이 정지조건이면 그 법률행위는 무효다."},{"종류":"요점","등급":"B","제목":"조건을 붙일 수 없는 법률행위","글":"단독행위에는 원칙적으로 조건을 붙일 수 없다. 다만 상대방이 동의했거나 상대방에게 이익만 주는 단독행위(유증, 채무면제)라면 예외적으로 붙일 수 있다. 붙이면 안 되는 행위에 조건을 달았다면 조건만 떨어지는 게 아니라 행위 전체가 무효다."},{"종류":"요점","등급":"A","제목":"조건부 법률행위의 효력","글":"조건 성취가 미정인 권리의무도 일반규정에 따라 처분·상속·보존하거나 담보로 할 수 있다(제149조). 정지조건이 붙었다는 사실은 그 효과 발생을 다투는 사람이 입증한다. 조건성취의 효력은 원칙적으로 소급하지 않지만, 당사자가 특약을 맺으면 소급효를 인정할 수 있다(제147조)."},{"종류":"소제목","글":"기한"},{"종류":"요점","등급":"A","제목":"기한의 의의","글":"기한은 법률행위의 효력이나 채무의 이행을 장래에 반드시 일어날 확실한 사실에 걸어 두는 것이다. 불확정한 사실이 생긴 때를 이행기한으로 정했다면, 그 사실이 생긴 때뿐 아니라 생길 수 없게 된 때에도 기한이 도래한 것으로 본다."},{"종류":"요점","등급":"A","제목":"기한의 이익","글":"기한의 이익이 누구를 위한 것인지 분명하지 않으면 채무자를 위한 것으로 추정한다(제153조 제1항). 기한의 이익 상실특약은 특별한 사정이 없다면 형성권적 기한이익 상실특약으로 추정한다."},{"종류":"참고","글":"의제 = 실제와 달라도 법이 그렇다고 치는 것 — 불이익을 볼 사람이 신의에 반해 조건 성취를 막으면, 방해가 없었다면 이뤄졌을 때에 조건이 성취된 것으로 친다"},{"종류":"참고","글":"부관 = 법률행위에 덧붙여 그 효력을 조건이나 기한에 걸어 두는 것 · 성부 = 이뤄지느냐 마느냐 · 성취 = 조건이 된 사실이 실제로 이뤄지는 것"},{"종류":"비유","글":"정지조건은 꺼져 있다가 조건이 이뤄지면 켜지는 스위치('합격하면 차를 준다'), 해제조건은 켜져 있다가 조건이 이뤄지면 꺼지는 스위치('낙제하면 장학금을 끊는다')다. 스위치는 효력만 켜고 끌 뿐, 계약은 맺은 날 이미 성립해 있다."},{"종류":"비교","제목":"가장조건 — 정지냐 해제냐에 따라 뒤집힌다","머리":["","정지조건이면","해제조건이면"],"행":[["기성조건(이미 이뤄짐)","조건 없는 법률행위","무효"],["불능조건(이뤄질 수 없음)","무효","조건 없는 법률행위"],["불법조건","법률행위 전체 무효","법률행위 전체 무효"]],"결론":"기성·불능은 서로 엇갈리고, 불법조건은 어느 쪽이든 법률행위까지 무효다"},{"종류":"조문","조":"제151조","글":"①조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다. ②조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다. ③조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"종류":"비유","글":"단독행위에 조건을 달면 상대방만 불안한 처지에 놓인다. 그래서 원칙은 금지이고, 상대방이 동의했거나 이익만 주는 행위(유증·채무면제)만 예외다. 금지된 곳에 조건을 달면 조건만이 아니라 법률행위 전부가 무효다. 상계는 법이 조건도 기한도 붙이지 못하게 막아 두었다."},{"종류":"조문","조":"제147조","글":"①정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력이 생긴다. ②해제조건있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다. ③당사자가 조건성취의 효력을 그 성취전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다."},{"종류":"비유","글":"조건이 이뤄지면 효력은 그날부터 켜진다. 과거로 거슬러 켜려면 당사자가 따로 그 뜻을 밝혀야 하고, 기한은 그렇게 정해도 거슬러 가지 못한다."},{"종류":"비교","제목":"조건과 기한","머리":["구분","조건","기한"],"행":[["걸어 두는 사실","올지 안 올지 모름(불확실)","반드시 옴(확실)"],["효력이 생기는 쪽","정지조건 성취 → 발생","시기(효력이 생기는 기한) 도래 → 발생"],["효력이 없어지는 쪽","해제조건 성취 → 소멸","종기(효력이 사라지는 기한) 도래 → 소멸"],["소급","원칙 ✕ · 특약하면 ○","특약해도 ✕"],["처분·상속·보존·담보","○(제149조)","○(제154조)"],["그 사실이 안 일어나기로 확정되면","정지조건 불성취 → 효력이 생기지 않음","불확정기한 → 그때 기한 도래"]],"결론":"확실히 올 날에 걸면 기한, 올지 모르는 일에 걸면 조건이다"},{"종류":"비유","글":"불확정기한은 날짜만 모를 뿐 언젠가 오는 날이다. '다른 사람에게 임대하면 보증금을 돌려준다'는 약정은 새로 임대된 때는 물론, 임대가 불가능해진 때에도 돌려줄 때가 온다."},{"종류":"조문","조":"제153조","글":"①기한은 채무자의 이익을 위한 것으로 추정한다. ②기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다."},{"종류":"비유","글":"기한의 이익은 '그날까지는 안 갚아도 되는' 이익이다. 누구 것인지 분명하지 않으면 갚을 사람(채무자) 것으로 추정한다. 스스로 버릴 수는 있지만 그 때문에 상대방 이익을 해쳐서는 안 된다."},{"종류":"참고","글":"형성권적 기한이익 상실특약 = 약정한 사유가 생겨도 채권자가 '지금 갚으라'는 뜻을 밝혀야 기한 이익이 사라지는 특약 (정지조건부 특약은 사유가 생기면 곧바로 사라짐)"}]},"민2-1":{"요약":"물권의 종류와 성립 원칙(일물일권·물권법정주의), 물권적 청구권의 요건·상대방을 묻는다.","블록":[{"종류":"소제목","글":"물권의 의의와 종류"},{"종류":"비교","제목":"물권과 채권 — 무엇이 다른가","머리":["구분","물권","채권"],"행":[["권리의 모양","사람이 물건을 직접 지배(지배권)","사람이 사람에게 행위를 요구(청구권)"],["누구에게 주장하나","누구에게나(절대권)","채무자에게만(상대권)"],["배타성","있다 — 일물일권주의","없다 — 채권자평등"],["내용은 누가 정하나","법률·관습법(물권법정주의, 강행규정)","당사자(계약자유, 임의규정)"]],"결론":"배타성 덕분에 물권끼리는 먼저 성립한 쪽이, 물권과 채권 사이에서는 원칙적으로 물권이 앞선다"},{"종류":"참고","글":"1필 = 등기부에 한 필지로 올라 있는 땅 한 덩어리 · 양도담보 = 빚을 담보하려고 물건의 소유권을 채권자에게 넘겨 두는 방식"},{"종류":"요점","등급":"B","제목":"일물일권주의 예외","글":"1필 토지의 일부에도 지상권·지역권·전세권 같은 용익물권이 성립할 수 있고, 점유취득시효로 소유권을 취득할 수도 있다(다만 저당권은 1필 토지의 일부에 설정할 수 없다). 수량이 늘었다 줄었다 하는 여러 동산으로 이뤄진 집합물에도 하나의 양도담보권이 성립할 수 있다."},{"종류":"소제목","글":"물권법정주의"},{"종류":"조문","조":"제185조","글":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다."},{"종류":"비유","글":"물권법정주의 = 정해진 메뉴판이다. 메뉴를 올릴 수 있는 것은 국회가 만든 법률과 관습법뿐이라 명령·규칙으로는 새 물권을 만들지 못한다. 관습법 메뉴에 오른 것은 분묘기지권·관습법상 법정지상권·동산양도담보이고, 온천권은 메뉴에 없다(소유권의 내용일 뿐이다)."},{"종류":"요점","등급":"B","제목":"물권법정주의의 의미","글":"법률은 국회가 만든 형식적 의미의 법률만을 말하고, 명령·규칙은 여기 들어가지 않는다. 물권법이 강행법규라는 성격도 여기에 뿌리를 둔다."},{"종류":"요점","등급":"B","제목":"관습법상 물권","글":"관습법상 물권으로 인정되는 것은 분묘기지권, 관습법상 법정지상권, 동산양도담보다. 온천권은 관습법상 물권이 아니라 소유권의 내용이다."},{"종류":"요점","등급":"B","제목":"물권 내용강제","글":"법이 정한 것과 다른 내용의 물권을 임의로 만들 수 없다(내용강제). 이를 어기면 일부무효가 된다."},{"종류":"요점","등급":"C","제목":"법률규정에 의한 저당권 성립","글":"저당권도 당사자의 약정뿐 아니라 법률의 규정(예 법정저당권)으로도 성립할 수 있다."},{"종류":"요점","등급":"C","제목":"전세권·유치권과 물권법정주의","글":"전세권자가 사용·수익 권능을 완전히 배제하고 채권담보만을 위해 전세권을 설정받는 것은 물권법정주의에 반해 허용되지 않는다. 유치권은 유치물과 견련관계 있는 채권만 피담보채권으로 삼을 수 있고, 견련관계 없는 채권을 위한 유치권은 애초에 성립하지 않는다."},{"종류":"구조","제목":"물권의 종류","갈래":[{"이름":"점유권","항목":["사실상 지배 그 자체 — 부동산·동산"]},{"이름":"소유권","항목":["사용·수익·처분 전부 — 부동산·동산"]},{"이름":"용익물권(사용가치)","항목":["지상권 — 토지","지역권 — 토지","전세권 — 토지·건물"]},{"이름":"담보물권(교환가치)","항목":["유치권 — 부동산·동산·유가증권","질권 — 동산·권리","저당권 — 부동산·권리"]}],"결론":"점유권을 뺀 나머지가 본권이고, 본권에서 소유권을 뺀 용익물권·담보물권이 제한물권(타물권)이다"},{"종류":"요점","등급":"B","제목":"소유권의 처분권능·포기","글":"사용·수익 권능을 대세적·영구적으로 포기한 소유권이나 처분권능이 없는 소유권은 인정되지 않는다. 근린공원을 자유롭게 이용했다는 사정만으로 공원이용권이라는 배타적 권리가 생기지는 않는다."},{"종류":"요점","등급":"C","제목":"물건의 독립성과 명인방법","글":"1동 건물의 일부도 구분행위를 거치면 독립된 부동산이 될 수 있다. 나무에 달려 아직 안 딴 열매(미분리과실)는 명인방법을 갖추면 독립한 소유권의 객체가 되고, 벌채해 분리한 수목은 그 자체로 독립한 동산이 된다. 무단으로 경작한 농작물은 명인방법이 없어도 경작자의 소유다(판례)."},{"종류":"요점","등급":"C","제목":"물권의 객체와 경계","글":"물건이 아닌 재산권도 물권의 객체가 될 수 있다(예 권리질권). 부동산등기규칙 같은 명령·규칙으로는 물권을 창설할 수 없다. 구분건물 등기부상 전유부분의 면적 표시가 잘못됐다는 사정만으로 그 면적만큼 소유권보존등기를 말소할 수는 없다. 지적도의 경계선이 기술적 착오로 실제와 다르게 그려졌다면, 토지의 경계는 실제의 경계선을 기준으로 정한다."},{"종류":"소제목","글":"물권적 청구권"},{"종류":"요점","등급":"A","제목":"물권적 청구권의 근거와 범위","글":"물권적 청구권 규정은 점유권(제204조~제206조)과 소유권(제213조·제214조) 두 곳에 있고, 소유권에 기한 규정을 다른 물권에 준용한다. 지역권과 저당권은 목적물을 점유하지 않는 물권이라서 물권적 반환청구권이 인정되지 않는다."},{"종류":"비교","제목":"물권마다 물권적 청구권이 다르다","머리":["물권","반환청구","방해제거청구","방해예방청구"],"행":[["소유권","○(제213조)","○(제214조)","○(제214조)"],["점유권","○ — 침탈당했을 때만(제204조)","○(제205조)","○(제206조)"],["지상권·전세권","○","○","○"],["지역권·저당권","✕ — 목적물을 점유하지 않는다","○","○"],["유치권","✕","✕","✕"]],"결론":"유치권은 유치권 자체에 기한 물권적 청구권이 없다 — 점유를 빼앗기면 점유권에 기한 점유물반환청구로 되찾는다"},{"종류":"요점","등급":"A","제목":"방해제거청구권의 내용","글":"방해제거청구권은 현재 계속되고 있는 방해의 원인을 제거하는 것을 내용으로 할 뿐, 이미 벌어진 방해의 결과(손해)까지 포함하지 않는다. 방해는 개념상 손해와 구별되므로, 물권적 청구권만으로 방해제거·예방에 드는 '비용'까지 청구할 수는 없다(비용·손해의 배상은 손해배상청구권의 영역)."},{"종류":"요점","등급":"B","제목":"물권적 청구권의 성질","글":"물권적 청구권은 물권에 딸린 권리라서, 물권이 이전되거나 소멸하면 함께 이전·소멸한다. 물권과 떼어서 물권적 청구권만 양도할 수는 없다. 소유권에 기한 물권적 청구권은 소유권과 따로 소멸시효에 걸리지 않는다."},{"종류":"요점","등급":"B","제목":"물권적 청구권의 발생요건과 상대방","글":"객관적인 침해사실(현재의 사실)만 있으면 되고, 침해자에게 고의나 과실이 있을 필요는 없다. 상대방은 지금 물권을 침해하고 있거나 침해할 염려가 있는 상태를 유지하는 사람이다. 간접점유자도 상대방이 되지만, 점유보조자는 상대방이 아니다. 침해자가 그 물건을 다른 사람에게 양도했다면 상대방은 그 양수인이다."},{"종류":"요점","등급":"C","제목":"진정명의회복청구권의 성질","글":"진정명의회복을 원인으로 한 소유권이전등기청구권은 법적 성질로 보면 소유권에 기한 방해배제청구권이다."},{"종류":"요점","등급":"C","제목":"임차인의 대위행사·불법원인급여","글":"임차인은 임차목적물에 관한 임대인의 소유권에 기한 물권적 청구권을 대위행사할 수 있다. 불법원인으로 물건을 급여한 사람은 원칙적으로 소유권에 기하여 반환청구를 할 수 없다(불법원인급여)."},{"종류":"요점","등급":"C","제목":"지상권 설정 소유자의 방해배제권","글":"토지에 지상권을 설정해 주었어도 소유자의 지위는 그대로이므로, 토지 일부를 불법점유하는 사람에게 소유권에 기한 방해배제를 청구할 수 있다."},{"종류":"비유","글":"철거는 '건물을 허물 수 있는 사람'(소유자, 대금을 다 치르고 넘겨받은 미등기 매수인)에게, 퇴거는 '남의 건물에 들어앉은 사람'에게 청구한다. 무단건물에 乙 자신이 살면 철거로 함께 나가게 되므로 퇴거를 따로 청구하지 못하고, 乙의 임차인 丙에게는 철거 ✕·퇴거 ○다."},{"종류":"요점","등급":"B","제목":"무단건물 철거·퇴거 청구","글":"甲 토지에 乙이 무단으로 건물을 지었다면, 乙이 그 건물에 살 때 甲은 乙에게 건물 철거와 대지 인도를 청구할 수 있지만 퇴거는 청구할 수 없다. 乙이 丁에게 건물을 팔고 대금을 다 받아 인도했어도 미등기라면 甲은 丁에게 철거를 청구할 수 있다. 다만 미등기 상태에서 그 양수인 丁 자신은 소유권에 기한 방해배제청구권을 행사할 수 없다. 乙이 丙에게 건물을 임대했다면 철거는 乙에게, 丙에게는 철거 대신 퇴거를 청구한다."},{"종류":"요점","등급":"C","제목":"무단건물의 부당이득과 인도청구","글":"철거가 집행될 때까지 甲은 乙(또는 丁)에게 토지를 쓴 데 따른 부당이득의 반환을 청구할 수 있다. 乙이 지상권을 취득한 뒤 지은 건물을 戊가 乙의 허락 없이 점유해도, 甲은 그 건물의 소유자가 아니므로 戊에게 건물 인도를 청구할 수 없다."},{"종류":"참고","글":"간접점유자 = 남(임차인 등)을 통해 점유하는 사람, 예컨대 임대인 · 점유보조자 = 남의 지시를 받아 물건을 쥐고 있을 뿐인 사람, 예컨대 가게 점원·가정부"},{"종류":"요점","등급":"C","제목":"물권적 청구권의 특수 사례","글":"소유자는 허무인(가짜 사람) 명의로 등기한 행위자를 상대로 그 등기의 말소를 구할 수 있다. 말소등기의무자가 목적물을 처분해 등기말소청구가 이행불능이 되어도, 물권적 청구권에는 채무불이행 법리가 적용되지 않으므로 전보배상은 청구할 수 없고 불법행위책임만 물을 수 있다. 저당권자는 목적물에서 임의로 분리·반출된 물건이라도 자신에게 반환하라고 청구할 수 없다(저당권은 점유를 수반하지 않는 물권이므로)."}]},"민2-2":{"요약":"등기 없이도 물권이 바뀌는 경우, 등기청구권·중간생략등기·등기의 추정력을 묻는다.","블록":[{"종류":"소제목","글":"공시와 공신"},{"종류":"참고","글":"공시 = 권리 상태를 밖에서 알 수 있게 드러내는 것(부동산은 등기, 동산은 점유, 수목·농작물은 명인방법) · 공신 = 드러난 모습을 믿고 거래한 사람을 그대로 보호하는 것"},{"종류":"요점","등급":"C","제목":"공시의 원칙·공신의 원칙","글":"공신의 원칙은 공시를 믿은 사람을 보호해야 한다는 원칙이다. 우리 민법은 동산에만 공신의 원칙을 인정하고, 부동산에는 인정하지 않는다."},{"종류":"비유","글":"부동산 등기는 '믿어도 보장해 주지 않는 안내판'이다. 등기를 믿고 샀더라도 그 등기가 무효면 권리를 얻지 못한다. 우리 민법은 이 보장(공신의 원칙)을 동산에만 준다."},{"종류":"요점","등급":"B","제목":"등기는 효력요건이지 존속요건이 아니다","글":"등기는 부동산 물권변동의 효력이 생기기 위한 요건일 뿐, 물권이 계속 존재하기 위한 요건(존속요건)은 아니다. 등기가 불법으로 말소되더라도 물권은 소멸하지 않고, 그 말소등기에는 권리소멸의 추정력도 인정되지 않는다. 이미 적법·유효하게 등기해 소유권을 취득한 사람이 그 부동산을 점유하더라도, 사실상태를 권리관계로 끌어올려 보호할 필요가 없다면 그 점유는 취득시효의 기초가 되는 점유가 아니다."},{"종류":"비유","글":"등기는 입장권이지 체류 허가증이 아니다. 권리가 바뀔 때는 반드시 있어야 하지만, 들어온 뒤 누가 몰래 찢어 버려도(불법 말소) 권리는 그대로 남는다."},{"종류":"소제목","글":"부동산 물권변동 — 제186조·제187조"},{"종류":"조문","조":"제186조","글":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"종류":"조문","조":"제187조","글":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"종류":"비교","제목":"등기해야 바뀌나 — 제186조와 제187조","머리":["구분","제186조 법률행위","제187조 법률규정"],"행":[["대표 예","매매·증여·교환, 공유지분 포기, 공유물 협의분할, 소유권 이전을 약정한 화해조서","상속·포괄유증·합병, 공용징수(수용), 형성판결(공유물분할판결), 경매(대금 완납), 건물 신축, 법정지상권·혼동·소멸시효"],["등기","해야 물권이 바뀐다","없어도 바뀐다 — 다만 처분하려면 먼저 등기(제187조 단서)"],["예외","원인행위가 무효·취소·해제되면 등기 없이 권리가 돌아온다","점유취득시효는 법률규정인데도 등기해야 소유권을 얻는다(제245조 제1항)"]],"결론":"같은 판결이라도 이행판결은 제186조 쪽(등기 필요), 형성판결은 제187조 쪽(등기 불요)이다"},{"종류":"요점","등급":"A","제목":"법률행위에 의한 물권변동","글":"원칙적으로 법률행위로 물권변동의 효력이 생기려면 등기가 있어야 한다. 공유지분을 포기하거나 공유물을 협의로 분할한 경우에도 등기를 해야 물권변동의 효력이 생긴다. 부동산소유권을 이전하기로 하는 화해조서에 따라 소유권을 취득할 때도 등기가 필요하다. 다만 원인행위가 무효·취소되거나 해제되면 등기 없이도 물권이 원래대로 복귀한다(유인성)."},{"종류":"비유","글":"형성판결은 판사가 권리관계를 직접 바꿔 주는 판결이라 확정되는 순간 물권이 바뀐다. 이행판결은 '등기해 주라'는 명령일 뿐이라 이긴 쪽이 그 판결로 등기를 마쳐야 바뀐다."},{"종류":"요점","등급":"A","제목":"법률규정에 의한 물권변동 — 등기 불요 목록","글":"상속·포괄유증·합병 같은 포괄승계, 공용징수(수용), 형성판결(예 공유물분할판결), 경매(경락인이 대금을 완납한 때), 건물 신축, 법정지상권·혼동·소멸시효, 분묘기지권의 시효취득, 전세권의 법정갱신은 모두 등기 없이 물권을 취득한다. 반면 이행판결(예 소유권이전등기를 명하는 판결)에 따른 물권변동은 등기가 있어야 한다. 등기 없이 취득했더라도 처분하려면 먼저 등기해야 한다(제187조 단서). 재결수용이나 국세징수법상 공매도 경매처럼 등기 없이 물권을 취득한다."},{"종류":"요점","등급":"B","제목":"점유취득시효는 제187조의 예외","글":"점유취득시효는 법률규정에 의한 물권취득인데도 등기해야 소유권을 취득한다(제245조 제1항). 제187조가 정한 '등기 불요' 원칙의 유일한 예외다."},{"종류":"요점","등급":"C","제목":"가등기의 성질","글":"가등기는 채권적 청구권(장래에 확정될 것 포함)을 보전하기 위한 것이고 물권적 청구권을 보전하기 위해서는 할 수 없다. 정지조건부 청구권을 보전하는 가등기도 허용된다. 가등기된 소유권이전청구권은 가등기에 대한 부기등기의 방법으로 타인에게 양도할 수 있다. 가등기에 기한 본등기가 이뤄지면 물권변동의 효력은 본등기가 행해진 때 발생한다(가등기 시로 소급하지 않고 순위만 가등기 시로 소급한다). 가등기에 기한 본등기 절차에 의하지 않고 별도의 본등기를 받았더라도, 제3자 명의의 중간처분등기가 있다면 가등기권자는 가등기에 기한 본등기 절차의 이행을 구할 수 있다. 본등기 청구는 가등기 당시의 등기명의인을 상대로 해야 한다(그 뒤 소유자가 바뀌었어도)."},{"종류":"요점","등급":"C","제목":"존속기간 전 전세권등기·완성 전 보존등기","글":"전세권 존속기간이 시작되기 전에 마친 전세권설정등기도 원칙적으로 유효하다. 신축건물의 보존등기를 건물 완성 전에 했더라도 그 후 건물이 곧 완성되었다면 그 등기를 무효라고 볼 수 없다. 다만 종전건물의 등기를 신축건물의 등기로 유용하지는 못한다."},{"종류":"소제목","글":"등기청구권"},{"종류":"요점","등급":"B","제목":"등기청구권의 의의와 성질","글":"등기청구권은 등기권리자가 등기의무자에게 등기절차에 협력해 달라고 요구할 수 있는 실체법상 권리다. 등기권리자·등기의무자가 함께 국가에 등기를 신청하는 공법상 권리인 등기신청권과는 다르다. 매매·증여·교환 같은 법률행위나 점유취득시효 완성에 근거한 소유권이전등기청구권은 채권적 청구권이고, 법률 규정(제187조)으로 등기 없이 물권을 얻은 사람이 소유자에게 설정등기를 요구하는 경우(예 법정지상권자의 지상권설정등기청구)는 물권적 청구권이다."},{"종류":"비교","제목":"등기청구권 — 채권적인가 물권적인가","머리":["구분","채권적 청구권","물권적 청구권"],"행":[["해당하는 것","매매·증여·교환에 따른 이전등기청구권, 점유취득시효 완성에 따른 이전등기청구권","원인무효·취소·해제에 따른 말소등기청구권, 진정명의회복을 위한 이전등기청구권, 법정지상권자의 설정등기청구권"],["소멸시효","걸린다 — 단 매수인·시효완성자가 점유하는 동안은 진행하지 않는다","걸리지 않는다"]],"결론":"소멸시효는 '채권적이냐'로 먼저 가르고, 채권적이면 '지금 점유 중이냐'로 한 번 더 가른다"},{"종류":"요점","등급":"A","제목":"등기청구권의 소멸시효","글":"매수인이 목적물을 점유하고 있는 동안에는 소멸시효가 진행하지 않는다. 매수인이 목적물을 제3자에게 처분했더라도(계속 점유를 매개하는 한) 소멸시효는 진행하지 않는다."},{"종류":"비유","글":"소멸시효는 권리 위에 잠든 사람을 내버려 두지 않는 제도다. 부동산을 넘겨받아 살고 있는 매수인은 잠든 게 아니라 권리를 누리는 중이라 시효가 흐르지 않고, 인도받아 쓰다가 제3자에게 넘긴 경우도 마찬가지다. 그냥 점유를 잃었을 때만 시효가 흐른다."},{"종류":"요점","등급":"B","제목":"등기청구권의 양도","글":"점유취득시효 완성으로 생기는 소유권이전등기청구권은 통상의 채권양도 법리에 따라 양도할 수 있고(시효완성 당시 등기명의인의 동의는 필요 없다), 양도인이 등기명의인에게 통지만 해도 대항력이 생긴다. 반면 매매로 인한 소유권이전등기청구권의 양도는 특별한 사정이 없는 한 양도인(매수인)이 채무자(매도인)에게 통지만 해서는 대항력이 생기지 않고, 매도인의 동의나 승낙이 있어야 한다."},{"종류":"소제목","글":"중간생략등기"},{"종류":"요점","등급":"B","제목":"이미 마친 중간생략등기의 효력","글":"관계자 전원의 합의가 없었어도 실체관계에 맞으면 중간생략등기는 원칙적으로 유효하다. 다만 토지거래허가구역에서 최초 매도인과 최종 매수인을 당사자로 허가를 받아 마친 중간생략등기는 강행규정 위반으로 무효다. 중간생략등기 합의 자체는 적법한 등기원인이 될 수 없다."},{"종류":"비교","제목":"중간생략등기 — 甲 → 乙 → 丙","머리":["단계","내용"],"행":[["甲 → 乙 매매","최초 매도인 甲과 중간 매수인 乙의 계약은 중간생략 합의가 있어도 그대로 남는다"],["乙 → 丙 매매","甲과 최종 매수인 丙 사이에 새 매매계약이 생기지는 않는다"],["丙의 등기 청구","세 사람 모두 합의했으면 丙이 甲에게 곧장 청구하고, 합의가 없으면 乙의 등기청구권을 대위행사한다. 합의가 있어도 甲은 乙이 대금을 낼 때까지 거절할 수 있다"],["이미 마친 등기","전원 합의가 없었어도 실체관계에 맞으면 원칙적으로 유효하다"]],"결론":"예외는 토지거래허가구역 — 甲·丙을 당사자로 허가받아 마친 중간생략등기는 무효다"},{"종류":"요점","등급":"B","제목":"토지거래허가구역과 중간생략등기","글":"토지거래허가구역 안에서는 丙이 甲에게 직접 허가신청절차의 협력을 구할 수 없다. 중간생략등기는 중간 매수인이 허가제도를 피하려는 행위라서 강행규정 위반으로 무효가 되기 때문이다."},{"종류":"참고","글":"중간생략등기 합의가 있어도 최초 매도인과 중간 매수인 사이의 매매계약은 사라지지 않고, 최초 매도인과 최종 매수인 사이에 새 매매계약이 맺어지는 것도 아니다."},{"종류":"소제목","글":"등기의 추정력"},{"종류":"요점","등급":"B","제목":"등기 추정력의 의의와 범위","글":"등기가 되어 있으면 그 내용대로의 사실이 있을 것이라고 추정한다. 그래서 등기명의자는 입증책임을 벗고, 등기가 무효라고 주장하는 사람이 입증책임을 진다. 등기가 있으면 등기 절차·등기 원인·등기된 권리 세 가지가 모두 적법하다고 추정한다. 다만 등기부상 권리변동의 당사자 사이에서는 서로 이 추정력을 원용할 수 없다(당사자는 실제 사실을 이미 알고 있으므로)."},{"종류":"요점","등급":"B","제목":"등기 추정력이 깨지는 경우","글":"사망자 명의로 신청하여 이뤄진 이전등기에는 특별한 사정이 없는 한 추정력이 인정되지 않는다. 소유권이전등기의 원인으로 주장된 계약서가 진정하지 않은 것으로 증명되면 등기의 적법추정은 깨진다."},{"종류":"요점","등급":"B","제목":"등기 추정력이 미치는 범위의 세부","글":"대리에 의한 매매계약을 원인으로 소유권이전등기가 이뤄진 경우, 대리권의 존재도 추정된다. 근저당권등기가 되면 피담보채권의 존재는 추정되지만, 그 피담보채권을 성립시키는 기본계약의 존재까지 추정되지는 않는다. 건물 소유권보존등기 명의자가 전(前)소유자로부터 그 건물을 양수했다고 주장하는데 전소유자가 양도 사실을 부인한다면, 그 보존등기의 추정력은 깨진다. 점유자의 권리추정 규정(제200조)은 특별한 사정이 없는 한 부동산 물권에는 적용되지 않는다(부동산은 등기의 추정력이 그 자리를 대신한다)."},{"종류":"참고","글":"추정 = 반대 증거가 나오면 뒤집히는 잠정 판단(간주와 다르다) · 입증책임 = 증명하지 못하면 불리한 판단을 받는 부담"},{"종류":"소제목","글":"물권변동과 권리변동의 종류"},{"종류":"요점","등급":"C","제목":"권리변동의 종류 — 가벼운 확인","글":"저당권 설정은 기존 소유권 위에 새 권리를 만드는 설정적 승계이지 원시취득이 아니다. 소유권 포기는 상대방 없는 단독행위, 청약자의 승낙연착 통지는 관념의 통지, 무주물 선점은 원시취득, 무권대리에서 추인 여부 확답의 최고는 의사의 통지다."},{"종류":"요점","등급":"C","제목":"공유자의 보존행위와 시효취득 기초 점유","글":"공유부동산에 제3자 명의의 원인무효등기가 있다면, 공유자 1인이 보존행위로 그 등기 전부의 말소를 청구할 수 있다. 부동산에 관하여 적법·유효한 등기를 하여 소유권을 취득한 사람이 그 부동산을 점유하더라도, 사실상태를 권리관계로 끌어올려 보호할 필요가 없다면 그 점유는 취득시효의 기초가 되는 점유가 아니다."}]},"민2-3":{"요약":"점유의 종류와 추정, 점유자·회복자의 관계, 점유보호청구권을 묻는다.","블록":[{"종류":"소제목","글":"점유권 총설"},{"종류":"비교","제목":"간접점유자와 점유보조자","머리":["구분","간접점유자","점유보조자"],"행":[["효과","점유권이 있다. 점유보호청구권을 행사할 수 있고 물권적 반환청구권의 상대방도 될 수 있다. 다만 자력구제권은 없다","점유권이 없다. 점유보호청구권을 행사하지 못하고 물권적 반환청구권의 상대방도 되지 못한다. 다만 점유자를 위해 자력구제권은 행사할 수 있다"]],"결론":"점유권의 유무가 점유보호청구권·물권적 반환청구권의 상대방 여부를 가른다"},{"종류":"요점","등급":"B","제목":"간접점유의 성립과 특수 사례","글":"전세권·임대차 등으로 타인에게 물건을 점유하게 한 사람은 간접으로 점유권이 있다. 주택임대차보호법상 대항요건인 인도는 임차인이 간접점유를 취득하는 경우에도 인정될 수 있다. 취득시효의 기초가 되는 점유에는 간접점유도 포함된다. 직접점유자가 점유를 임의로 양도했다면 그것이 간접점유자의 의사에 반하더라도 간접점유가 침탈된 것은 아니다. 점유매개관계를 발생시킨 법률행위가 무효라도 간접점유는 인정될 수 있다. 임차인이 임대인의 동의 없이 전대했다면, 임대인과 전대인(원래 임차인) 둘 다 간접점유자가 된다."},{"종류":"요점","등급":"C","제목":"제3자의 방해와 간접점유자의 청구권","글":"제3자가 직접점유자의 점유를 방해했다면, 특별한 사정이 없는 한 간접점유자도 점유권에 기한 방해배제청구권을 행사할 수 있다."},{"종류":"소제목","글":"점유의 종류와 추정"},{"종류":"요점","등급":"C","제목":"자주점유와 타주점유","글":"점유자는 소유의 의사로 점유한다고 추정한다. 자주점유가 아니라고 주장하는 쪽이 상대방의 점유가 타주점유라는 점을 증명해야 한다. 점유자가 자주점유의 권원을 주장했지만 그 권원이 인정되지 않았다는 사정만으로는, 특별한 사정이 없는 한 자주점유의 추정이 번복되지 않는다. 다만 점유를 시작할 때 타인 소유임을 알면서도 정당한 권원 없이 무단으로 점유했다는 사실(악의의 무단점유)이 증명되면 자주점유의 추정은 깨진다. 임차인, 전세권자, 명의수탁자, 분묘기지권자, 계약형 명의신탁의 신탁자는 타주점유자다 — 점유매개관계의 직접점유자는 전형적인 타주점유자다."},{"종류":"요점","등급":"C","제목":"자주점유의 판단 사례","글":"매수한 토지의 실제 면적이 등기된 면적을 상당히 초과해도, 특별한 사정이 없으면 그 초과부분의 점유도 자주점유다. 양도인이 등기부상의 명의인과 동일인이고 그 명의를 의심할 만한 특별한 사정이 없는 경우, 그 부동산을 양수하여 인도받은 사람은 과실(過失) 없는 점유자다."},{"종류":"요점","등급":"B","제목":"선의점유와 악의점유","글":"점유자는 선의로 점유한다고 추정한다. 다만 본권에 관한 소에서 패소한 선의점유자는 그 소가 제기된 때부터 소급해 악의점유자로 본다(판결 확정 때가 아니라 소 제기 때부터)."},{"종류":"비교","제목":"점유를 가르는 두 잣대","머리":["구분","자주점유 / 타주점유","선의점유 / 악의점유"],"행":[["묻는 것","소유자처럼 지배하려는 의사가 있나","점유할 권리(본권)가 있다고 믿나"],["판단 방법","속마음이 아니라 점유를 얻게 된 권원의 성질로 겉에서 판단","본권이 없음을 알거나 의심하면 악의"],["추정","자주점유로 추정(제197조 제1항)","선의로 추정(제197조 제1항)"],["본권 소송에서 지면","판결이 확정된 때부터 타주점유","소를 제기한 때로 거슬러 악의점유(제197조 제2항)"]],"결론":"패소의 효과는 시점이 다르다 — 악의는 소 제기 때로 소급, 타주는 판결 확정 때부터"},{"종류":"조문","조":"제197조","글":"①점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다. ②선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다."},{"종류":"비유","글":"자주점유는 '내 것처럼' 쥐는 것, 선의점유는 '내 것이라고 믿고' 쥐는 것이다. 임차인은 아무리 떳떳해도 빌린 권원이라 자주점유가 못 되고, 매매가 무효인 줄 모르는 매수인은 자주점유자다."},{"종류":"참고","글":"권원 = 점유를 시작하게 된 법률상 원인(매매·임대차 등) · 본권 = 점유를 정당하게 해 주는 권리(소유권·지상권·전세권·임차권 등)"},{"종류":"소제목","글":"점유권의 효력"},{"종류":"요점","등급":"B","제목":"점유권의 추정 규정","글":"추정 규정은 셋이다 — 제197조(자주·선의·평온·공연), 제198조(전후 두 시점 점유 시 계속), 제200조(점유물 위 권리의 적법). 전후 양 시점에 점유한 사실이 있으면 그 사이 점유는 계속한 것으로 추정하고, 점유자가 다르더라도 점유의 승계가 증명되면 점유계속은 추정된다. 건물의 부지가 된 토지는 특별한 사정이 없는 한 그 건물의 소유자가 점유하는 것으로 본다."},{"종류":"소제목","글":"점유자와 회복자의 관계"},{"종류":"비교","제목":"점유물을 돌려줄 때 — 선의와 악의","머리":["구분","선의점유자","악의점유자"],"행":[["과실","가진다(제201조 제1항)","돌려주고, 써 버렸으면 대가를 보상(폭력·은비 점유도 같다) — 법정이자를 붙여 반환하고, 이자 지급이 늦어지면 지연손해금도 물어야 한다"],["멸실·훼손 책임","자주점유면 이익이 남은 만큼, 타주점유면 손해 전부","손해 전부"],["필요비","청구 가능 — 과실을 가졌다면 통상필요비는 ✕","청구 가능"],["유익비","값이 늘어난 것이 남아 있으면 회복자가 고른 금액(지출액이나 증가액), 법원이 회복자의 청구로 상당한 기간을 허여할 수 있다","같다"]],"결론":"비용 상환은 선의·악의를 가리지 않는다 — 갈리는 것은 과실과 멸실·훼손 책임이다"},{"종류":"조문","조":"제202조","글":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"종류":"비유","글":"선의점유자 = 제 밭인 줄 알고 농사지은 사람이라 거둔 열매는 가져도 된다. 대신 열매를 가졌으니 밭을 가꾸는 데 든 통상의 비용은 청구하지 못한다."},{"종류":"요점","등급":"B","제목":"과실취득권의 한계","글":"이행지체를 이유로 매매계약이 해제되었다면, 선의점유자인 매수인이라도 과실취득권을 인정받지 못한다. 은비(隱秘, 몰래 숨긴 점유)에 의한 점유자는 선의라도 과실을 취득할 권리가 없다."},{"종류":"참고","글":"과실(果實) = 물건에서 생기는 열매·차임 같은 수익으로 건물 사용이익도 여기에 준한다. 잘못을 뜻하는 과실(過失)과 다른 말이다 · 은비 = 남몰래 숨긴 점유"},{"종류":"요점","등급":"B","제목":"비용상환청구권의 행사","글":"점유자의 필요비·유익비상환청구권은 점유물을 회복자에게 반환할 때 행사하는 것이 원칙이다. 무효인 매매계약의 매수인이 목적물에 필요비 등을 지출한 뒤 매도인이 그 목적물을 제3자에게 양도했다면, 점유자인 매수인은 그 양수인(새 소유자)에게 비용상환을 청구할 수 있다."},{"종류":"소제목","글":"점유보호청구권"},{"종류":"요점","등급":"B","제목":"점유보호청구권의 주체와 상대방","글":"점유보호청구권의 주체는 점유자(직접점유자·간접점유자)이고, 점유보조자는 주체가 될 수 없다. 상대방은 지금 물건을 침해하고 있는 사람이다. 타인의 점유를 침탈한 뒤 제3자에게 다시 점유를 침탈당한 사람은 이미 점유를 잃었으므로 점유물반환청구권의 상대방이 될 수 없다."},{"종류":"비교","제목":"점유보호청구권 3종","머리":["구분","점유물반환(제204조)","점유물방해제거(제205조)","점유물방해예방(제206조)"],"행":[["언제","점유를 빼앗겼을 때(침탈) — 사기·횡령은 ✕","점유를 방해받을 때","방해받을 염려가 있을 때"],["무엇을","물건 반환 + 손해배상","방해 제거 + 손해배상","예방 또는 손해배상의 담보 — 둘 중 하나"],["누구에게","침탈자, 그 포괄승계인, 악의의 특별승계인","지금 방해하고 있는 사람","방해할 염려를 만든 사람"],["기간","침탈당한 날부터 1년","방해가 끝난 날부터 1년 · 공사는 착수 뒤 1년이 지나거나 완성되면 제거 청구 ✕","공사는 착수 뒤 1년이 지나거나 완성되면 ✕"]],"결론":"침탈자에게서 선의로 넘겨받은 사람이 끼면 그다음 사람이 악의여도 반환청구를 못 한다"},{"종류":"조문","조":"제204조","글":"①점유자가 점유의 침탈을 당한 때에는 그 물건의 반환 및 손해의 배상을 청구할 수 있다. ②전항의 청구권은 침탈자의 특별승계인에 대하여는 행사하지 못한다. 그러나 승계인이 악의인 때에는 그러하지 아니하다. ③제1항의 청구권은 침탈을 당한 날로부터 1년내에 행사하여야 한다."},{"종류":"비유","글":"침탈은 빼앗긴 것, 사기는 속아서 제 손으로 넘긴 것이다. 제 손으로 넘긴 점유는 빼앗긴 게 아니라서 점유물반환청구를 못 하고, 소유권 같은 본권으로 되찾아야 한다."},{"종류":"요점","등급":"B","제목":"방해배제청구권의 요건","글":"점유를 방해받았다면 방해자에게 고의·과실이 없어도 방해제거 및 손해배상을 청구할 수 있다."},{"종류":"참고","글":"제척기간 = 그 안에 행사하지 않으면 권리가 사라지는 기한(시효와 달리 중단이 없다) · 특별승계인 = 매매 등으로 그 물건만 넘겨받은 사람(상속인 같은 포괄승계인과 구별)"},{"종류":"요점","등급":"B","제목":"점유의 소와 본권의 소","글":"점유권에 기인한 소(점유의 소)는 본권에 관한 이유로 재판하지 못한다. 점유자가 본권을 가지고 있는지는 점유의 소의 결론에 영향을 주지 못하고, 본권 다툼은 따로 한다."},{"종류":"비유","글":"점유의 소는 '누가 쥐고 있었나'만 보는 경기 심판이다. '원래 내 것'이라는 본권 사정은 이 경기의 판정 이유가 되지 못하고, 본권 다툼은 따로 한다."}]},"민2-4":{"요약":"상린관계·취득시효·첨부(부합)와 공유·합유·총유의 법률관계를 묻는다.","블록":[{"종류":"소제목","글":"상린관계"},{"종류":"조문","조":"제219조","글":"①어느 토지와 공로사이에 그 토지의 용도에 필요한 통로가 없는 경우에 그 토지소유자는 주위의 토지를 통행 또는 통로로 하지 아니하면 공로에 출입할 수 없거나 과다한 비용을 요하는 때에는 그 주위의 토지를 통행할 수 있고 필요한 경우에는 통로를 개설할 수 있다. 그러나 이로 인한 손해가 가장 적은 장소와 방법을 선택하여야 한다. ②전항의 통행권자는 통행지소유자의 손해를 보상하여야 한다."},{"종류":"비유","글":"주위토지통행권 = 막힌 땅의 비상구다. 비상구라서 쓸 만한 통로가 이미 있으면 더 편하다는 이유로 새로 낼 수 없고, 나중에 공로가 뚫려 필요가 없어지면 사라진다. 다만 기존 통로가 제구실을 못하면 비상구가 열린다."},{"종류":"요점","등급":"B","제목":"주위토지통행권의 범위와 비용","글":"통행권의 범위는 현재 토지의 이용 상황을 기준으로 정하고, 장차 건립될 건물처럼 장래의 이용상황까지 미리 대비해 넓게 정할 수는 없다. 통로개설·유지비용은 원칙적으로 통행권자가 부담한다. 통행지 소유자가 통행에 방해되는 축조물(배수로 등)을 설치했더라도, 통행지 소유자가 그것을 철거할 의무를 지는 것은 아니다. 통행권의 성립에는 등기가 필요 없다."},{"종류":"요점","등급":"C","제목":"상린관계의 세부 규정","글":"인접지의 수목뿌리가 경계를 넘어온 때에는 임의로 제거할 수 있다(가지는 먼저 제거를 최고해야 한다). 경계에 설치된 담이 상린자의 공유라면, 상린자는 공유를 이유로 그 담의 분할을 청구하지 못한다. 경계선 부근에 건축할 때 경계로부터 반미터 이상의 거리를 두지 않았다면, 착수한 지 1년이 지났거나 건물이 완성된 뒤에는 철거를 청구하지 못하고 손해배상만 청구할 수 있다. 토지 주변의 소음이 사회통념상 수인한도를 넘지 않았다면 그 사정만으로 소유권에 기해 소음피해의 제거를 청구할 수 없다. 우물을 팔 때 경계로부터 2미터 이상의 거리를 두어야 하지만, 당사자 사이에 다른 특약이 있으면 그 특약이 우선한다. 토지소유자가 부담하는 자연유수의 승수의무는 흘러오는 물을 막지 않을 소극적 의무일 뿐, 적극적으로 그 물길을 소통시킬 의무까지 포함하지 않는다. 타인의 토지를 지나지 않으면 필요한 수도를 설치할 수 없는 토지소유자는, 그 타인의 승낙 없이도 손해를 보상하고 수도를 시설할 수 있다."},{"종류":"소제목","글":"소유권의 취득 — 취득시효"},{"종류":"비교","제목":"취득시효 4가지","머리":["구분","요건","기간"],"행":[["부동산 점유취득시효(제245조 제1항)","자주·평온·공연한 점유","20년 점유 + 등기해야 취득"],["부동산 등기부취득시효(제245조 제2항)","자주·평온·공연 + 선의·무과실(점유를 시작할 때)","소유자로 10년 등기 + 10년 점유"],["동산 장기취득시효(제246조 제1항)","자주·평온·공연한 점유","10년"],["동산 단기취득시효(제246조 제2항)","자주·평온·공연 + 선의·무과실(점유를 시작할 때)","5년"]],"결론":"선의·무과실이 붙으면 기간이 줄어든다 — 부동산 20년→10년, 동산 10년→5년"},{"종류":"조문","조":"제245조","글":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다. ②부동산의 소유자로 등기한 자가 10년간 소유의 의사로 평온, 공연하게 선의이며 과실없이 그 부동산을 점유한 때에는 소유권을 취득한다."},{"종류":"요점","등급":"B","제목":"취득시효의 객체","글":"1필 토지의 일부도 점유취득시효로 시효취득할 수 있다(다만 1필 일부에 대한 등기부취득시효는 안 된다). 일반재산(옛 잡종재산)도 시효취득할 수 있지만, 시효기간 중 계속 일반재산이어야 하고 도중에 행정재산이 되면 그 뒤로는 소유권이전등기를 청구할 수 없다. 집합건물의 공용부분은 별도로 시효취득할 수 없다. 성명불상자(이름을 모르는 사람)의 소유물도 시효취득의 대상이 될 수 있다. 이중으로 된 소유권보존등기 가운데 무효인 등기에 기초해서는 등기부취득시효가 성립할 수 없다. 시효가 완성된 때의 소유권보존등기가 무효라면, 원칙적으로 그 등기명의인을 상대로는 시효완성에 따른 소유권이전등기를 청구할 수 없다. 미등기부동산이라도 점유취득시효가 완성됐다는 사정만으로 등기 없이 소유권을 취득하지는 않는다 — 여전히 등기를 해야 소유권을 취득한다."},{"종류":"요점","등급":"B","제목":"점유취득시효의 요건과 효과","글":"자주·평온·공연한 점유는 추정되므로(제197조) 선의점유일 필요는 없다. 직접점유만이 아니라 간접점유도 시효취득의 기초가 된다. 다만 점유를 시작할 때 타인 소유임을 알면서도 정당한 권원 없이 무단으로 점유했다면(악의의 무단점유) 자주점유의 추정이 깨진다. 점유의 승계가 있으면 시효이익을 받으려는 사람은 자기 또는 전(前) 점유자의 점유개시일 가운데 원하는 날을 취득시효의 기산점으로 선택할 수 있다. 취득시효의 효력은 점유를 시작한 때로 소급해서 생긴다. 부동산에 대한 압류·가압류는 점유 자체를 빼앗는 것이 아니므로 점유취득시효를 중단시키지 않는다. 소멸시효의 중단 규정은 취득시효에도 준용하고, 소멸시효의 정지도 통설은 준용된다고 본다."},{"종류":"요점","등급":"A","제목":"점유취득시효 완성 뒤 소유자가 처분한 경우","글":"시효완성자는 그 제3자에게 등기를 청구하지 못하고, 완성 당시의 등기명의인에게 청구해야 한다. 제3자가 악의이더라도 그 소유권을 확정적으로 취득한다. 다만 제3자가 등기명의인의 처분행위에 적극 가담했다면 그 매매는 반사회질서행위로 무효다. 제3자 앞으로 등기가 된 뒤 새로 20년이 지나면, 그 등기 시를 기산점으로 2차 취득시효 완성을 주장할 수 있다. 시효완성 뒤 등기명의가 바뀌었더라도 나중에 그 소유권이 시효완성 당시의 소유자에게 되돌아오면, 시효완성자는 그 소유자에게 시효취득의 효과를 주장할 수 있다."},{"종류":"비교","제목":"점유취득시효 — 누구에게 등기를 청구하나","머리":["단계","내용"],"행":[["완성 전 소유자 변경","점유 중에 소유자가 바뀌면 시효가 완성될 때의 새 등기명의인에게 청구한다"],["20년 완성","완성 당시 등기명의인에게 이전등기청구권(채권적)이 생긴다. 점유를 이어 가는 동안은 소멸시효가 진행하지 않는다"],["완성 후 제3자에게 처분","제3자가 등기를 마치면 악의여도 대항하지 못한다. 제3자가 처분에 적극 가담했으면 반사회질서로 무효"],["제3자 등기 뒤 다시 20년","소유권이 바뀐 때를 새 기산점으로 2차 취득시효를 주장할 수 있다"]],"결론":"상대는 늘 '완성 당시의 등기명의인' — 완성 뒤에 등기를 넘겨받은 사람에게는 청구하지 못한다"},{"종류":"비유","글":"시효완성자는 '아직 등기를 못 받은 매수인'과 같은 처지다. 소유자가 먼저 남에게 팔아 등기해 주면 이중매매의 첫 매수인처럼 그 제3자에게 대항하지 못하고, 소유자가 시효 완성을 알고 처분했다면 불법행위책임(채무불이행책임 ✕)을 물을 뿐이다."},{"종류":"요점","등급":"B","제목":"취득시효 완성자의 점유와 손해배상·부당이득","글":"시효완성자의 점유는 정당한 점유이므로, 등기 전이라도 소유자는 그 점유로 인한 손해배상이나 부당이득 반환을 청구할 수 없다. 취득시효 완성 후 등기 전에 원소유자가 저당권을 설정했다면, 등기를 마친 시효취득자는 그 저당권의 부담을 그대로 안고, 피담보채무를 변제해 저당권을 소멸시켰더라도 원소유자에게 부당이득반환을 청구할 수 없다. 등기청구권을 행사한 뒤 소유자가 제3자에게 처분해 이행불능이 되었다면, 시효완성자는 소유자에게 불법행위책임은 물을 수 있지만 채무불이행책임은 물을 수 없다. 토지가 수용되어 나온 보상금에 대상청구권을 행사하려면, 이행불능(수용)이 생기기 전에 등기명의인에게 시효완성을 내세워 권리를 주장하거나 행사했어야 한다. 명의신탁 해지로 명의수탁자에서 명의신탁자로 소유권이전등기가 된 경우, 시효완성자는 특별한 사정이 없는 한 그 명의신탁자에게 시효완성을 주장할 수 없다."},{"종류":"참고","글":"평온 = 폭력을 쓰지 않은 점유 · 공연 = 숨기지 않은 점유 · 기산점 = 기간을 세기 시작하는 때"},{"종류":"소제목","글":"소유권의 취득 — 첨부"},{"종류":"비교","제목":"첨부 — 붙고 섞이고 새로 만든 물건은 누구 것인가","머리":["구분","상황","소유"],"행":[["부합(부동산+동산)","동산이 부동산에 붙음","부동산 소유자 — 동산 값이 더 커도 같다"],["부합(동산+동산)","동산끼리 붙어 떼기 어려움","주된 동산의 소유자, 주종을 가를 수 없으면 부합 당시 값의 비율로 공유"],["혼화","곡물·기름 같은 종류물이 섞여 가를 수 없음","동산 부합 규정을 준용"],["가공","남의 재료에 손을 대 새 물건을 만듦","원칙은 재료 주인, 가공으로 늘어난 값이 재료값보다 현저히 크면 가공자"]],"결론":"부동산끼리는 따로 본다 — 무단 건물·무단 농작물은 지은 사람·기른 사람 것, 무단으로 심은 나무는 땅 주인 것"},{"종류":"요점","등급":"A","제목":"부동산 사이의 부합 — 건물·농작물·수목","글":"토지와 건물끼리는 부합을 인정하지 않으므로 무단으로 지은 건물은 지은 사람 소유다. 농작물은 경작할 권원이 있었는지와 관계없이 토지에 부합하지 않고 언제나 경작자의 소유다(무단 경작도 마찬가지). 허락 없이 남의 토지에 심은 수목은 토지에 부합해 토지소유자 소유가 되지만, 토지소유자의 승낙을 받아 심은 수목(예 토지소유자와 사용대차계약을 맺은 사용차주가 심은 수목)은 심은 사람 소유로 남는다(토지 임차인의 승낙만으로는 부족하다). 건물을 증축했다면 권한 없이 증축했거나 증축부분에 독립성이 없으면 기존건물 소유자 소유가 되고, 권한 있는 사람이 증축한 독립된 부분은 증축한 사람 소유다. 지상권자가 지상권에 기하여 토지에 부속시킨 물건은 지상권자의 소유로 남는다. 경매절차에서 부합된 증축부분이 따로 평가되지 않았더라도 매수인은 그 부합물의 소유권을 함께 취득한다."},{"종류":"조문","조":"제213조","글":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"종류":"비유","글":"소유물반환은 '지금 들고 있는 사람'에게 청구한다. 빼앗아 간 사람이라도 이미 남에게 넘겨 점유를 잃었으면 상대가 아니고, 남에게 맡겨 둔 간접점유자는 상대가 된다."},{"종류":"요점","등급":"B","제목":"소유권에 기한 물권적 청구권","글":"소유물반환청구권은 법률상 정당한 권원 없이 소유물을 점유하는 사람에게 돌려 달라고 청구하는 권리다(제213조). 소유물방해예방청구권은 소유권을 방해할 염려가 있는 사람에게 방해 예방이나 손해배상의 담보를 청구하는 권리다(제214조). 점유보조자는 반환청구의 상대방이 될 수 없다 — 甲이 점유보조자 乙을 두고 점유한다면 상대방은 甲뿐이다."},{"종류":"요점","등급":"C","제목":"부동산 소유권이전등기청구권의 성질과 양도","글":"교환으로 인한 이전등기청구권은 매매와 마찬가지로 채권적 청구권이다(물권적 청구권이 아니다). 점유취득시효 완성으로 인한 이전등기청구권은 점유가 계속되는 동안은 소멸시효로 소멸하지 않는다. 매매로 인한 이전등기청구권의 양도는 특별한 사정이 없는 한 양도인(매수인)이 채무자(매도인)에게 통지만 해서는 대항력이 생기지 않고 매도인의 동의·승낙이 있어야 한다."},{"종류":"요점","등급":"C","제목":"소유권 취득의 특수 사례","글":"부동산은 무주물 선점의 대상이 아니다(주인 없는 부동산은 국유가 된다) — 무주물 선점으로 즉시 소유권을 취득하는 것은 동산뿐이다. 타인의 토지에서 발견된 매장물은 특별한 사정이 없는 한 발견자가 단독으로 소유권을 취득하지 못하고, 토지소유자와 절반씩 취득한다. 타주점유자는 자신이 점유하는 부동산의 소유권을 시효취득할 수 없다. 지적도의 경계선이 기술적 착오로 실제 경계와 다르게 그려졌다면, 토지의 경계는 실제의 경계선을 기준으로 정한다. 토지가 포락(물에 잠겨 원상복구가 불가능한 상태)되면 그 토지에 대한 종전 소유권은 소멸한다."},{"종류":"소제목","글":"공동소유 — 공유"},{"종류":"비교","제목":"공유·합유·총유 한방 비교","머리":["구분","공유","합유","총유"],"행":[["누가 가지나","지분으로 나눈 여러 사람","조합체(동업자들)","법인 아닌 사단(종중·교회 등)"],["지분 처분","자유","전원 동의","지분 없음"],["처분·변경","전원 동의","전원 동의","사원총회 결의"],["관리(임대 등)","지분 과반수","조합계약에 따름","사원총회 결의"],["보존행위","각자 단독으로","각자 단독으로","사원총회 결의"],["분할청구","언제든(5년 안의 불분할 약정 가능)","조합이 있는 동안 ✕","✕"],["종료사유","공유물 양도, 목적물 분할","합유물 양도, 조합체 해산","총유물 양도"]],"결론":"보존행위를 혼자 할 수 있는 것은 공유·합유뿐 — 총유는 보존도 총회 결의를 거친다"},{"종류":"조문","조":"제265조","글":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"종류":"비유","글":"공유물 = 여럿이 돈을 모아 산 차 한 대다. 팔거나 개조하려면(처분·변경) 모두가 찬성해야 하고, 누구에게 빌려줄지(관리)는 지분 과반수로 정하며, 고장 난 곳 수리(보존)는 한 사람이 혼자 해도 된다."},{"종류":"요점","등급":"A","제목":"공유물의 처분·변경과 관리","글":"공유물을 처분하거나 변경하려면 공유자 모두가 동의해야 한다(공유 대지 위에 건물을 새로 짓는 것도 마찬가지). 공유물의 관리(예 임대할지, 어떻게 사용할지)는 지분의 과반수로 정한다 — 딱 절반(1/2)의 지분권자는 과반수가 아니므로 단독으로 관리사항을 정하지 못한다. 반면 지분(담보제공 포함)을 처분하는 데는 다른 공유자의 동의가 필요 없다. 보존행위는 공유자 각자가 단독으로 할 수 있다."},{"종류":"요점","등급":"B","제목":"공유물 관리특약의 승계와 준공유","글":"공유자들이 공유물의 관리에 관해 정한 특약은 특별한 사정이 없는 한 그 특정승계인에게도 효력이 미친다. 다만 공유지분권의 본질적 부분을 침해하는 특약은 특정승계인에게 효력이 미치지 않는다. 개별 채권자들이 같은 기회에 하나의 부동산에 근저당권을 함께 설정받았다면, 그들은 그 근저당권을 준공유한다."},{"종류":"요점","등급":"A","제목":"공유물 무단 사용의 법률관계","글":"과반수 지분권자는 협의 없이도 공유물을 단독으로 임대할 수 있고, 그로부터 배타적 사용·수익을 허락받은 제3자의 점유는 소수지분권자와의 관계에서도 적법하다(소수지분권자는 그 제3자에게 인도나 부당이득반환을 청구할 수 없다). 반대로 소수지분권자가 협의 없이 임대했다면 과반수 지분권자는 그 임차인에게 목적물의 인도를 청구할 수 있다. 소수지분권자가 협의 없이 공유물 전부나 자기 지분을 넘는 부분을 배타적으로 점유하고 있어도, 다른 소수지분권자는 자신에게 공유물을 인도·반환하라고는 청구할 수 없다(다만 점유 배제나 방해제거는 보존행위로 청구할 수 있다). 공유물을 사용해 얻은 이익이나 무단점유자에 대한 부당이득반환청구권은 각 공유자가 지분 비율만큼만 가진다."},{"종류":"요점","등급":"B","제목":"원인무효등기와 공유자의 말소청구·시효중단","글":"공유물에 제3자 명의로 원인무효등기가 돼 있다면, 공유자 1인이 보존행위로 그 등기 전부의 말소를 청구할 수 있다. 그러나 공유자 중 1인이 자기 단독명의로 원인무효의 소유권이전등기를 한 경우에는, 그 등기명의인의 지분 범위 내에서는 유효하므로 다른 공유자는 그 지분을 제외한 나머지 부분의 말소만 청구할 수 있다(전부 말소는 못 구한다). 공유자 중 1인이 공유물 전부를 다른 공유자의 동의 없이 매도해 매수인 명의로 등기를 마쳤더라도, 매도한 공유자의 지분 범위 내에서는 그 등기가 유효하다. 공유자는 자신의 지분에 관해서도 단독으로 제3자의 취득시효를 중단시킬 수 없다(취득시효 중단은 공유자 전원이 함께 해야 효력이 있다)."},{"종류":"요점","등급":"B","제목":"공유지분의 처분·포기","글":"공유자는 다른 공유자의 동의 없이 자기 지분을 처분할 수 있다. 공유자 중 1인이 지분을 포기하거나 상속인 없이 사망하면, 그 지분은 다른 공유자들에게 각자 지분 비율대로 돌아간다(제267조) — 다만 등기를 해야 이 물권변동의 효력이 생긴다. 집합건물 공용부분의 지분은 전유부분을 따라가므로 이 규정이 적용되지 않는다."},{"종류":"요점","등급":"C","제목":"공유물분할","글":"협의분할은 공유자 전원이 참여해야 하고, 1인이라도 빠지면 무효다. 협의분할이 이뤄졌다면 재판상 분할은 청구하지 못하고, 일부 공유자가 분할 합의에 따른 등기 이전에 협조하지 않으면 이전등기청구소송으로 해결하며 새로 공유물분할소송을 제기할 수는 없다. 재판상 분할에서 현물분할을 하면서 분할을 원하지 않는 나머지 공유자들을 계속 공유로 남겨 두는 방식은 가능하지만, 분할을 원하는 분할청구자를 공유로 남기는 방식은 허용되지 않는다. 협의분할은 등기를 해야(등기가 접수된 때) 물권변동의 효력이 생기지만, 재판상 분할은 판결이 확정되면 등기 없이도 효력이 생긴다. 분할된 뒤에도 공유지분에 있던 저당권은 저당권설정자가 받은 부분으로 모이지 않고 분할 전 지분 비율대로 각 부분에 남는다. 공유물분할금지의 약정(5년 이내)은 갱신할 수 있다."},{"종류":"조문","조":"제270조","글":"공유자는 다른 공유자가 분할로 인하여 취득한 물건에 대하여 그 지분의 비율로 매도인과 동일한 담보책임이 있다."},{"종류":"요점","등급":"C","제목":"구분소유적 공유","글":"토지 일부를 특정해 매수하면서 분할 절차 대신 그 면적 비율만큼 공유지분등기를 마쳤다면, 이는 실질적으로 그 특정부분을 단독소유하는 구분소유적 공유관계다. 등기명의자는 그 특정부분을 다른 공유자의 동의 없이 자유롭게 처분할 수 있고, 그 점유는 자주점유다. 등기명의자가 자기 몫이 아닌 특정부분에 건물을 지었다면 법정지상권은 성립하지 않는다. 등기명의자는 자기 특정부분을 불법점유하는 제3자에게 공유물의 보존행위로 배제를 구할 수 있지만, 등기부상으로는 여전히 공유이므로 일반적인 공유물분할을 청구할 수는 없다."},{"종류":"소제목","글":"공동소유 — 합유·총유"},{"종류":"요점","등급":"A","제목":"합유의 의의와 처분·분할","글":"합유는 법률 규정이나 계약에 따라 여러 사람이 조합체(2인 이상이 서로 출자해 공동사업을 하려고 만든 인적 결합체)로서 물건을 소유하는 관계다. 합유지분은 합유물 전체에 미친다. 합유지분을 처분하려면 합유자 전원의 동의가 있어야 하고, 합유물의 분할은 조합체가 존속하는 한 청구하지 못한다. 부동산에 관한 합유지분의 포기는 등기를 해야 물권변동의 효력이 생긴다. 합유물의 보존행위는 합유자 각자가 할 수 있고, 원인무효 등기의 말소를 구하는 소도 합유자 각자가 제기할 수 있다."},{"종류":"요점","등급":"B","제목":"합유자 1인의 단독등기와 사망","글":"합유재산에 관하여 합유자 중 1인이 임의로 자기 단독명의의 소유권보존등기를 했다면, 합유에는 공유와 달리 지분이 따로 나뉘어 있지 않으므로 그 등기는 전부 무효다(공유와 달리 '자기 지분 범위 내 유효'가 적용되지 않는다). 합유자 중 1인이 사망하면 특약이 없는 한 그 지분은 상속인에게 넘어가지 않고, 잔존 합유자가 2인 이상이면 잔존 합유자의 합유로 귀속된다. 조합체가 해산하면 합유는 종료한다."},{"종류":"비유","글":"합유 = 동업자들의 공동 금고다. 동업이 이어지는 동안에는 내 몫만 빼 가거나(지분 처분은 전원 동의) 금고를 쪼개자고 할 수 없고, 특약이 없으면 동업자가 죽어도 그 몫은 상속인에게 넘어가지 않는다."},{"종류":"요점","등급":"C","제목":"총유물의 관리·처분과 선관주의의무","글":"법인 아닌 종중처럼 법인 아닌 사단이 소유 토지의 매매를 중개한 중개업자에게 중개수수료를 지급하기로 약정하는 것은 총유물의 관리·처분행위에 해당하지 않는다(총유물 자체의 처분이 아니라 별개의 채무부담행위이므로 사원총회 결의가 없어도 된다). 비법인사단의 사원은 단독으로 총유물의 보존행위를 할 수 없다(총유는 보존행위도 사원총회 결의를 거친다). 법률에 다른 규정이 없으면 소유권자는 자기 재산과 같은 주의만 기울이면 되고, 임차인·전세권자·유치권자·점유매개관계의 직접점유자처럼 선량한 관리자의 주의의무까지 지지는 않는다."}]},"민2-5":{"요약":"지상권은 토지 사용권과 법정지상권·관습법상 법정지상권의 성립요건을, 지역권은 요역지·승역지의 부종성·불가분성과 시효취득을 가장 많이 묻는다.","블록":[{"종류":"비교","제목":"용익물권 3종 한방 비교 — 지상권·지역권·전세권","머리":["구분","지상권","지역권","전세권"],"행":[["목적물","남의 토지(건물·공작물·수목을 소유할 목적)","남의 토지(내 토지의 편익을 위한 목적)","남의 토지·건물(농경지 ✕)"],["일부에 설정","토지 일부 ○","승역지 일부 ○ · 요역지는 1필 전부","토지·건물 일부 ○"],["대가","지료 — 요소 아님(무상 가능)","유상·무상 모두 가능","전세금 — 성립요소"],["존속기간","최단 30·15·5년, 최장 제한 없음","규정 없음(영구 가능)","최장 10년, 건물만 최단 1년"],["양도·임대 금지 특약","무효(강행규정)","요역지와 떼어 양도하는 것 자체가 안 된다","설정행위로 금지할 수 있다"],["반환청구권","○","✕ — 승역지를 점유하지 않는다","○"]],"결론":"양도금지 특약이 통하는 것은 전세권뿐, 반환청구가 안 되는 것은 지역권뿐이다"},{"종류":"소제목","글":"지상권"},{"종류":"요점","등급":"B","제목":"지상권의 성질","글":"지상권은 남의 토지를 사용하는 물권이라, 공작물이 없거나 멸실되어도 그대로 존속하고 1필지 일부에도 설정할 수 있다. 물권이므로 상속·양도할 수 있고 양도금지특약은 무효다(전세권은 설정행위로 양도금지특약을 할 수 있다는 점과 다르다)."},{"종류":"비유","글":"지상권의 몸통은 '땅을 쓰는 권리'이고 건물은 그 위에 얹힌 짐이다. 그래서 건물이 없거나 무너져도 지상권은 그대로 남는다."},{"종류":"요점","등급":"C","제목":"제305조 법정지상권","글":"대지와 건물이 같은 사람 것이었는데 건물에 전세권을 설정한 뒤 대지 소유자가 바뀌면, 그 대지의 특별승계인은 전세권설정자에게 지상권을 설정한 것으로 본다. 지료는 당사자의 청구가 있으면 법원이 정한다."},{"종류":"요점","등급":"B","제목":"관습법정지상권 대항력","글":"관습법상 법정지상권은 관습법으로 부동산 물권을 취득하는 것이라 등기 없이도 효력이 생긴다. 취득 당시의 토지소유자는 물론, 그에게서 소유권을 넘겨받은 제3자에게도 등기 없이 주장할 수 있다."},{"종류":"구조","제목":"지상권을 얻는 길","갈래":[{"이름":"약정지상권(제186조)","항목":["설정계약 + 등기"]},{"이름":"법정지상권(제187조)","항목":["제305조 — 건물에 전세권 설정 뒤 대지 소유자 변경","제366조 — 저당물 경매로 토지·건물 소유자가 갈림","가등기담보법 제10조 — 담보권 실행","입목법 제6조 — 토지와 입목 소유자가 갈림"]},{"이름":"관습법상 법정지상권","항목":["한 사람 것이던 토지·건물이 매매 등으로 갈림 + 철거 특약 없음"]},{"이름":"분묘기지권","항목":["지상권과 비슷한 관습법상 물권 — 등기 대신 봉분으로 공시"]}],"결론":"법정지상권은 등기 없이 생기지만, 남에게 처분하려면 먼저 등기해야 한다"},{"종류":"비교","제목":"법정지상권(제366조)과 관습법상 법정지상권","머리":["구분","법정지상권(제366조)","관습법상 법정지상권"],"행":[["한 사람 소유였던 때","저당권 설정 때 건물이 있고(짓던 중이라도 규모·종류를 알 수 있으면 ○) 토지와 건물이 한 사람 것","소유자가 갈릴 때 한 사람 것(처음부터 같을 필요 ✕)"],["갈라진 원인","저당물의 경매","매매·증여·강제경매·공매 등(환지처분·환매 ✕)"],["특약","포기·배제 특약을 해도 무효","철거 특약이 있으면 성립 ✕, 포기·배제 특약 가능"],["공통","미등기·무허가 건물도 ○ · 가설건축물 ✕ · 지료는 청구하면 법원이 정함","같다"]],"결론":"토지에 저당권을 설정한 뒤 지은 건물에는 저당권자가 양해했더라도 법정지상권이 생기지 않는다"},{"종류":"요점","등급":"B","제목":"지상권 이전과 등기","글":"지상권이 딸린 건물을 산 매수인은 지상권이전등기까지 해야 지상권을 취득한다. 다만 지상물이 경매된 경우 경락인은 등기 없이도 지상권을 취득한다(경매라는 법률 규정에 따른 물권변동이기 때문이다)."},{"종류":"요점","등급":"C","제목":"지상권 존속기간","글":"설정행위로 정한 존속기간은 강행규정이라 지상권자에게 불리한 약정은 무효다. 최장기간에는 규정이 없어 영구로 정해도 유효하다. 다만 이미 있는 건물을 이용하려고 설정한 지상권에는 최단존속기간 규정(제280조 제1항 제1호)이 적용되지 않는다(판례)."},{"종류":"요점","등급":"B","제목":"지상권 처분의 자유","글":"지상권의 양도·임대를 막는 특약은 효력이 없다(강행규정). 지상권에 저당권을 설정하는 것을 막는 특약도 무효다."},{"종류":"요점","등급":"C","제목":"지상물 양도와 지상권","글":"지상물을 양도했다면 종된 권리인 지상권도 함께 넘기기로 묵시적으로 합의했다고 본다. 다만 지상권을 취득하려면 따로 지상권이전등기를 해야 한다."},{"종류":"참고","글":"지료 = 지상권자가 땅을 쓰는 대가로 내는 돈으로, 지상권의 요소가 아니라서 약정이 없어도 지상권은 성립한다 · 투하자본의 회수 = 들인 돈을 양도·임대로 되찾는 것"},{"종류":"요점","등급":"A","제목":"지료 체납의 효과","글":"지료 약정은 등기해야 제3자에게 대항할 수 있다. 지료를 2년 이상 내지 않으면 지상권설정자는 지상권소멸을 청구할 수 있다(강행규정). 지료 약정이 없다면 소멸청구는 인정되지 않는다. 지료가 밀린 중에 토지소유자가 바뀌었다면, 새 소유자에 대한 연체 기간이 2년 이상이어야 소멸청구를 할 수 있다."},{"종류":"요점","등급":"B","제목":"저당목적 지상권 소멸청구","글":"토지 위의 건물·수목이 저당권의 목적이면, 지상권소멸청구는 저당권자에게 통지하고 상당한 기간이 지나야 효력이 생긴다."},{"종류":"요점","등급":"B","제목":"지상권자의 갱신청구권","글":"지상권 존속기간이 만료되면 지상권자는 계약 갱신을 청구할 수 있다(청구권일 뿐 형성권은 아니다). 설정자가 갱신을 거절하면 지상권자는 지상물매수청구권을 행사할 수 있다."},{"종류":"요점","등급":"C","제목":"지상물매수청구권","글":"위 경우 지상권설정자가 상당한 가액을 제공하며 공작물이나 수목을 사겠다고 청구하면, 지상권자는 정당한 이유 없이 거절하지 못한다(제285조 제2항)."},{"종류":"요점","등급":"B","제목":"담보지상권의 소멸","글":"저당권자가 담보가치를 지키려고 함께 설정한 지상권은, 피담보채권이 변제나 시효로 소멸하면 부종성에 따라 함께 소멸한다. 다만 제3자가 토지를 무단점유해도 지상권 침해를 이유로 임료 상당 손해배상은 청구할 수 없다."},{"종류":"요점","등급":"C","제목":"분묘기지권의 지료","글":"시효취득으로 얻은 경우가 아니면 분묘기지권이 성립한 날부터 지료를 낼 의무가 있다. 지료약정은 토지를 승계한 사람에게도 효력이 있다."},{"종류":"비유","글":"분묘기지권은 봉분이 곧 등기부다. 겉으로 봉분이 보여야 권리가 공시되므로 등기는 필요 없고, 봉분 없는 평장·암장이나 시신 없는 가묘에는 분묘기지권이 없다."},{"종류":"소제목","글":"지역권"},{"종류":"요점","등급":"B","제목":"지역권의 의의","글":"일정한 목적으로 남의 토지를 자기 토지의 편익에 이용하는 부동산 용익물권이다. 요역지는 1필의 토지 전부여야 하지만 승역지는 1필일 필요가 없어, 토지 일부에도 성립할 수 있다."},{"종류":"요점","등급":"B","제목":"지역권 이용권자","글":"요역지·승역지의 지상권자, 전세권자, 임차인 사이에서도 지역권이 인정된다."},{"종류":"요점","등급":"A","제목":"지역권의 불가분성","글":"토지공유자 1인은 자기 지분만으로 그 토지를 위한 지역권이나 그 토지가 부담하는 지역권을 소멸시키지 못한다. 공유자 1인이 지역권을 취득하면 다른 공유자도 함께 취득하고, 점유로 인한 취득시효의 중단은 지역권을 행사하는 공유자 모두에 대한 사유가 아니면 효력이 없다."},{"종류":"요점","등급":"A","제목":"지역권의 부종성","글":"지역권은 요역지와 떼어서 양도하거나 다른 권리의 목적으로 삼지 못한다. 요역지소유권에 부종해 이전하며, 이전에 지역권이전등기는 필요 없다."},{"종류":"참고","글":"요역지 = 편익을 받는 쪽 땅(내 땅) · 승역지 = 편익을 내주는 쪽 땅(남의 땅)"},{"종류":"조문","조":"제292조","글":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다. ②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"종류":"비유","글":"지역권은 요역지에 달린 옵션이다. 옵션만 떼어 팔 수 없고, 다른 약정이 없으면 요역지가 넘어갈 때 이전등기 없이 따라간다. 공유자 한 사람이 옵션을 얻으면 모두 얻고, 한 사람이 제 지분만큼 없앨 수는 없다."},{"종류":"요점","등급":"","제목":"지역권의 취득방법","글":"지역권은 보통 설정계약과 등기로 취득한다. 다만 지역권만 따로 양도할 수 없어, 요역지의 소유권이나 이용권에 딸려서만 취득할 수 있다."},{"종류":"요점","등급":"A","제목":"지역권의 시효취득","글":"지역권은 계속되고 표현된 것만 시효취득할 수 있다. 토지를 불법점유한 사람은 통행지역권을 시효취득하지 못한다(판례)."},{"종류":"비교","제목":"남의 땅을 지나가는 세 가지 권리","머리":["구분","주위토지통행권(제219조)","분할·일부양도 통행권(제220조)","통행지역권"],"행":[["성격","상린관계 — 법률이 당연히 준다","상린관계 — 법률이 당연히 준다","용익물권 — 설정계약이나 시효로 얻는다"],["등기","필요 없음","필요 없음","필요(설정계약 + 등기, 시효취득도 등기)"],["손해 보상","통행지 소유자에게 보상해야 함","보상 의무 없음","약정대로(유상·무상) · 시효취득했어도 보상해야 함(판례)"]],"결론":"보상 없이 지나가는 것은 분할·일부양도로 막힌 땅뿐이고, 그 땅을 산 사람에게는 무상통행권이 넘어가지 않는다"},{"종류":"참고","글":"계속되고 표현된 = 끊기지 않고 이어지며 밖에서 보이는 것 — 통행지역권이면 스스로 통로를 내서 다니는 것(판례)"},{"종류":"요점","등급":"B","제목":"지역권 존속기간","글":"민법에 지역권 존속기간에 관한 명문 규정이 없다. 영구무한으로 설정해도 유효하다."},{"종류":"요점","등급":"A","제목":"지역권자의 권리","글":"지역권에 기한 물권적 청구권 가운데 반환청구권은 인정되지 않는다(승역지를 점유하지 않으므로). 승역지 소유자는 지역권에 필요한 부분의 토지소유권을 지역권자에게 위기(포기해 넘김)하고 그 부담에서 벗어날 수 있다."},{"종류":"요점","등급":"C","제목":"승역지 소유자의 공작물 사용","글":"승역지 소유자는 지역권의 행사를 방해하지 않는 범위에서 지역권자가 설치한 공작물을 사용할 수 있다. 다만 이익을 받는 비율로 그 공작물의 설치·보존 비용을 분담해야 한다."}]},"민2-6":{"요약":"전세권은 성립요소인 전세금과 존속기간·법정갱신, 소멸 시 동시이행관계를 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"전세권의 성립"},{"종류":"요점","등급":"A","제목":"전세금 지급의 의미","글":"전세금 지급은 전세권이 성립하기 위한 요소다. 기존채권으로 전세금 지급을 대신할 수도 있다."},{"종류":"조문","조":"제303조","글":"①전세권자는 전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다. ②농경지는 전세권의 목적으로 하지 못한다."},{"종류":"요점","등급":"C","제목":"전세권의 성립요건","글":"설정계약과 전세금 지급, 전세권등기로 취득한다. 부동산을 인도하는 것은 전세권의 성립요소가 아니다."},{"종류":"요점","등급":"B","제목":"채권담보목적 전세권","글":"채권담보를 목적으로 전세권을 설정등기해도 사용·수익권능을 배제하지 않았다면 유효하다. 사용·수익권능을 영구히 배제했다면 무효다."},{"종류":"소제목","글":"전세권의 존속기간"},{"종류":"조문","조":"제312조","글":"①전세권의 존속기간은 10년을 넘지 못한다. 당사자의 약정기간이 10년을 넘는 때에는 이를 10년으로 단축한다. ②건물에 대한 전세권의 존속기간을 1년 미만으로 정한 때에는 이를 1년으로 한다. ④건물의 전세권설정자가 전세권의 존속기간 만료전 6월부터 1월까지 사이에 전세권자에 대하여 갱신거절의 통지 또는 조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"종류":"요점","등급":"B","제목":"전세권 존속기간","글":"최장기간은 토지전세권·건물전세권 모두 10년이다. 최단기간은 건물전세권만 1년이고, 토지전세권에는 없다."},{"종류":"요점","등급":"C","제목":"토지전세권자의 지상물매수청구권","글":"토지전세권도 존속기간이 만료되면 지상권 규정을 준용해 지상물매수청구권이 인정된다."},{"종류":"요점","등급":"A","제목":"건물전세권의 법정갱신","글":"존속기간 만료 6개월 전부터 1개월 전까지 전세권설정자가 전세권 소멸 등을 통지하지 않으면, 앞선 전세권과 같은 조건으로 다시 설정한 것으로 본다(다만 존속기간은 정하지 않은 것으로 본다). 법률 규정에 따른 물권변동이라 갱신등기가 필요 없고, 전세권자는 등기 없이도 전세권설정자나 목적물을 취득한 제3자에게 권리를 주장할 수 있다(판례)."},{"종류":"요점","등급":"C","제목":"존속기간 미약정 시 소멸통고","글":"당사자는 언제든 상대방에게 전세권 소멸을 통고할 수 있다. 상대방이 통고를 받은 날부터 6개월이 지나면 전세권은 소멸한다."},{"종류":"요점","등급":"C","제목":"전세권 설정등기의 효력 시점","글":"합의한 존속기간이 시작되기 전에 전세권설정등기가 마쳐졌더라도, 특별한 사정이 없는 한 그 등기는 유효한 것으로 추정된다."},{"종류":"소제목","글":"전세권의 효력"},{"종류":"요점","등급":"B","제목":"전세권자의 관리의무","글":"전세권자는 목적물의 현상을 유지하고 통상의 관리에 해당하는 수선을 해야 한다."},{"종류":"비유","글":"전세권자는 집을 제 것처럼 쓰는 대신 통상의 수선도 스스로 맡는다. 그래서 필요비는 청구하지 못하고 유익비만 청구한다 — 수선을 임대인이 맡는 임차인이 필요비를 청구하는 것과 반대다."},{"종류":"요점","등급":"B","제목":"건물전세권과 지상권·임차권","글":"남의 토지 위 건물에 전세권이 설정되면 그 효력은 건물 소유를 목적으로 한 지상권이나 임차권에도 미친다. 전세권설정자는 전세권자의 동의 없이 그 지상권·임차권을 소멸시키는 행위를 하지 못한다."},{"종류":"요점","등급":"C","제목":"건물전세권과 법정지상권(제305조)","글":"대지와 건물이 같은 사람 것이었는데 건물에만 전세권을 설정해 사용·수익하던 중 대지 소유권만 바뀌었다면, 그 특별승계인은 전세권설정자(건물소유자)에게 지상권을 설정해 준 것으로 본다."},{"종류":"요점","등급":"C","제목":"전세금반환채권의 분리양도","글":"전세권이 존속하는 동안에는 전세금반환채권과 떼어서 전세권만 따로 양도하지 못한다. 존속하는 중에는, 장래 전세권이 소멸하면 채권이 생긴다는 것을 조건으로 한 장래의 조건부 채권만 양도할 수 있다."},{"종류":"비유","글":"전세권은 '쓰는 권리'와 '전세금을 먼저 돌려받는 권리'가 한 몸인 권리다. 그래서 전세권이 살아 있는 동안에는 전세금반환채권과 떼어 전세권만 넘길 수 없고, 장래 소멸을 조건으로 한 채권만 따로 넘길 수 있다."},{"종류":"요점","등급":"B","제목":"목적물 양도와 전세권설정자 지위","글":"전세권 존속기간 중 목적물의 소유권이 양도되면 양수인이 전세권설정자의 지위를 승계한다. 그래서 존속기간 만료 후에는 종전 소유자가 아니라 양수인에게 전세금 반환을 청구해야 한다."},{"종류":"요점","등급":"C","제목":"전전세·임대의 책임","글":"전세권자는 전전세나 임대를 하지 않았더라면 피할 수 있었던 불가항력으로 인한 손해에 대해서도 책임을 진다."},{"종류":"소제목","글":"전세권의 소멸"},{"종류":"요점","등급":"B","제목":"전세권 소멸 후 남는 권리","글":"존속기간 만료로 전세권이 소멸하면 용익물권적 권능은 없어지지만, 전세금을 돌려받을 때까지의 담보물권적 권능(우선변제권 등)은 남는다. 그래서 존속기간이 지나면 전세금반환채권도 확정되어 자유롭게 양도할 수 있다."},{"종류":"요점","등급":"C","제목":"전세권설정자의 소멸청구","글":"전세권자가 의무를 위반한 경우, 전세권설정자는 전세권소멸을 청구할 수 있다(형성권)."},{"종류":"요점","등급":"B","제목":"소멸 시 동시이행관계","글":"전세금 반환과, 목적물 반환 및 전세권말소등기에 필요한 서류 교부는 동시이행관계다."},{"종류":"요점","등급":"B","제목":"건물 일부 전세권의 경매청구","글":"전세권설정자가 전세금 반환을 지체하면 전세권자는 경매를 청구할 수 있다. 다만 건물 일부에 설정된 전세권이면, 전세권의 목적이 아닌 나머지 부분에 대해서는 우선변제권은 별론으로 하고 경매신청권이 없다."}]},"민2-7":{"요약":"유치권은 성립요건(견련성·변제기·적법한 점유)과 경매권은 있어도 우선변제권은 없다는 점을 가장 많이 묻는다.","블록":[{"종류":"비교","제목":"유치권 vs 저당권 한방 비교","머리":["구분","유치권","저당권"],"행":[["성립","법이 정한 요건을 갖추면 당연히 생긴다(법정담보물권)","설정계약 + 등기(약정담보물권)"],["등기","필요 없다(부동산도)","해야 효력이 생긴다"],["점유","유치권자가 점유해야 하고, 잃으면 소멸","설정자가 계속 점유(점유를 넘기지 않는다)"],["목적물","남의 물건(동산·부동산)·유가증권","부동산·지상권·전세권(토지 일부·건물 일부·지역권 ✕)"],["우선변제권","없다 — 경매는 돈으로 바꾸기 위한 것일 뿐","있다"],["물상대위","✕","○"],["경매 뒤 경락인에게","소멸하지 않고 인도를 거절할 수 있다(변제 청구는 ✕)","경매로 소멸"]],"결론":"유치권은 '안 돌려주고 버티는 힘', 저당권은 '먼저 받아 가는 힘'이다"},{"종류":"소제목","글":"유치권 서설"},{"종류":"요점","등급":"A","제목":"담보물권의 공통 특성(통유성)","글":"담보물권은 부종성(피담보채권이 소멸하면 함께 소멸, 근저당권은 완화)·수반성(피담보채권이 이전되면 함께 이전)·불가분성(채권 전부를 변제받을 때까지 목적물 전부에 효력)·물상대위성(목적물이 멸실·훼손·공용징수 등으로 바뀐 화재보험금·손해배상금·수용보상금 등에도 효력, 지급 전에 압류해야 함. 단, 협의취득에 따른 보상금은 제외)을 갖는다. 유치권에는 물상대위성이 인정되지 않는다."},{"종류":"참고","글":"피담보채권 = 담보가 지켜 주는 채권 · 물상대위 = 담보물이 없어지며 생긴 돈(보험금·손해배상금·수용보상금)으로 담보를 옮겨 거는 것 · 압류 = 그 돈을 채무자가 받아 가지 못하게 묶어 두는 것"},{"종류":"소제목","글":"유치권의 성립"},{"종류":"조문","조":"제320조","글":"①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다. ②전항의 규정은 그 점유가 불법행위로 인한 경우에 적용하지 아니한다."},{"종류":"비유","글":"유치권 = 수리공이 수리비를 받을 때까지 차를 내주지 않는 권리다. 내주지 않는 것이 핵심이라 먼저 받아 갈 힘(우선변제권)은 없고, 차를 내주면(점유 상실) 권리도 사라진다."},{"종류":"요점","등급":"B","제목":"유치권의 불가분성 사례","글":"다세대주택 여러 세대의 공사를 마친 수급인이 공사대금 잔액을 받으려고 그중 한 세대만 점유해 유치권을 행사해도, 그 유치권은 한 세대 몫이 아니라 다세대주택 전체 공사대금채권의 잔액 전부를 피담보채권으로 해서 성립한다."},{"종류":"요점","등급":"B","제목":"미완성 건물과 유치권","글":"건물신축공사를 도급받은 수급인이 토지에 정착물을 설치했지만 사회통념상 독립한 건물에 이르지 못한 채 공사가 멈췄다면, 그 토지에는 유치권을 행사할 수 없다."},{"종류":"구조","제목":"유치권 성립요건 5가지","갈래":[{"이름":"① 목적물","항목":["남의 물건(동산·부동산)이나 유가증권 — 채무자 것이 아니어도 된다","수급인이 제 재료로 지은 독립 건물은 제 것이라 ✕"]},{"이름":"② 견련성","항목":["그 물건에 관하여 생긴 채권 — 수선비·필요비·유익비·물건 하자로 인한 손해배상 ○","보증금·권리금·부속물매수청구권·건축자재 대금 ✕"]},{"이름":"③ 변제기","항목":["채권이 변제기에 있어야 한다 — 그 전에는 그냥 점유일 뿐"]},{"이름":"④ 적법한 점유","항목":["직접·간접점유 모두 ○ — 채무자가 직접점유하는 간접점유는 ✕","불법점유 ✕"]},{"이름":"⑤ 배제 특약 없음","항목":["원상복구 특약은 비용상환청구권 포기로 보아 ✕"]}],"결론":"하나라도 빠지면 유치권은 생기지 않는다"},{"종류":"요점","등급":"B","제목":"견련성 있는 채권","글":"물건의 수선료채권, 목적물에 들인 비용(필요비·유익비)의 상환청구권, 물건의 하자로 생긴 손해배상청구권은 유치권의 피담보채권이 될 수 있다. 채권과 점유 사이에는 견련관계가 필요 없고, 점유하는 중에 채권이 생겨야 하는 것도 아니다."},{"종류":"비유","글":"'그 물건에서 생긴 돈'만 유치권을 만든다. 수리비·비용은 그 건물에 들어간 돈이라 ○, 보증금·권리금은 임대차 계약에서 생긴 돈이라 ✕다."},{"종류":"요점","등급":"A","제목":"견련성 없는 채권","글":"임차인의 보증금채권과 권리금채권은 유치권의 피담보채권이 될 수 없다."},{"종류":"요점","등급":"A","제목":"변제기 요건","글":"피담보채권이 변제기에 있어야 유치권이 성립한다. 변제기가 오기 전에는 그냥 점유일 뿐이다."},{"종류":"요점","등급":"A","제목":"적법한 점유 요건","글":"직접점유든 간접점유든 상관없지만, 채무자가 직접점유하고 채권자가 간접점유하는 경우에는 유치권이 인정되지 않는다. 불법점유로도 유치권은 인정되지 않는다."},{"종류":"요점","등급":"C","제목":"점유의 적법성 추정","글":"유치권자가 스스로 자기 점유가 불법행위로 인한 것이 아님을 증명할 필요는 없다. 점유가 불법행위로 인한 것이라는 사실은 상대방이 증명해야 한다."},{"종류":"소제목","글":"유치권의 효력과 소멸"},{"종류":"요점","등급":"B","제목":"유치권의 대항력","글":"부동산 경매(강제경매·임의경매)에서 경락인이 유치물에 관한 채권을 변제하지 않으면, 유치권자는 경락인에게도 인도를 거절할 수 있다(다만 경락인에게 변제를 청구할 수는 없다). 경매개시결정이 난 뒤에 성립한 유치권으로는 경락인에게 대항하지 못한다."},{"종류":"요점","등급":"C","제목":"유치권과 저당권·가압류의 우선순위","글":"유치권은 저당권이나 가압류보다 나중에 성립했더라도, 압류(경매개시결정)의 효력이 생기기 전에만 성립했으면 그 매수인에게 대항할 수 있다. 저당권·가압류와 유치권 사이에는 성립 순서를 따지지 않는다."},{"종류":"비유","글":"유치권자는 경락인에게 '돈 받기 전엔 못 비킨다'고 버틸 수는 있어도 '돈을 달라'고 청구할 수는 없다. 경매개시결정 뒤에 생긴 유치권이면 버티지도 못한다."},{"종류":"요점","등급":"A","제목":"유치권자의 경매권","글":"유치권자가 하는 경매는 우선변제를 받으려는 것이 아니라, 물건을 돈으로 바꾸기 위한 환가 경매다. 유치권자에게 경매권은 있지만 우선변제권은 없다."},{"종류":"요점","등급":"C","제목":"유치권자의 과실수취권","글":"유치권자는 유치물의 과실인 금전을 수취하여 다른 채권보다 먼저 자기 채권의 변제에 충당할 수 있다(제323조)."},{"종류":"참고","글":"경락인 = 경매에서 목적물을 사들인 사람(매수인) · 간이변제충당 = 정당한 이유가 있을 때 감정인 평가대로 유치물을 직접 변제에 충당해 달라고 법원에 청구하는 것 · 선관주의 = 그 일을 맡은 보통 사람에게 기대되는 정도의 주의"},{"종류":"요점","등급":"C","제목":"유치물 사용권","글":"보존에 필요한 범위이거나 채무자가 승낙한 경우에만 유치물을 사용·대여하거나 담보로 제공할 수 있다. 보존에 필요한 사용으로 얻은 이익은 부당이득으로 반환해야 한다(공사대금채권으로 유치권을 행사하는 사람이 그 주택에 사는 것은 보존을 위한 사용이다). 유치권자에게서 유치물 보관을 맡은 사람은 소유자의 반환청구를 거절할 수 있다(판례)."},{"종류":"요점","등급":"B","제목":"유치권자의 선관주의의무","글":"유치권자는 선량한 관리자의 주의를 기울여 유치물을 점유해야 한다."},{"종류":"요점","등급":"C","제목":"유치권과 소멸시효","글":"유치권을 행사하고 있어도 피담보채권의 소멸시효 진행이 막히지 않는다(제326조). 다만 유치권만 따로 소멸시효에 걸리지는 않는다."},{"종류":"요점","등급":"B","제목":"점유 상실과 유치권","글":"점유를 잃으면 유치권은 소멸한다. 다만 점유를 빼앗겼다가 점유물반환청구권으로 되찾았다면 점유를 잃지 않았던 것으로 본다. 유치권자가 점유를 침탈당했을 때 점유반환청구권은 1년 안에 행사해야 하지만, 유치권 침해로 인한 손해배상청구권까지 1년 안에 행사해야 하는 것은 아니다."},{"종류":"요점","등급":"C","제목":"여러 유치물의 일부 소멸청구","글":"여러 유치물 가운데 일부에만 소멸청구 사유가 생겼다면, 나머지 유치물에 대해서까지 소멸을 청구할 수는 없다."}]},"민2-8":{"요약":"저당권은 효력이 미치는 범위(부합물·과실·물상대위)와 일괄경매청구권, 근저당권의 확정 시기를 가장 많이 묻는다.","블록":[{"종류":"비유","글":"저당권 = 집에 붙여 두는 '우선 번호표'다. 집주인은 계속 살고(점유 이전 ✕), 저당권자는 경매 때 번호표 순서대로 먼저 받아 간다. 집을 가져간 게 아니므로 방해 제거는 청구해도 자기에게 돌려 달라고는 못 한다."},{"종류":"소제목","글":"저당권의 성립"},{"종류":"요점","등급":"B","제목":"저당권설정자","글":"저당권설정자는 피담보채권의 채무자뿐 아니라 제3자(물상보증인)도 될 수 있다. 저당권설정자에게는 목적물을 처분할 권리나 권능이 있어야 한다."},{"종류":"참고","글":"물상보증인 = 남의 빚을 위해 제 재산에 저당권을 설정해 준 사람 · 저당권설정자 = 저당권을 설정해 준 사람(채무자나 물상보증인)"},{"종류":"요점","등급":"B","제목":"저당권의 목적물","글":"부동산, 지상권, 전세권이 저당권의 목적물이 된다(전세권처럼 1필 토지·1개 건물의 일부에는 설정할 수 없다). 저당권은 등기해야 효력이 생긴다."},{"종류":"요점","등급":"C","제목":"피담보채권의 종류","글":"피담보채권의 종류에는 제한이 없다. 금전채권이 아니어도 되고, 장래의 채권이나 조건부 채권이어도 괜찮다."},{"종류":"소제목","글":"저당권의 효력"},{"종류":"요점","등급":"B","제목":"피담보채권의 범위","글":"이자는 등기해야 피담보채권의 범위에 들어간다. 지연이자는 원본의 이행기일이 지난 뒤 1년분까지만 담보되고(후순위 권리자나 제3취득자를 보호하려는 것), 저당권 실행비용과 함께 등기하지 않아도 피담보채권의 범위에 들어간다."},{"종류":"조문","조":"제360조","글":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"종류":"요점","등급":"A","제목":"부합물·종물에 대한 효력","글":"부합한 시기와 관계없이 저당권의 효력이 부합물에 미친다. 다만 다른 약정을 했거나 법률에 특별한 규정이 있으면 부합물에 저당권 효력이 미치지 않게 할 수 있다. 저당부동산에 종된 권리에도 유추적용되어, 건물에 설정된 저당권의 효력은 그 건물 소유를 목적으로 한 지상권이나 토지임차권에도 미친다."},{"종류":"요점","등급":"A","제목":"과실에 대한 효력","글":"저당부동산이 압류된 뒤에 저당권설정자가 그 부동산에서 거둔 과실(임대차계약에 따른 차임채권도 과실로 본다)이나 거둘 수 있는 과실에는 저당권의 효력이 미친다."},{"종류":"요점","등급":"B","제목":"물상대위","글":"저당 목적물이 멸실·훼손·공용징수되어 생긴 금전 기타 대체물(화재보험금·손해배상금·수용보상금 등)이 지급되기 전에, 저당권자는 이를 압류해 물상대위할 수 있다. 압류는 저당권자가 직접 하지 않고 제3자가 해도 괜찮다. 다만 협의취득에 따른 보상금에는 물상대위권을 행사할 수 없다."},{"종류":"요점","등급":"B","제목":"일괄경매청구권(제365조)","글":"토지에 저당권이 설정된 뒤 저당권설정자가 그 위에 건물을 지었다면, 저당권자는 토지와 함께 건물도 경매하라고 청구할 수 있다. 저당권설정자에게서 저당토지의 용익권을 설정받은 사람이 건물을 지었더라도, 그 뒤 저당권설정자가 소유권을 취득했다면 마찬가지다. 다만 우선변제적 효력은 건물에는 미치지 않아, 저당권자는 토지 경매대금에서만 우선변제를 받는다."},{"종류":"비교","제목":"법정지상권(제366조)과 일괄경매청구권(제365조)","머리":["구분","법정지상권(제366조)","일괄경매청구권(제365조)"],"행":[["저당권 설정 때 건물","있어야 한다","없어야 한다(나대지에 설정)"],["건물 소유","설정 당시 토지와 건물이 한 사람 것","설정자가 건물을 지었거나, 설정자에게서 용익권을 받은 사람이 지은 뒤 설정자가 소유권을 얻었을 것"],["효과","건물 소유자가 토지에 지상권을 얻는다","저당권자가 토지와 건물을 함께 경매 청구 — 건물 값에서는 우선변제 ✕"]],"결론":"일괄경매는 저당권자의 선택이다 — 토지만 경매할 수도 있다"},{"종류":"요점","등급":"C","제목":"제3취득자의 지위","글":"저당권이 설정된 뒤에도 목적물을 양도하거나 그 위에 지상권·전세권을 설정할 수 있다. 이때 소유권 양수인, 지상권자, 전세권자 등을 제3취득자라고 한다. 후순위 저당권자는 제3취득자가 아니다. 제3취득자도 경매인이 될 수 있다."},{"종류":"요점","등급":"C","제목":"제3취득자의 변제범위","글":"제3취득자는 일반저당권이면 지연이자를 1년분까지만, 근저당권이면 채권최고액까지만 변제하면 저당권을 소멸시킬 수 있다."},{"종류":"요점","등급":"A","제목":"제3취득자의 비용상환청구권","글":"저당물의 제3취득자가 그 부동산을 보존·개량하려고 필요비나 유익비를 썼다면, 저당물의 경매대가에서 우선상환을 받을 수 있다."},{"종류":"요점","등급":"B","제목":"공동저당(제368조)","글":"같은 채권을 담보하려고 여러 부동산에 저당권을 설정한 경우, 동시에 배당하면 각 부동산의 경매대가에 비례해 채권을 나눠 배당한다(동시배당). 일부 부동산의 대가를 먼저 배당해 그 채권 전부를 변제받으면, 그 부동산의 후순위저당권자는 선순위자가 동시배당이었다면 다른 부동산에서 받았을 금액 한도에서 선순위자를 대위해 저당권을 행사할 수 있다(이시배당)."},{"종류":"소제목","글":"저당권의 처분과 소멸"},{"종류":"요점","등급":"A","제목":"저당권의 처분 제한과 부종성","글":"저당권만 담보된 채권과 떼어서 남에게 양도하거나 다른 채권의 담보로 삼지 못한다. 피담보채권이 변제·시효완성 등으로 소멸하면 저당권도 함께 소멸한다(부종성)."},{"종류":"소제목","글":"근저당권"},{"종류":"조문","조":"제357조","글":"①저당권은 그 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 이를 설정할 수 있다. 이 경우에는 그 확정될 때까지의 채무의 소멸 또는 이전은 저당권에 영향을 미치지 아니한다. ②전항의 경우에는 채무의 이자는 최고액 중에 산입한 것으로 본다."},{"종류":"요점","등급":"A","제목":"근저당권의 특성","글":"근저당권은 장래에 늘었다 줄었다 하는 불특정 다수의 채권을 최고액까지 담보한다는 점에서 보통 저당권과 다르다. 그 효력은 최고액 범위 안에서 채권액 전체(이자 포함)에 미치고, 최고액을 넘지 않는다면 1년분을 넘는 지연이자도 담보된다. 이자가 최고액에 산입된 것으로 보므로 따로 등기할 필요가 없다."},{"종류":"비유","글":"근저당 = 한도가 정해진 마이너스 통장이다. 한도(채권최고액) 안에서 빚이 오르내리고, 잔액이 잠시 0이 되어도 통장(근저당권)은 닫히지 않으며, 이자도 한도 안에 들어간다."},{"종류":"요점","등급":"B","제목":"근저당권의 부종성 완화","글":"근저당권은 소멸 면에서 부종성이 요구되지 않아, 피담보채권이 잠시 없어지더라도 근저당권은 소멸하지 않는다. 피담보채권이 확정되기 전이라면 채무의 범위나 채무자를 바꿀 수 있다."},{"종류":"요점","등급":"A","제목":"근저당권의 확정 시기","글":"설정계약에서 정한 결산기가 오거나, 존속기간이 있으면 그 기간이 끝나거나, 기본계약이 해지되는 등으로 피담보채권이 확정된다. 근저당권자가 채무불이행을 이유로 경매를 신청하면 신청 시에 확정되지만, 후순위 권리자가 경매를 신청했다면 선순위 근저당권은 경락대금이 완납될 때 확정된다."},{"종류":"비교","제목":"근저당 — 설정에서 확정까지","머리":["단계","내용"],"행":[["설정","최고액과 채무자를 등기한다. 이자는 최고액에 들어 있으므로 따로 등기하지 않는다"],["확정 전","채권이 늘고 줄며, 잠시 0이 되어도 근저당권은 남는다. 최고액·채무자·채무 범위를 바꿀 수 있다. 개별 채권을 넘겨도 근저당권은 따라가지 않는다"],["확정","결산기 도래·존속기간 만료·기본계약 해지, 근저당권자의 경매신청(신청 때), 후순위자의 경매신청(선순위는 매각대금 완납 때), 채무자 파산"],["확정 후","새로 생긴 채권은 담보되지 않는다. 확정 전 원본에서 확정 뒤 생긴 이자·지연이자는 최고액 안에서 담보된다"]],"결론":"확정 전이냐 후냐가 근저당 문제의 갈림길 — 확정 전 일부 양도·대위변제로는 근저당권이 옮겨 가지 않는다"},{"종류":"요점","등급":"B","제목":"확정 전의 변경","글":"피담보채권이 확정되기 전이라면 채권최고액, 채무자 등을 바꿀 수 있고, 바뀐 뒤의 사항만 담보한다."}]},"민3-1":{"요약":"계약 총론은 청약·승낙에 의한 성립요건과 효력발생시기, 동시이행의 항변권·위험부담, 제3자를 위한 계약의 효력, 해제·해지의 요건과 제3자 보호범위를 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"계약의 종류"},{"종류":"비교","제목":"계약의 한평생","머리":["단계","내용"],"행":[["성립","청약과 승낙이 맞아떨어지면 성립한다. 교차청약·의사실현으로도 성립한다"],["효력","쌍무계약이면 동시이행의 항변권과 위험부담이 따라붙는다. 이행을 제3자에게 하게 할 수도 있다"],["소멸","해제는 계약을 처음으로 되돌리고(소급), 해지는 앞으로만 끝낸다"]],"결론":"각론의 매매·교환·임대차는 모두 이 세 단계 위에서 움직인다"},{"종류":"비교","제목":"대표 계약 7개를 세 잣대로","머리":["계약","쌍무/편무","유상/무상","낙성/요물"],"행":[["매매","쌍무","유상","낙성"],["교환","쌍무","유상","낙성"],["임대차","쌍무","유상","낙성"],["도급","쌍무","유상","낙성"],["증여","편무","무상","낙성"],["사용대차","편무","무상","낙성"],["현상광고","편무","유상","요물"]],"결론":"쌍무계약은 모두 유상이지만 유상이라고 다 쌍무는 아니다 — 현상광고가 그 예다"},{"종류":"비유","글":"현상광고 = 현상금 수배 전단. 돈을 줄 빚은 전단을 붙인 쪽만 지고(편무), 그 돈은 일을 해낸 대가이며(유상), 누군가 실제로 해내야 계약이 선다(요물)."},{"종류":"참고","글":"요물계약 = 합의만으로는 안 되고 물건 인도나 일의 완성 같은 실제 급부가 있어야 성립하는 계약 · 출연 = 자기 재산을 줄여 상대에게 이익을 주는 것"},{"종류":"소제목","글":"계약의 성립"},{"종류":"요점","등급":"A","제목":"청약의 의의와 효력","글":"청약은 승낙만 있으면 곧바로 계약이 성립할 만큼 구체적·확정적인 의사표시다. 구체적이지 않으면 청약의 유인에 그쳐 채무불이행책임이 없다(상가분양광고). 도달주의에 따라 상대방에게 도달해야 효력이 생기고, 도달한 뒤에는 마음대로 철회하지 못한다(제527조). 발신 뒤 도달 전에 청약자가 죽거나 행위능력을 잃어도 청약의 효력에는 영향이 없다."},{"종류":"비유","글":"청약의 유인은 '집 팝니다' 광고, 청약은 그 광고를 보고 '그 값에 사겠다'고 한 연락이다. 광고에 응한 쪽이 청약자가 되므로 광고주가 승낙해야 비로소 계약이 된다."},{"종류":"요점","등급":"A","제목":"승낙과 계약의 성립시기","글":"승낙은 청약과 내용이 같아야 한다(객관적 합치). 조건을 달거나 내용을 바꿔 승낙하면 청약을 거절하고 새로 청약한 것이 되어, 원래 청약자가 다시 승낙하지 않는 한 계약이 성립하지 않는다(제534조). 승낙 통지를 발신한 때 계약이 성립하지만(발신주의), 승낙기간이나 상당한 기간 안에 도달하지 않으면 승낙은 소급해서 효력을 잃는다."},{"종류":"요점","등급":"B","제목":"무의식적 불합의","글":"청약과 승낙이 실제로는 어긋나는데 승낙자가 서로 맞는다고 잘못 믿었다면 계약은 성립하지 않는다(취소 대상이 아니라 애초에 불성립)."},{"종류":"요점","등급":"A","제목":"의사실현·교차청약에 의한 성립","글":"청약자의 의사표시나 관습상 승낙 통지가 필요 없다면, 승낙으로 볼 만한 사실이 있었던 때 계약이 성립한다(의사실현, 청약자가 그 사실을 안 때가 아니다). 교차청약은 두 청약이 모두 상대방에게 도달한 때, 같은 때 도달하지 않았다면 나중 청약이 도달한 때 계약이 성립한다."},{"종류":"요점","등급":"B","제목":"계약체결상의 과실책임","글":"원시적으로 불능이고 객관적으로 전부 불능인 급부를 목적으로 계약을 맺었을 때, 그 불능을 안 당사자가 몰랐거나 알 수 없었던 상대방에게 지는 책임이다."},{"종류":"소제목","글":"계약의 효력"},{"종류":"조문","조":"제536조","글":"①쌍무계약의 당사자 일방은 상대방이 그 채무이행을 제공할 때 까지 자기의 채무이행을 거절할 수 있다. 그러나 상대방의 채무가 변제기에 있지 아니하는 때에는 그러하지 아니하다."},{"종류":"요점","등급":"B","제목":"동시이행 항변권의 성립·존속","글":"한쪽 채무가 이행불능 등으로 소멸하면 항변권도 소멸한다. 다만 이행지체나 채무자의 귀책사유로 손해배상채무로 바뀌었거나 대상청구권이 생겼다면 채무의 동일성이 이어져 항변권은 남는다. 한 차례 현실제공으로 상대방을 수령지체에 빠뜨렸어도 그 제공을 계속하지 않았다면, 그 사실만으로 상대방의 항변권이 없어졌다고 보지 않는다. 동시이행의 항변권이 붙은 채권은 자동채권으로 삼아 상계하지 못한다."},{"종류":"비교","제목":"동시이행이 되는 짝, 안 되는 짝","머리":["짝","동시이행"],"행":[["계약이 무효·취소된 뒤 서로의 반환의무","○"],["잔대금 지급 ↔ 소유권이전등기","○"],["임대차 종료 때 목적물 반환 ↔ 보증금 반환","○"],["지상물매수청구 뒤 건물대금 지급 ↔ 토지 인도","○"],["피담보채무 변제 ↔ 담보 목적 등기 말소","× (변제가 먼저)"],["보증금 반환 ↔ 임차권등기명령에 따른 등기 말소","× (보증금이 먼저)"],["토지거래허가 협력의무 ↔ 대금 지급","×"],["권리금 회수 방해로 인한 손해배상 ↔ 임차목적물 반환","×"]],"결론":"한쪽이 먼저 끝나야 다른 쪽 의무가 생기는 관계는 동시이행이 아니다"},{"종류":"비유","글":"동시이행은 계산대의 맞교환이다 — 상대가 물건을 내밀기 전에는 나도 돈을 내밀지 않아도 된다. 전당포는 다르다. 빌린 돈부터 갚아야 맡긴 물건이 나오듯, 담보 목적 등기의 말소는 변제 뒤에야 청구할 수 있다."},{"종류":"요점","등급":"A","제목":"위험부담의 원칙과 예외","글":"쌍무계약에서 한쪽 채무가 양쪽 모두의 책임 없는 사유로 이행불능이 되면, 채무자는 반대급부를 청구하지 못한다(제537조, 채무자위험부담). 이미 받은 것은 부당이득으로 돌려준다. 다만 채권자의 책임 있는 사유로 불능이 되었거나 채권자의 수령지체 중에 양쪽 모두 책임 없는 사유로 불능이 되었다면, 채무자는 반대급부를 청구할 수 있다(제538조, 채권자위험부담). 이때 채무자가 자기 채무를 면해 얻은 이익은 채권자에게 돌려준다."},{"종류":"비교","제목":"이행불능 — 누구 탓인가에 따라","머리":["불능의 원인","적용되는 법리","결과"],"행":[["채무자 탓","채무불이행(위험부담 문제 ×)","채권자가 해제하고 손해배상을 청구한다"],["누구 탓도 아님","채무자위험부담(제537조)","채무자는 반대급부를 청구하지 못하고, 이미 받은 계약금 등은 부당이득으로 돌려준다"],["채권자 탓, 또는 채권자 수령지체 중 누구 탓도 아님","채권자위험부담(제538조)","채무자는 반대급부를 청구할 수 있고, 자기 채무를 면해 얻은 이익은 채권자에게 돌려준다"]],"결론":"위험부담 규정은 특약으로 바꿀 수 있다(매수인이 위험을 지기로 약정 가능)"},{"종류":"소제목","글":"제3자를 위한 계약"},{"종류":"조문","조":"제539조","글":"①계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다. ②전항의 경우에 제삼자의 권리는 그 제삼자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다."},{"종류":"비유","글":"꽃배달 주문과 같다. 나(요약자)가 꽃집(낙약자)에 돈을 내고 친구(수익자)에게 보내게 한다. 친구는 주문 당사자가 아니어서 주문을 해제·취소할 수 없고, 내가 왜 꽃을 보냈는지(대가관계)는 꽃집이 따질 일이 아니다."},{"종류":"참고","글":"요약자 = 제3자에게 이행하라고 약속받은 당사자 · 낙약자 = 제3자에게 이행하기로 약속한 당사자 · 수익의 의사표시 = 제3자가 낙약자에게 그 이익을 받겠다고 알리는 것"},{"종류":"요점","등급":"B","제목":"제3자를 위한 계약의 요건","글":"제3자는 계약이 성립할 때 존재하지 않아도 된다(태아, 설립 중인 법인 등). 중첩적 채무인수계약도 제3자를 위한 계약에 해당한다."},{"종류":"요점","등급":"S","제목":"수익자의 지위","글":"수익자는 계약 당사자가 아니다. 그래서 계약해제권·취소권이 없고, 원상회복청구를 하거나 그 상대방이 되지도 않는다. 다만 제3자 보호규정(해제·통정허위표시 등)을 적용할 때 보호받는 제3자에는 해당하지 않는다."},{"종류":"요점","등급":"B","제목":"수익의 의사표시와 그 효과","글":"수익자의 권리는 낙약자에게 수익의 의사표시를 한 때 생긴다. 낙약자는 상당한 기간을 정해 이익을 받을지 확답하라고 최고할 수 있고, 그 기간 안에 확답이 없으면 수익을 거절한 것으로 본다. 수익의 의사표시 뒤 낙약자가 이행하지 않으면 수익자에게도 손해배상청구권이 생기고, 제3자의 권리가 생긴 뒤에는 계약 당사자라도 그 권리를 바꾸거나 없애지 못한다."},{"종류":"요점","등급":"A","제목":"요약자의 해제권","글":"수익자가 수익의 의사표시를 한 뒤 낙약자가 채무를 이행하지 않으면, 요약자는 제3자의 동의나 승낙 없이 혼자서 계약을 해제할 수 있다. 수익자는 계약 당사자가 아니어서 해제권·취소권을 행사하지 못하지만, 낙약자의 불이행을 근거로 손해배상은 청구할 수 있다."},{"종류":"요점","등급":"A","제목":"낙약자의 항변권과 대가관계","글":"낙약자는 요약자와 맺은 계약(제3자의 권리를 생기게 한 기본계약)에서 나오는 항변으로만 제3자에게 대항할 수 있다. 요약자와 수익자 사이의 법률관계(대가관계)를 내세워 수익자에게 항변할 수는 없고, 그 대가관계에 하자가 있어도 계약 성립에는 영향이 없다."},{"종류":"소제목","글":"계약의 해제와 해지"},{"종류":"비교","제목":"법정해제의 흐름","머리":["단계","내용"],"행":[["이행지체","상당한 기간을 정해 최고하고 그 안에 이행이 없으면 해제권이 생긴다. 정기행위이거나 미리 이행하지 않겠다고 밝혔으면 최고가 필요 없다"],["이행불능","채무자 책임으로 불능이 되면 최고 없이 바로 해제권이 생긴다"],["해제의 의사표시","상대방에게 하고, 철회하지 못한다. 당사자가 여럿이면 전원이, 전원에게 한다"],["효과","계약이 처음부터 없던 것이 된다 → 원상회복(금전은 받은 날부터 이자) + 손해배상. 단 제3자의 권리는 해치지 못한다"]],"결론":"목적물이 가압류된 것만으로는 이행불능이 아니므로 그것만 이유로 해제할 수 없다"},{"종류":"조문","조":"제548조","글":"①당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다. ②전항의 경우에 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다."},{"종류":"비교","제목":"법정해제와 합의해제(해제계약)","머리":["구분","법정해제","합의해제"],"행":[["이유","채무불이행","당사자의 합의"],["손해배상청구","○","× (특약이 없는 한)"],["대금 반환 시 이자 가산","○","× (특약이 없는 한)"],["소급효","○","○"],["제3자 보호","○","○"]],"결론":"합의해제는 채무불이행이 없어도 할 수 있지만, 손해배상과 이자 가산은 따로 정하지 않으면 인정되지 않는다."},{"종류":"요점","등급":"B","제목":"법정해제권의 발생","글":"이행지체라면 상당한 기간을 정해 최고한 뒤 그 기간 안에 이행이 없어야 해제권이 생기지만, 정기행위이거나 채무자가 이행하지 않겠다는 뜻을 분명히 밝혔다면 최고가 필요 없다. 이행불능이라면 채무자의 귀책사유로 계약 뒤에 불능이 된 경우(후발적 불능) 최고 없이 바로 채권자에게 해제권이 생긴다."},{"종류":"요점","등급":"B","제목":"해제권 행사의 불가분성","글":"당사자 한쪽이나 양쪽이 여러 명이면 해제는 전원이 하거나 전원에게 해야 한다(동시에 할 필요는 없다)."},{"종류":"비교","제목":"해제로부터 보호되는 제3자인가","머리":["해제 전에 이해관계를 맺은 사람","보호"],"행":[["매수인 명의로 등기된 목적물에 저당권을 얻은 사람","○"],["매수인의 책임재산이 된 목적물을 가압류한 사람","○"],["매수인과 매매예약을 하고 가등기를 마친 사람","○"],["주택임대차보호법상 대항요건을 갖춘 임차인","○"],["매수인의 소유권이전등기청구권을 압류한 사람","×"],["계약상 채권을 양수한 사람","×"]],"결론":"목적물 자체에 등기·인도 등으로 권리를 갖췄으면 보호되고, 계약상 채권만 붙잡았으면 보호되지 않는다"},{"종류":"요점","등급":"A","제목":"해제의 소급효와 물권복귀","글":"해제하면 계약이 처음으로 거슬러 올라가 모두 소멸하고, 물권은 당연히 원래 권리자에게 돌아간다. 다만 해제된 계약으로 생긴 법률효과를 바탕으로 새 이해관계를 맺고 등기·인도 등으로 완전한 권리까지 얻은 제3자의 권리는 해치지 못한다."},{"종류":"요점","등급":"B","제목":"원상회복의무와 손해배상청구권","글":"원상회복은 계약이 처음부터 없던 상태로 되돌리는 것으로, 선의·악의나 현존이익과 상관없이 받은 급부 전부를 돌려줘야 한다. 금전을 받았다면 받은 날부터의 이자를 붙여 돌려주는데, 이 이자는 부당이득반환의 성질이지 이행지체에 따른 손해배상이 아니다. 목적물을 사용했다면 사용 대가도 돌려준다. 계약을 해제해도 손해배상 청구에는 영향이 없다."},{"종류":"비유","글":"해제는 영상 되감기, 해지는 정지 버튼이다. 해제하면 계약이 처음으로 돌아가 주고받은 것을 서로 돌려주지만, 해지하면 그때부터만 끝나 이미 지난 기간의 차임은 그대로 남는다."},{"종류":"참고","글":"최고 = 이행하라고 재촉하는 통지 · 정기행위 = 정해진 때에 하지 않으면 계약 목적을 이룰 수 없는 급부 · 소급효 = 효력이 계약 처음으로 거슬러 올라가는 것"}]},"민3-2":{"요약":"매매·교환은 계약금(해약금)의 성질과 이행의 착수, 매도인의 담보책임 유형별 요건, 환매의 요건·기간, 교환의 매매 규정 준용을 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"매매"},{"종류":"요점","등급":"A","제목":"매매의 의의와 법적 성질","글":"매매는 당사자 한쪽이 재산권을 상대방에게 넘기기로 약정하고 상대방이 그 대금을 치르기로 약정하면 효력이 생긴다(제563조). 목적물 인도의무나 대금 지급시기를 계약 때 구체적으로 정해 두지 않아도, 나중에 정할 방법과 기준만 있으면 충분하다. 낙성·쌍무·유상·불요식계약이고, 이 규정은 다른 유상계약에도 원칙적으로 준용된다(제567조). 남의 물건이나 권리도 매매의 목적물이 될 수 있다."},{"종류":"소제목","글":"매매의 예약과 계약금"},{"종류":"요점","등급":"A","제목":"매매의 예약과 예약완결권","글":"예약완결권은 행사기간을 정했으면 그 기간 안에(약정으로 10년을 넘겨 정해도 유효하다), 정하지 않았으면 예약이 성립한 날부터 10년 안에 행사해야 한다. 이 기간은 법원의 직권조사사항이라 당사자의 주장이 없어도 법원이 고려해야 한다. 예약완결권은 재산권이라 특별한 사정이 없으면 타인에게 양도할 수 있다. 행사기간을 정하지 않았다면 예약자는 상당한 기간을 정해 확답하라고 최고할 수 있고, 그 기간 안에 확답이 없으면 예약은 효력을 잃는다."},{"종류":"조문","조":"제565조","글":"①매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다. ②제551조의 규정은 전항의 경우에 이를 적용하지 아니한다."},{"종류":"요점","등급":"S","제목":"계약금의 성질과 해약금의 추정","글":"계약금계약은 요물계약이고 매매계약에 딸린 종된 계약이라, 꼭 매매와 같은 때에 맺어야 하는 것은 아니다. 위약금 성질은 따로 특약을 했을 때에만 생기고, 위약금약정이 있으면 계약금은 해약금과 위약금(손해배상 예정액) 성질을 함께 가진다. 이름이 계약금이든 보증금이든 원칙적으로 해약금 성질을 가진 것으로 추정한다."},{"종류":"비교","제목":"해약금 해제와 채무불이행 해제","머리":["구분","해약금에 의한 해제(제565조)","채무불이행에 의한 해제"],"행":[["이유","필요 없다","상대방의 채무불이행"],["언제까지","당사자 한쪽이 이행에 착수하기 전","불이행이 생긴 뒤"],["방법","준 쪽은 계약금 포기, 받은 쪽은 배액 상환","(원칙적으로 최고 뒤) 해제의 의사표시"],["손해배상","청구 못 함","청구할 수 있음"]],"결론":"매수인이 중도금을 냈다면 매도인은 물론 매수인 자신도 계약금만 버리고 빠져나갈 수 없다"},{"종류":"비유","글":"해약금은 계약에서 빠져나가는 비상구 요금이다. 준 쪽은 낸 돈을 버리고, 받은 쪽은 두 배를 물어 주고 나간다. 한쪽이라도 이행에 발을 들이면(이행의 착수) 비상구는 양쪽 모두에게 닫힌다."},{"종류":"요점","등급":"A","제목":"이행의 착수와 해약금 해제의 한계","글":"특약이 없으면 이행기 전에 한 이행도 이행의 착수로 본다. 매도인이 전혀 착수하지 않았더라도 매수인이 중도금을 내 이미 착수했다면, 매수인은 계약금을 포기하는 방법으로 해제할 수 없다(마찬가지로 매도인도 배액을 상환해 해제할 수 없다). 계약금 중 일부만 받은 상태에서 받은 사람이 해제하려면, 돌려줄 배액은 실제로 받은 금액이 아니라 약정한 계약금을 기준으로 계산한다. 채권양도로 중도금 지급을 갈음하기로 하고 그 채무자까지 자리에 참석해 구체적으로 이행 단계에 들어갔다면, 계약 당시의 약정이라도 이행의 착수로 본다."},{"종류":"참고","글":"이행의 착수 = 중도금 지급처럼 채무 이행의 일부를 실제로 하는 것(토지거래허가를 받았거나 잔대금 청구 소송만 낸 것은 해당 ×) · 배액 = 두 배의 금액"},{"종류":"소제목","글":"매매의 효력"},{"종류":"요점","등급":"B","제목":"매도인·매수인의 의무","글":"인도하지 않은 목적물에서 생긴 과실은 매도인의 것이지만, 인도 전이라도 매수인이 대금을 모두 치렀다면 그 뒤의 과실수취권은 매수인에게 돌아간다. 매수인은 목적물을 받기 전까지는 대금이자를 낼 의무가 없다. 매매목적물에 권리를 주장하는 사람이 있으면 매수인은 위험한 한도에서 대금 지급을 거절할 수 있다. 계약비용(측량·평가비, 계약서 작성비 등)은 당사자 양쪽이 반씩 부담한다(등기비용은 포함하지 않는다)."},{"종류":"소제목","글":"매도인의 담보책임"},{"종류":"요점","등급":"B","제목":"담보책임 총설","글":"매매의 목적인 물건이나 권리에 하자·불완전한 점이 있을 때 매도인이 매수인에게 지는 무과실책임이다. 매도인에게 고의·과실이 없어도 책임을 진다."},{"종류":"요점","등급":"B","제목":"수량부족·일부멸실의 담보책임","글":"수량을 지정한 매매에서 수량이 모자라거나 계약 당시 이미 목적물 일부가 멸실되어 있었다면(원시적·객관적·일부불능), 선의의 매수인은 원칙적으로 대금감액청구권과 손해배상청구권을 갖고, 남은 부분만으로는 사지 않았을 사정이 있으면 해제권까지 갖는다. 악의의 매수인은 담보책임을 물을 수 없다. 선의의 매수인은 그 사실을 안 날부터 1년 안에 행사해야 한다."},{"종류":"비교","제목":"한방 정리 — 매도인의 담보책임","머리":["유형","선의 매수인","악의 매수인","행사기간"],"행":[["전부 타인의 권리(제570조)","해제 + 손해배상","해제만","제한 없음"],["일부 타인의 권리(제572조)","대금감액·해제 + 손해배상","대금감액만","선의는 안 날부터, 악의는 계약한 날부터 1년"],["수량부족·일부멸실(제574조)","대금감액·해제 + 손해배상","없음","안 날부터 1년"],["제한물권·등기된 임대차(제575조)","목적 달성 불능이면 해제, 그 밖에는 손해배상","없음","안 날부터 1년"],["저당권·전세권 행사(제576조)","해제 + 손해배상, 자기 돈으로 소유권을 지켰으면 그 상환 청구","선의와 같음","제한 없음"],["물건의 하자(제580조)","목적 달성 불능이면 해제, 그 밖에는 손해배상(과실 없이 몰랐어야 함)","없음","안 날부터 6개월"]],"결론":"악의여도 무언가 할 수 있는 것은 셋 — 전부 타인 권리(해제), 일부 타인 권리(감액), 저당권·전세권 행사(전부)"},{"종류":"요점","등급":"B","제목":"제한물권·저당권 행사에 의한 담보책임","글":"저당권·전세권의 행사로 매수인이 소유권을 취득할 수 없게 되면, 선의·악의를 가리지 않고 해제권과 손해배상청구권이 있고(경매가 실행된 경우), 매수인이 자기 출재로 소유권을 지켰다면 매도인에게 그 상환을 청구할 수 있다. 이 담보책임에는 행사기간 제한이 없다."},{"종류":"요점","등급":"B","제목":"물건의 하자담보책임","글":"매수인이 하자를 몰랐고 과실도 없어야 성립하며(경매에는 적용하지 않는다), 제척기간은 하자를 발견한 때부터 6개월이다. 종류물 매매에서 목적물이 특정된 뒤 하자가 있으면, 매수인은 특정물 매매와 같은 담보책임을 묻거나 하자 없는 물건으로 완전물급여를 청구할 수 있다."},{"종류":"조문","조":"제580조","글":"①매매의 목적물에 하자가 있는 때에는 제575조제1항의 규정을 준용한다. 그러나 매수인이 하자있는 것을 알았거나 과실로 인하여 이를 알지 못한 때에는 그러하지 아니하다. ②전항의 규정은 경매의 경우에 적용하지 아니한다."},{"종류":"비유","글":"집 문서가 문제면 권리의 하자, 집 벽이 갈라졌으면 물건의 하자다. 경매로 산 사람은 문서 문제(권리의 하자)는 따질 수 있어도 벽 균열(물건의 하자)은 따지지 못한다."},{"종류":"요점","등급":"B","제목":"경매에서의 담보책임","글":"경매에서는 물건의 하자에는 담보책임이 인정되지 않고 권리의 하자에만 인정된다. 경매절차가 무효라면 매수인(경락인)은 매도인에게 손해배상을 청구할 수 없고, 대신 매각대금을 배당받은 채권자에게 부당이득으로 반환을 청구해야 한다. 매도인이 무자력이면 매수인은 그 배당금을 받은 채권자에게 반환을 청구할 수 있다."},{"종류":"소제목","글":"환매"},{"종류":"요점","등급":"A","제목":"환매의 의의와 성질","글":"환매권은 재산권이라 양도·상속할 수 있고 채권자대위권의 대상도 된다. 목적물이 부동산이면 매매등기와 함께 환매권 유보를 등기해야 제3자에게 대항할 수 있다."},{"종류":"요점","등급":"A","제목":"환매의 요건","글":"환매특약은 매매계약과 같은 때에 해야 하고, 매매계약이 무효면 환매특약도 무효다. 환매기간은 한번 정하면 다시 늘릴 수 없고, 약정으로 한도를 넘겨 정했다면 부동산은 5년, 동산은 3년으로 줄어든다."},{"종류":"요점","등급":"B","제목":"환매대금과 환매권의 행사","글":"환매대금은 원래 매매대금에 매수인이 부담한 매매비용을 더한 금액이다. 다만 환매대금에 관해 당사자가 다르게 정한 특약이 있으면 그 특약이 우선한다(제590조 제2항). 목적물의 과실과 대금의 이자는 서로 상계한 것으로 본다."},{"종류":"소제목","글":"교환"},{"종류":"요점","등급":"A","제목":"교환의 성질과 매매 규정의 준용","글":"당사자 양쪽이 금전이 아닌 재산권을 서로 넘기기로 약정하면 성립하는 낙성·쌍무·유상·불요식계약이라 서면 작성이 필요 없고, 승낙도 방식에 제한이 없다. 쌍무계약이라 동시이행항변권과 위험부담 법리가 그대로 적용되고, 유상계약이라 매매 규정이 준용된다(제567조). 보충금에는 매매대금 규정을 준용해, 보충금을 못 받으면 그것만으로도 계약을 해제할 수 있다. 특약이 없어도 각 당사자는 목적물의 하자에 담보책임을 진다."},{"종류":"요점","등급":"B","제목":"교환 당사자의 시가 고지","글":"특별한 사정이 없으면 자기 목적물의 시가를 사실대로 고지할 의무는 없다. 상대방 목적물보다 시가를 다소 높게 고지해 그 차액을 보충금으로 약정하기에 이르렀더라도, 특별한 사정이 없는 한 불법행위(기망)가 되지 않는다."}]},"민3-3":{"요약":"임대차는 존속기간·법정갱신, 비용상환청구권·부속물매수청구권·지상물매수청구권의 요건, 임차권 양도·전대의 효과, 보증금의 성질을 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"임대차의 성립과 존속기간"},{"종류":"요점","등급":"B","제목":"임대차의 목적물","글":"임대차의 목적물이 꼭 임대인 소유일 필요는 없고, 임대인에게 처분권한이 있어야 하는 것도 아니다. 남의 물건이라도 임대차의 목적물로 삼는 데 상관없다."},{"종류":"요점","등급":"B","제목":"부동산임차권의 대항력","글":"민법상 임대차에는 원칙적으로 대항력이 없다. 다만 건물 소유를 목적으로 한 토지임대차는 등기하지 않았더라도 임차인이 그 땅 위 건물을 등기하면 제3자에게 대항할 수 있다(제622조, 건물이 멸실되면 대항력이 없다)."},{"종류":"요점","등급":"A","제목":"임대차의 존속기간과 갱신","글":"약정 존속기간에는 최장기간 제한이 없어 영구무한으로 정해도 유효하다. 기간이 끝났을 때 토지임대차에 건물·수목 등 지상시설이 남아 있으면 임차인은 계약갱신을 청구할 수 있고, 임대인이 원하지 않으면 그 시설을 상당한 가액에 매수하라고 청구할 수 있다(제643조). 법정갱신은 강행규정이 아니며, 갱신되면 제3자가 제공한 담보는 소멸한다(임차인이 제공한 담보는 소멸하지 않는다)."},{"종류":"참고","글":"편면적 강행규정 = 임차인에게 불리한 약정만 무효로 만드는 규정(임차인에게 유리한 약정은 유효하다)"},{"종류":"소제목","글":"지상물매수청구권"},{"종류":"요점","등급":"A","제목":"지상물매수청구권의 성립","글":"토지임차인의 계약갱신청구권·지상물매수청구권(제643조)은 편면적 강행규정이라 임차인에게 불리한 특약은 효력이 없다. 임대인의 동의 없이 지었거나 허가 없이 지은 불법건물, 경제적 가치가 없거나 임대인에게 쓸모없는 건물, 미등기건물, 근저당권이 설정된 건물이라도 지상물이 남아 있으면 매수청구할 수 있다. 기간 약정이 없는 토지임대차에서 임대인이 해지통고를 했다면, 임차인은 갱신청구를 거치지 않고 바로 지상물매수를 청구할 수 있다. 임차인의 채무불이행으로 계약이 해지되었다면 지상물매수청구권을 행사할 수 없다."},{"종류":"요점","등급":"B","제목":"지상물매수청구권의 범위와 대금","글":"임대인 땅과 제3자 땅에 걸쳐 지은 건물은, 임차한 땅 위의 건물 부분이 구분소유의 객체가 될 수 있을 때에만 매수청구할 수 있다. 근저당권이 설정되어 있어도 매수대금은 건물 시가이고, 채권최고액을 뺀 나머지 금액이 아니다."},{"종류":"소제목","글":"임대차의 효력"},{"종류":"요점","등급":"B","제목":"차임증감청구권","글":"임대물에 대한 공과부담이 늘거나 줄었거나 그 밖의 경제사정이 바뀌어 약정한 차임이 적당하지 않게 되면, 당사자는 앞으로의 차임을 올리거나 내려 달라고 청구할 수 있다(제628조, 편면적 강행규정)."},{"종류":"요점","등급":"B","제목":"비용상환청구권","글":"필요비는 임대차가 계속되는 중이라도 지출하면 바로 상환을 청구할 수 있다. 유익비는 임대차가 끝났을 때 가액 증가가 남아 있는 경우에만 청구할 수 있고, 목적물을 반환받은 날부터 6개월 안에 행사해야 한다(제626조, 강행규정이 아니라서 포기 특약도 유효하고, 유치권도 인정된다). 특별한 사정이 없다면 임차인은 지출한 필요비만큼 차임 지급을 거절할 수 있다."},{"종류":"비유","글":"필요비는 고장 난 보일러 수리비, 유익비는 새로 깐 원목 마루 값이다. 보일러 수리비는 지금 바로 청구하고, 마루 값은 나갈 때 그 가치가 남아 있어야 받는다."},{"종류":"조문","조":"제646조","글":"①건물 기타 공작물의 임차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 임대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다. ②임대인으로부터 매수한 부속물에 대하여도 전항과 같다."},{"종류":"요점","등급":"B","제목":"부속물매수청구권","글":"건물 임차인이 임대인의 동의를 얻어 붙인 물건이나 임대인에게서 산 부속물이 있으면, 임대차가 끝날 때 매수를 청구할 수 있는 형성권이다(강행규정). 임차인의 채무불이행으로 해지되었다면 행사할 수 없다. 적법하게 전대했다면 전차인도 행사할 수 있다."},{"종류":"비교","제목":"임차인이 돌려받거나 팔 수 있는 것 넷","머리":["권리","대상","언제","임차인이 포기하는 특약"],"행":[["필요비 상환청구","목적물 보존에 쓴 비용","지출하면 바로","유효"],["유익비 상환청구","목적물 가치를 높인 비용","임대차 종료 때 가액 증가가 남아 있으면","유효"],["부속물 매수청구","건물 임차인이 임대인 동의를 얻어 붙인 물건, 임대인에게서 산 부속물","임대차 종료 때","무효(제652조)"],["지상물 매수청구","토지 임차인의 건물·수목 등 지상시설","기간 만료 뒤 갱신을 거절당했을 때(해지통고로 끝나면 바로)","무효(제652조)"]],"결론":"비용상환청구권은 포기 특약이 유효하고, 두 매수청구권은 임차인에게 불리한 특약이 무효다. 임차인의 채무불이행으로 해지되면 두 매수청구권은 생기지 않는다"},{"종류":"참고","글":"부속물 = 건물에 붙였지만 건물의 구성부분은 되지 않고 건물 사용에 객관적으로 편리를 주는 물건(임차인만의 특수한 목적에 쓰려고 붙인 것은 제외) · 필요비·유익비 상환은 목적물을 돌려받은 날부터 6개월 안에 청구한다"},{"종류":"참고","글":"필요비상환청구권은 채권적 청구권이고, 부속물매수청구권·지상물매수청구권은 형성권이다."},{"종류":"참고","글":"건물전세권자에게도 유익비상환청구권·부속물매수청구권·전세금증감청구권이 인정된다(임대차 규정 준용)."},{"종류":"소제목","글":"임차인의 의무와 보증금"},{"종류":"요점","등급":"B","제목":"차임 연체와 해지","글":"건물임차인이 차임을 2기 이상 연체하면 임대인은 계약을 해지할 수 있다."},{"종류":"요점","등급":"B","제목":"보증금의 성질과 공제","글":"임대차가 묵시적으로 갱신되면 보증금도 그대로 이어지지만, 제3자가 제공한 담보는 소멸한다. 임대인은 계약기간 중에도 보증금을 연체차임에 충당할 수 있지만, 임차인은 보증금이 있다는 이유로 차임 지급을 거절할 수 없다. 밀린 차임은 임대차가 끝난 뒤에는 보증금에서 당연히 공제되지만, 계약기간 중에는 당연히 공제되지 않는다."},{"종류":"소제목","글":"임차권의 양도와 전대"},{"종류":"요점","등급":"B","제목":"임차권 양도·전대의 원칙","글":"임차권을 양도하거나 임차물을 전대하려면 임대인의 동의를 받아야 하고, 동의 없이 했다면 임대인은 계약을 해지할 수 있다(제629조). 동의 없는 양도·전대도 당사자 사이에서는 유효하지만 임대인에게는 대항하지 못한다."},{"종류":"요점","등급":"B","제목":"임대인 동의 있는 전대의 효과","글":"전차인은 임대인에게 직접 의무를 진다(제630조). 임대인·임차인이 임대차를 합의로 해지해도 전대차는 소멸하지 않는다(다만 기간 만료나 해지로 임대차가 끝나면 전대차도 소멸한다). 전차인은 임대인의 동의를 받아 부속시킨 물건이 있으면 임대인에게 매수를 청구할 수 있다."},{"종류":"비교","제목":"임대인 동의가 있는 전대, 없는 전대","머리":["구분","동의 있는 전대","동의 없는 전대"],"행":[["임차인–전차인 사이","유효","유효(임대인에게는 대항하지 못함)"],["무단 전대를 이유로 한 해지","해당 없음","임대인이 할 수 있음(제629조)"],["전차인과 임대인","전차인이 임대인에게 직접 의무를 진다(제630조)","전차인은 임대인에게 대항하지 못한다"],["임대차가 존속하는 동안 임대인이 전차인에게 차임 상당 손해배상 청구","—","못 한다(임차인에게 차임을 청구할 수 있으므로)"],["임대인·임차인이 임대차를 합의해지하면","전차권은 소멸하지 않는다","—"],["전차인의 부속물 매수청구","할 수 있다(제647조)","못 한다"]],"결론":"동의가 있으면 전차인은 임대인과 직접 이어지고, 임대인·임차인의 합의해지로도 밀려나지 않는다"},{"종류":"요점","등급":"A","제목":"임대인 동의 없는 전대의 효과","글":"임대인은 계약을 해지할 수 있지만, 해지하지 않는 동안에는 임차인이 원래 지위를 그대로 가진다. 그래서 해지되지 않는 한 임대인은 임차인에게 차임을 청구할 수 있고, 그 결과 양수인(전차인)에게 차임에 갈음한 손해배상을 청구하지 못한다(해지한 뒤에는 청구할 수 있다)."}]},"민4-1":{"요약":"임차권의 대항력과 우선변제권·최우선변제권의 성립요건, 존속기간과 계약갱신요구권을 가장 많이 묻는다.","블록":[{"종류":"비교","제목":"한방 정리 — 주택 vs 상가 임대차","머리":["구분","주택임대차보호법","상가건물 임대차보호법"],"행":[["적용 범위","주거용 건물(보증금 액수 제한 없음)","사업자등록 대상 상가건물, 대통령령 보증금액 이하(서울 9억원, 월차임×100을 보증금에 더해 셈)"],["대항요건","인도 + 주민등록(전입신고)","인도 + 사업자등록 신청"],["대항력 발생","그다음 날(오전 0시)부터","그다음 날부터"],["최단 존속기간","2년(임차인은 더 짧은 기간을 주장 가능)","1년(임차인은 더 짧은 기간을 주장 가능)"],["묵시적 갱신 — 임대인 통지 기간","기간 끝나기 6개월 전 ~ 2개월 전","기간 끝나기 6개월 전 ~ 1개월 전"],["묵시적 갱신 — 임차인 통지","기간 끝나기 2개월 전까지","규정 없음(1개월이 안 남아도 갱신 거절 가능)"],["묵시적 갱신 뒤","기간 2년, 임차인은 언제든 해지 통지 → 3개월 뒤 효력","기간 1년, 임차인은 언제든 해지 통고 → 3개월 뒤 효력"],["계약갱신요구권","6개월 전 ~ 2개월 전에 요구, 1회, 갱신 기간 2년","6개월 전 ~ 1개월 전에 요구, 전체 기간 10년 이내"],["차임 연체","2기 → 해지(민법 제640조), 묵시적 갱신 배제·갱신요구 거절 사유","3기 → 해지(제10조의8), 갱신요구 거절 사유"],["소액 최우선변제(서울)","보증금 1억6천500만원 이하, 5천500만원까지","환산보증금 6천500만원 이하, 2천200만원까지"],["권리금 회수기회 보호","없음","있음(제10조의4)"]],"결론":"주택은 2년·2기·2개월 전, 상가는 1년·3기·1개월 전 — 숫자 짝으로 가른다"},{"종류":"소제목","글":"적용범위"},{"종류":"요점","등급":"","제목":"적용범위","글":"이 법은 주거용 건물(일부가 주거 외 목적으로 쓰여도 적용)에 적용되고, 등기하지 않은 전세계약에도 준용된다. 일시사용임이 명백한 임대차에는 적용되지 않는다. 사무실로 쓰이던 건물이 임대차 중 주거용으로 용도가 바뀌면 그때부터 적용되고, 적법한 임대 권한을 가진 사람에게서 빌렸다면 그 사람이 실제 소유자가 아니어도 적용된다."},{"종류":"소제목","글":"대항력"},{"종류":"요점","등급":"B","제목":"대항요건","글":"주택 인도와 주민등록(전입신고)을 마치면 그다음 날 오전 0시부터 대항력이 생긴다. 전차인(실제로 사는 직접점유자)이 주택을 인도받고 자기 이름으로 주민등록을 마쳐도 임차인은 그때부터 대항력을 얻는다."},{"종류":"요점","등급":"A","제목":"임대인 지위의 승계","글":"임차주택의 양수인은 임대인 지위를 이어받은 것으로 보고, 원래 임대인의 보증금반환채무는 원칙적으로 소멸한다. 다만 임차인이 승계를 원하지 않아 양도 사실을 안 때부터 상당한 기간 안에 이의를 제기하면 양도인의 반환채무는 소멸하지 않고, 채권담보 목적으로 형식상 양도한 경우에는 임대인 지위가 승계되지 않아 원래 임대인이 반환의무를 그대로 진다. 임대차가 끝나도 보증금을 돌려받을 때까지는 임대차관계가 계속되는 것으로 본다. 양도 전 발생한 연체차임채권은 특별한 사정이 없으면 양수인에게 승계되지 않고, 보증금반환채권이 가압류된 상태에서 양도되면 양수인이 제3채무자 지위를 승계한다."},{"종류":"조문","법":"주택임대차보호법","조":"주택임대차보호법 제3조","글":"① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다. ④ 임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."},{"종류":"비유","글":"대항력은 집이 팔려도 새 집주인에게 '계속 살겠다'고 버티는 힘, 우선변제권은 경매 때 뒷순위보다 먼저 보증금을 받는 힘이다. 앞의 것은 인도 + 전입신고로 생기고, 뒤의 것은 여기에 확정일자까지 갖춰야 생긴다."},{"종류":"소제목","글":"보증금의 회수"},{"종류":"요점","등급":"B","제목":"배당요구","글":"우선변제권이 있어도 경매 법원에 배당요구를 해야 배당받는다. 배당요구를 하지 않아 후순위 채권자가 먼저 배당받았더라도 부당이득반환을 청구할 수 없고, 우선변제금을 받으려면 주택을 양수인에게 인도해야 한다."},{"종류":"요점","등급":"B","제목":"우선변제권·최우선변제권과 대지","글":"대항요건과 확정일자를 갖춘 임차인의 우선변제권, 소액임차인의 최우선변제권 모두 임차주택의 대지 환가대금에 그대로 미친다(임차주택이 미등기라도 같다). 다만 저당권이 설정된 대지 위에 새로 지은 건물의 소액임차인은 그 저당권의 환가대금에서는 우선변제권을 인정받지 못한다."},{"종류":"비교","제목":"우선변제권과 최우선변제권","머리":["구분","우선변제권","최우선변제권(소액임차인)"],"행":[["요건","대항요건 + 확정일자","소액 보증금 + 경매신청 등기 전 대항요건(확정일자 불필요)"],["받는 순서","갖춘 때를 기준으로 한 순위대로","선순위 담보물권자보다도 먼저"],["받는 금액","보증금 전액(순위 안에서)","일정액만(서울 5천500만원), 주택가액(대지 포함)의 2분의 1까지"]],"결론":"확정일자는 순위를 정하려는 것이다 — 순위를 건너뛰는 최우선변제에는 확정일자가 필요 없다"},{"종류":"참고","글":"확정일자 = 그날 그 계약서가 있었음을 공적으로 증명하는 날짜 · 배당요구 = 경매 법원에 받을 돈이 있다고 신청하는 것"},{"종류":"비교","제목":"보증금을 지키는 순서","머리":["단계","내용"],"행":[["인도 + 전입신고","대항요건을 갖춘다"],["다음 날 오전 0시","대항력이 생긴다"],["확정일자","대항요건과 확정일자를 모두 갖추면 우선변제권이 생긴다"],["경매 때 배당요구","배당요구를 해야 배당받는다. 안 해서 후순위자가 받아 가도 부당이득반환을 청구하지 못한다"]],"결론":"우선변제권이 있어도 배당요구는 따로 해야 한다"},{"종류":"요점","등급":"","제목":"임차권등기명령","글":"임대차가 끝난 뒤 보증금을 돌려받지 못한 임차인은 주택 소재지 관할 법원(지방법원·지방법원지원·시·군법원)에 임차권등기명령을 신청할 수 있고, 그 비용은 임대인에게 청구할 수 있다. 등기를 마치면 대항력·우선변제권을 새로 얻고, 이미 취득한 대항력·우선변제권은 등기 후 이사해도 그대로 유지된다. 다만 그 등기 이후에 들어온 임차인은 최우선변제권이 없다."},{"종류":"소제목","글":"존속기간과 갱신"},{"종류":"요점","등급":"B","제목":"최단 존속기간 2년","글":"기간을 정하지 않았거나 2년보다 짧게 정했다면 그 기간은 2년으로 본다. 다만 임차인 쪽에서는 2년 미만으로 정한 기간도 유효하다고 주장할 수 있다."},{"종류":"요점","등급":"A","제목":"묵시적 갱신(법정갱신)","글":"임대인이 기간이 끝나기 6개월 전부터 2개월 전까지, 임차인이 2개월 전까지 갱신거절이나 조건변경 통지를 하지 않으면 전과 같은 조건으로 다시 임대차한 것으로 보고 기간은 2년으로 본다. 임차인은 언제든지 해지를 통고할 수 있고 통고 후 3개월이 지나면 임대차가 소멸한다. 다만 2기의 차임을 연체했거나 의무를 현저히 위반한 임차인에게는 묵시적 갱신이 인정되지 않는다."},{"종류":"요점","등급":"B","제목":"계약갱신요구권과 4년 보장","글":"임차인의 계약갱신요구권은 6개월 전부터 2개월 전까지 행사할 수 있고, 그 효력은 통지가 임대인에게 도달한 때 발생한다(임대인에게 갱신거절 사유가 없는 한). 1회만 행사할 수 있고 이렇게 갱신된 임대차의 존속기간은 2년으로 본다. 최단 존속기간 2년과 합쳐 임차인은 모두 4년의 임대차기간을 보장받는다."},{"종류":"조문","법":"주택임대차보호법","조":"주택임대차보호법 제6조의2","글":"① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"종류":"비교","제목":"묵시적 갱신과 계약갱신요구권(주택)","머리":["구분","묵시적 갱신","계약갱신요구권"],"행":[["어떻게","임대인은 6개월~2개월 전, 임차인은 2개월 전까지 아무 통지가 없을 때","임차인이 6개월~2개월 전에 요구할 때(정당한 사유 없이는 거절 못 함)"],["횟수","제한 없음","1회"],["갱신된 기간","2년","2년"],["차임·보증금","전과 같은 조건","전과 같은 조건, 다만 제7조 범위(20분의 1)에서 증감 가능"],["임차인의 해지","언제든 통지, 3개월 뒤 효력","언제든 통지, 3개월 뒤 효력(제6조의2 준용)"],["2기 차임 연체가 있으면","묵시적 갱신이 안 된다","임대인이 갱신을 거절할 수 있다"]],"결론":"어느 쪽이든 임차인은 2년을 보장받되, 원하면 해지를 통지하고 3개월 뒤 나갈 수 있다"},{"종류":"비유","글":"묵시적 갱신은 기간 안에 아무도 갱신 거절을 통지하지 않아 저절로 이어지는 자동 연장이고, 계약갱신요구권은 임차인이 딱 한 번 쓸 수 있는 연장 쿠폰이다. 연장 쿠폰은 2기 차임을 연체한 적이 있으면 임대인이 받아 주지 않아도 된다."}]},"민4-2":{"요약":"적용범위(환산보증금)와 대항력, 계약갱신요구권(10년), 권리금 회수기회 보호를 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"적용범위"},{"종류":"요점","등급":"A","제목":"적용범위와 예외 적용","글":"상가건물 임대차보호법은 사업자등록의 대상이 되는 상가건물의 임대차에 적용되고, 보증금이 대통령령으로 정한 금액을 넘으면 원칙적으로 적용되지 않는다. 다만 그런 경우에도 대항력, 권리금 회수기회 보호, 3기 연체로 인한 해지, 계약갱신요구권(존속기간을 약정한 경우), 감염병예방법에 따른 해지, 표준계약서 규정은 그대로 적용된다."},{"종류":"구조","제목":"보증금액을 넘는 상가임대차","갈래":[{"이름":"그래도 적용 ○","항목":["대항력","계약갱신요구권(기간 약정이 없으면 ×)","권리금 회수기회 보호","3기 차임 연체 해지","감염병 집합제한에 따른 폐업 해지","표준계약서"]},{"이름":"적용 ×","항목":["우선변제권·최우선변제권","임차권등기명령","최단기간 1년","묵시적 갱신"]}],"결론":"가게 자리를 지키는 규정은 남고, 보증금을 먼저 돌려받는 규정은 빠진다"},{"종류":"참고","글":"환산보증금 = 보증금 + 월차임 × 100. 예) 보증금 6억원에 월차임 100만원이면 7억원으로 보고 지역별 한도와 견준다"},{"종류":"소제목","글":"대항력과 보증금의 회수"},{"종류":"요점","등급":"B","제목":"대항력","글":"보증금액이 대통령령이 정한 금액을 넘더라도 대항력은 인정된다. 임대차를 등기하지 않았더라도 임차인이 건물을 인도받고 사업자등록을 신청하면 그다음 날부터 제3자에게 효력이 생긴다."},{"종류":"요점","등급":"B","제목":"우선변제권과 정보제공요구","글":"대항요건을 갖추고 관할 세무서장에게서 임대차계약서에 확정일자를 받은 임차인에게 우선변제권이 보장된다. 임대차계약을 체결하려는 사람은 임대인의 동의 없이도 관할 세무서장에게 그 상가건물의 임대차에 관한 정보 제공을 요구할 수 있다."},{"종류":"요점","등급":"B","제목":"임차권등기명령","글":"임대차가 끝났는데 보증금을 못 돌려받았다면, 임차인은 건물이 있는 곳의 관할 법원(지방법원·지원·시군법원)에 임차권등기명령을 혼자 신청할 수 있다(주택과 같다)."},{"종류":"참고","글":"임차권등기명령 = 보증금을 못 받은 채 이사해도 대항력·우선변제권이 그대로 유지되도록 법원 명령으로 해 두는 임차권 등기"},{"종류":"소제목","글":"존속기간과 갱신"},{"종류":"요점","등급":"B","제목":"최단 존속기간 1년","글":"기간을 정하지 않았거나 1년보다 짧게 정한 임대차라면 그 기간은 1년으로 본다. 다만 임차인 쪽에서는 1년 미만으로 정한 기간도 유효하다고 주장할 수 있다."},{"종류":"요점","등급":"B","제목":"계약갱신요구권","글":"임차인이 기간이 끝나기 6개월 전부터 1개월 전까지 계약갱신을 요구하면 임대인은 정당한 사유 없이 거절하지 못한다. 다만 임차인이 빌린 건물의 전부나 일부를 고의나 중대한 과실로 파손한 경우 등에는 거절할 수 있다. 갱신요구권은 최초 임대차기간을 포함한 전체 임대차기간이 10년을 넘지 않는 범위에서만 행사할 수 있다."},{"종류":"요점","등급":"B","제목":"묵시적 갱신과 3기 연체 해지","글":"임대인이 기간이 끝나기 6개월 전부터 1개월 전까지 갱신거절이나 조건변경 통지를 하지 않으면 전과 같은 조건으로 다시 임대차한 것으로 본다. 다만 임차인은 종료일까지 1개월이 채 남지 않은 때에도 갱신을 거절하고 최초 종료일에 임대차를 끝낼 수 있다. 묵시적으로 갱신된 임대차의 기간은 1년으로 보고, 임차인은 언제든지 해지를 통고할 수 있으며 통고 후 3개월이 지나면 효력이 생긴다. 임차인이 연체한 차임이 3기의 차임액에 이르면 임대인은 계약을 해지할 수 있다."},{"종류":"요점","등급":"","제목":"차임 증감과 감염병 폐업 해지","글":"차임이나 보증금의 증액청구는 청구 당시 금액의 100분의 5를 넘지 못하고, 증액이 있은 후 1년 안에는 다시 청구할 수 없다. 감염병예방법에 따른 집합 제한·금지 조치를 총 3개월 이상 받아 경제사정이 중대하게 변동돼 폐업한 임차인은 임대차계약을 해지할 수 있고, 그 해지는 임대인이 통고를 받은 날부터 3개월이 지나야 효력이 생긴다."},{"종류":"소제목","글":"권리금"},{"종류":"요점","등급":"","제목":"권리금 회수기회 보호","글":"임대인은 기간이 끝나기 6개월 전부터 임대차 종료 시까지 임차인이 주선한 신규임차인에게 권리금 요구·수수, 권리금 못 받게 방해, 현저히 고액의 차임·보증금 요구, 정당한 사유 없는 계약체결 거절로 권리금 회수를 방해해서는 안 된다. 신규임차인이 될 사람의 자력이 없거나 의무위반 우려, 1년 6개월 이상 비영리 사용, 임대인이 고른 신규임차인과 이미 권리금계약을 체결한 경우에는 거절해도 정당한 사유가 있다고 본다. 임대인이 계약갱신을 거절할 수 있는 사유(파손 등)가 있으면 권리금 회수기회를 보장할 의무도 없다. 이를 위반해 손해가 생기면 배상책임이 있고, 그 청구권은 임대차가 종료한 날부터 3년 안에 행사하지 않으면 소멸한다(방해가 있은 날이 아니다)."},{"종류":"조문","법":"상가건물 임대차보호법","조":"상가건물 임대차보호법 제10조","글":"② 임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다."}]},"민4-3":{"요약":"적용범위와 실행통지·청산기간, 청산금 계산과 채무자등의 말소청구권, 양도담보권자의 사용·수익 제한을 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"적용범위"},{"종류":"요점","등급":"B","제목":"적용요건","글":"가등기담보 등에 관한 법률이 적용되려면 재산권 이전의 예약으로 설정한 가등기담보에서 예약 당시 그 재산의 가액이 차용액과 이자를 합한 금액을 넘어야 한다. 예약 당시 가액이 피담보채무액에 못 미치면 청산금평가액 통지나 청산금 지급 같은 절차를 밟을 여지가 없다. 소비대차 채권을 담보하는 경우에 적용되므로 공사대금이나 매매대금 지급을 담보하려는 경우에는 적용되지 않는다. 등기나 등록을 할 수 있는 재산(선박·자동차·항공기·중기 포함)에 적용되고, 전세권·저당권·질권은 제외된다."},{"종류":"요점","등급":"B","제목":"담보가등기 여부의 판단","글":"담보가등기인지 청구권보전을 위한 가등기인지는 등기부에 적힌 표시나 주고받은 서류 종류로 형식적으로 정하지 않고, 거래의 실질과 당사자의 의사를 해석해서 정한다."},{"종류":"요점","등급":"C","제목":"가등기를 갖출 것","글":"가등기담보 설정계약만 맺고 가등기나 가등록을 하지 않았다면 이 법은 적용되지 않는다."},{"종류":"구조","제목":"가등기담보법이 적용되는가","갈래":[{"이름":"적용 ○","항목":["차용금(소비대차) 채권 담보 — 다른 채권이 함께 담보돼도 적용","예약 당시 목적물 가액 > 차용액 + 이자","가등기나 소유권이전등기를 마침","등기·등록할 수 있는 재산(자동차·선박 등 포함)"]},{"이름":"적용 ×","항목":["공사대금·매매대금만 담보","예약 당시 가액 ≤ 차용액 + 이자","설정계약만 하고 가등기는 안 함","전세권·저당권·질권"]}],"결론":"빌린 돈을 담보하고 담보물 값이 빚보다 클 때 — 이 둘이 갖춰져야 청산 절차가 따라온다"},{"종류":"참고","글":"양도담보 = 담보로 아예 소유권이전등기를 넘겨 두는 것 · 담보가등기 = 채권담보의 목적으로 마친 가등기"},{"종류":"요점","등급":"A","제목":"양도담보권자의 사용·수익 제한","글":"부동산을 채권담보 목적으로 양도했다면 특별한 사정이 없는 한 목적부동산을 사용·수익할 권리는 채무자인 양도담보설정자에게 있다. 양도담보권자는 사용·수익할 정당한 권한이 있는 채무자나 그 권한을 이어받은 사람을 상대로, 자기가 사용·수익하지 못했다는 이유로 임료 상당의 손해배상이나 부당이득반환을 청구할 수 없다."},{"종류":"조문","법":"가등기담보 등에 관한 법률","조":"가등기담보 등에 관한 법률 제1조","글":"이 법은 차용물(借用物)의 반환에 관하여 차주(借主)가 차용물을 갈음하여 다른 재산권을 이전할 것을 예약할 때 그 재산의 예약 당시 가액(價額)이 차용액(借用額)과 이에 붙인 이자를 합산한 액수를 초과하는 경우에 이에 따른 담보계약(擔保契約)과 그 담보의 목적으로 마친 가등기(假登記) 또는 소유권이전등기(所有權移轉登記)의 효력을 정함을 목적으로 한다."},{"종류":"소제목","글":"담보권의 실행(귀속청산)"},{"종류":"요점","등급":"B","제목":"실행통지와 청산금 계산","글":"채권자가 담보권을 실행해 소유권을 취득하려면 변제기 후 청산금 평가액을 채무자등에게 통지해야 한다. 청산금은 목적부동산 가액에서 피담보채권액과 선순위 권리자의 채권액을 뺀 금액이고, 선순위 담보권이 있으면 채권액을 계산할 때 그 피담보채권도 포함한다. 청산금이 없으면 없다는 뜻을 통지한다. 채권자는 자기가 통지한 청산금 액수를 두고 다툴 수 없다(실제 평가액이 다르더라도 통지한 금액에 묶인다)."},{"종류":"조문","법":"가등기담보 등에 관한 법률","조":"가등기담보 등에 관한 법률 제3조","글":"① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다. 이 경우 청산금이 없다고 인정되는 경우에는 그 뜻을 통지하여야 한다."},{"종류":"조문","법":"가등기담보 등에 관한 법률","조":"가등기담보 등에 관한 법률 제11조","글":"채무자등은 청산금채권을 변제받을 때까지 그 채무액(반환할 때까지의 이자와 손해금을 포함한다)을 채권자에게 지급하고 그 채권담보의 목적으로 마친 소유권이전등기의 말소를 청구할 수 있다. 다만, 그 채무의 변제기가 지난 때부터 10년이 지나거나 선의의 제삼자가 소유권을 취득한 경우에는 그러하지 아니하다."},{"종류":"요점","등급":"B","제목":"청산기간과 특약의 효력","글":"청산금 지급과 소유권 취득에 관한 규정에 어긋나는 특약 가운데 채무자 등에게 불리한 것은 효력이 없다. 청산기간이 지나기 전에 한 무청산특약은 무효이고, 청산기간이 지난 뒤에 한 무청산특약은 유효하다."},{"종류":"요점","등급":"C","제목":"청산금 지급과 소유권 취득","글":"청산금이 없으면 본등기를 마친 때 목적부동산의 소유권을 취득한다. 청산금 지급의무와 부동산 소유권이전등기·인도의무는 동시이행관계이므로, 청산기간이 지난 뒤 채권자는 채무자 등에게 청산금을 지급해야 비로소 담보가등기에 기초한 본등기를 할 수 있다(청산기간이 지나기 전에 한 본등기는 무효다)."},{"종류":"요점","등급":"A","제목":"채무자등의 말소청구권","글":"채무자등은 청산금을 받기 전까지 채무액(반환할 때까지의 이자·손해금 포함)을 채권자에게 갚고 담보가등기 말소를 청구할 수 있다. 다만 채무의 변제기가 지난 때부터 10년이 지났거나 선의의 제3자가 소유권을 취득했다면 말소를 청구할 수 없다."},{"종류":"비유","글":"청산은 거스름돈이다. 목적물 값에서 빚(선순위 채권 포함)을 빼고 남는 거스름돈을 채무자에게 건네야 등기를 가져올 수 있다. 거스름돈이 있는데 건네지 않고 먼저 한 본등기는 무효다."},{"종류":"참고","글":"청산금 = 목적물 가액 − (피담보채권액 + 선순위 담보 채권액) · 채무자등 = 채무자, 물상보증인, 담보가등기 뒤 소유권을 얻은 제3자"},{"종류":"참고","글":"후순위권리자 = 담보가등기 뒤에 등기된 저당권자·전세권자·담보가등기권리자 — 청산기간 안에는 자기 채권 변제기 전이라도 경매를 청구할 수 있다"},{"종류":"소제목","글":"후순위 권리자와 경매"},{"종류":"요점","등급":"B","제목":"후순위 권리자의 권리보호","글":"청산기간이 지나기 전에 채무자가 청산금에 관한 권리를 양도하거나 그 밖에 처분했더라도 이로써 후순위 권리자에게 대항하지 못한다."},{"종류":"요점","등급":"B","제목":"경매와 담보가등기","글":"담보가등기가 된 부동산에 경매 등 개시결정이 있고 그 경매 신청이 청산금 지급 전에 이루어졌다면, 그 가등기에 기초해 본등기를 청구할 권리는 담보가등기권리자에게 없다. 다만 다른 채권자보다 먼저 자기 채권을 우선변제받을 권리는 있다. 담보가등기가 된 부동산이 경매 등으로 매각되면 담보가등기 권리는 그 매각으로 소멸한다."},{"종류":"비교","제목":"담보가등기권자가 가는 두 길","머리":["구분","권리취득에 의한 실행(귀속청산)","경매"],"행":[["방법","실행 통지 → 2개월 청산기간 → 청산금 지급 → 본등기","담보가등기권리를 저당권으로 보고 경매를 청구"],["얻는 것","목적물의 소유권","순위에 따른 우선변제(배당)"],["담보가등기는","본등기로 이어진다","매각으로 소멸한다(제15조)"]],"결론":"귀속청산으로 소유권을 얻어도 선순위 저당권은 사라지지 않는다 — 그래서 청산금을 셀 때 그 채권액을 뺀다. 청산금 지급 전에 경매가 신청되면 본등기를 청구할 수 없다"},{"종류":"비교","제목":"귀속청산의 순서","머리":["단계","내용"],"행":[["변제기 경과","채무자가 변제기까지 갚지 않는다"],["실행 통지","청산금 평가액(없으면 없다는 뜻)을 채무자등에게 통지한다. 채권자는 통지한 금액을 두고 다투지 못한다"],["청산기간 2개월","통지가 채무자등에게 도달한 날부터 2개월이 지나야 한다"],["청산금 지급","청산금 지급과 본등기·인도는 동시이행이다"],["본등기 → 소유권 취득","청산금이 없으면 청산기간이 지난 뒤 본등기를 마친 때 소유권을 얻는다"]],"결론":"청산기간이 지나기 전에 한 채무자에게 불리한 특약(무청산 특약 등)은 무효, 지난 뒤 제3자 권리를 해치지 않는 특약은 유효하다"}]},"민4-4":{"요약":"전유부분·공용부분의 구별과 등기, 대지사용권의 일체성, 관리인 선임과 재건축·복구 결의의 정족수를 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"전유부분과 공용부분"},{"종류":"요점","등급":"B","제목":"전유부분과 공용부분의 구별","글":"구분소유권의 목적이 되는 건물 부분을 전유부분이라 하고, 구분소유권의 객체가 될 수 있는데도 공용으로 쓰이면 그 부분은 공용부분이다."},{"종류":"요점","등급":"A","제목":"공용부분의 등기","글":"구조상 공용부분은 등기 없이도 공용부분이 되고 물권변동 등기도 필요 없다. 규약상 공용부분은 공용부분이라는 취지의 등기가 있어야 하지만 물권변동 등기는 여전히 필요 없다."},{"종류":"구조","제목":"집합건물 한 동의 구성","갈래":[{"이름":"전유부분","항목":["구분소유권의 목적인 건물 부분","구분소유가 가능해도 공용으로 쓰이면 공용부분"]},{"이름":"공용부분","항목":["구조상 공용부분 — 복도·계단, 등기 불필요, 시효취득 ×","규약상 공용부분 — 규약·공정증서로 지정, 공용부분이라는 취지를 등기"]},{"이름":"대지사용권","항목":["소유권·지상권·전세권·임차권","전유부분과 일체 — 규약으로 달리 정하지 않으면 분리처분 ×"]}],"결론":"공용부분 지분과 대지사용권은 전유부분을 따라간다"},{"종류":"조문","법":"집합건물의 소유 및 관리에 관한 법률","조":"집합건물의 소유 및 관리에 관한 법률 제13조","글":"① 공용부분에 대한 공유자의 지분은 그가 가지는 전유부분의 처분에 따른다. ② 공유자는 그가 가지는 전유부분과 분리하여 공용부분에 대한 지분을 처분할 수 없다. ③ 공용부분에 관한 물권의 득실변경(得失變更)은 등기가 필요하지 아니하다."},{"종류":"요점","등급":"B","제목":"공용부분의 사용·관리·수익","글":"각 공유자는 공용부분을 그 용도에 맞게 사용할 수 있다. 규약에 다른 정함이 없으면 각 공유자는 지분 비율대로 공용부분 관리비용과 조세 등 의무를 부담하고 공용부분에서 생기는 이익도 가진다. 일부 구분소유자만 공용하도록 제공된 것이 명백한 공용부분(일부공용부분)은 그들 구분소유자만의 공유에 속한다."},{"종류":"요점","등급":"B","제목":"관리비의 특별승계","글":"아파트의 특별승계인은 전 입주자가 밀린 관리비 가운데 공용부분 관리비는 승계하지만, 그 연체료는 승계하지 않는다."},{"종류":"비유","글":"전유부분은 내 호실, 공용부분은 복도·계단이다. 호실을 팔면 복도 지분은 저절로 따라가고 복도 지분만 따로 팔 수는 없으며, 복도를 오래 차지해도 시효로 내 것이 되지 않는다."},{"종류":"참고","글":"특별승계인 = 매매·경매 등으로 그 호실을 넘겨받은 사람 — 앞사람이 밀린 관리비 중 공용부분 관리비는 떠안지만 그 연체료는 떠안지 않는다"},{"종류":"요점","등급":"B","제목":"대지사용권과 일체성","글":"대지사용권은 구분소유자가 전유부분을 소유하려고 건물의 대지에 대해 갖는 권리(소유권·지상권·전세권·임차권)다. 규약으로 달리 정하지 않았다면 대지사용권을 전유부분과 떼어 처분할 수 없고, 전유부분과 일체성을 갖게 된 뒤 시작된 강제경매절차로도 마찬가지다."},{"종류":"조문","법":"집합건물의 소유 및 관리에 관한 법률","조":"집합건물의 소유 및 관리에 관한 법률 제20조","글":"① 구분소유자의 대지사용권은 그가 가지는 전유부분의 처분에 따른다. ② 구분소유자는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다. 다만, 규약으로써 달리 정한 경우에는 그러하지 아니하다."},{"종류":"소제목","글":"관리단·관리인"},{"종류":"요점","등급":"A","제목":"관리인의 선임","글":"구분소유자가 10인 이상이면 관리단집회 결의로 관리인을 선임·해임해야 한다(강행규정). 관리인이 꼭 구분소유자일 필요는 없다."},{"종류":"요점","등급":"C","제목":"관리인의 권한과 관리위원회","글":"관리인은 공용부분 보존행위, 공용부분 관리·변경에 관한 관리단집회 결의 집행, 관리단 사무집행 비용·분담금의 청구·수령·관리, 관리단을 대표하는 재판상·재판외 행위, 그 밖에 규약에서 정한 행위를 할 권한과 의무가 있다. 건물 전체나 상당 부분의 임대권한을 관리인에게 맡기는 규약은 무효다. 관리위원회를 둔 경우 관리인이 이런 행위를 하려면 원칙적으로 관리위원회 결의를 거쳐야 한다(규약으로 달리 정한 사항은 예외). 관리위원회 위원은 규약에 달리 정하지 않았다면 구분소유자 중에서 관리단집회 결의로 뽑고, 임기는 2년 범위에서 규약으로 정한다."},{"종류":"요점","등급":"","제목":"정기 관리단집회","글":"관리인은 매년 회계연도가 끝난 뒤 3개월 안에 정기 관리단집회를 소집해야 한다."},{"종류":"비교","제목":"관리단·관리인·관리위원회","머리":["구분","관리단","관리인","관리위원회"],"행":[["생기는 방법","구분소유 관계가 성립하면 저절로 설립","구분소유자 10인 이상이면 반드시 선임","규약으로 둘 수 있다"],["누구로","구분소유자 전원","구분소유자가 아니어도 된다","구분소유자 중에서 관리단집회 결의로 선출"],["임기","—","2년 범위에서 규약으로","2년 범위에서 규약으로"],["하는 일","건물·대지·부속시설 관리 사업","관리단을 대표하고 사무를 집행","관리인의 사무 집행을 감독"]],"결론":"관리인은 외부 사람이어도 되지만, 규약에 달리 정한 바가 없으면 관리위원회 위원을 겸하지 못한다"},{"종류":"비유","글":"관리단은 가입 절차 없이 구분소유와 동시에 생기는 소유자 전체 모임, 관리인은 그 모임의 대표다. 대표는 소유자가 아닌 전문가여도 된다."},{"종류":"참고","글":"규약 = 건물의 관리·사용에 관해 구분소유자들이 정한 자치 규칙(설정·변경·폐지는 구분소유자와 의결권 각 4분의 3 이상 찬성)"},{"종류":"소제목","글":"의결 정족수와 재건축"},{"종류":"비교","제목":"관리단집회 의결 정족수","머리":["결의","구분소유자","의결권"],"행":[["보통 결의","과반수","과반수"],["공용부분 변경","3분의 2 이상","3분의 2 이상"],["규약 설정·변경·폐지","4분의 3 이상","4분의 3 이상"],["재건축","5분의 4 이상","5분의 4 이상"],["일부멸실(건물가격 2분의 1 초과) 복구","5분의 4 이상","5분의 4 이상"]],"결론":"건물을 허무는 재건축과 절반 넘게 멸실된 부분을 되살리는 복구만 5분의 4다"},{"종류":"요점","등급":"B","제목":"재건축의 결의","글":"재건축은 구분소유자와 의결권의 각 5분의 4 이상 결의로 한다."},{"종류":"요점","등급":"","제목":"일부멸실과 복구","글":"멸실된 부분이 건물가격의 2분의 1을 넘으면 구분소유자와 의결권 각 5분의 4 이상의 찬성으로 복구를 결의할 수 있다. 복구 결의에 반대한 구분소유자는 찬성한 구분소유자에게 건물과 대지에 관한 권리를 시가로 매수하라고 청구할 수 있다."},{"종류":"비교","제목":"재건축 결의 뒤","머리":["단계","내용"],"행":[["재건축 결의","구분소유자와 의결권 각 5분의 4 이상"],["참가 여부 촉구","찬성하지 않은 구분소유자에게 참가할지 서면으로 묻는다"],["2개월 안 회답","회답이 없으면 참가하지 않겠다고 회답한 것으로 본다"],["매도청구","회답기간 만료일부터 2개월 안에 불참자에게 구분소유권과 대지사용권을 시가로 팔라고 청구한다"]],"결론":"재건축은 찬성 쪽이 반대 쪽에 '팔라'(매도청구), 복구는 반대 쪽이 찬성 쪽에 '사라'(매수청구) — 방향이 반대다"},{"종류":"조문","법":"집합건물의 소유 및 관리에 관한 법률","조":"집합건물의 소유 및 관리에 관한 법률 제47조","글":"② 제1항의 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의에 따른다. 다만, 「관광진흥법」 제3조제1항제2호나목에 따른 휴양 콘도미니엄업의 운영을 위한 휴양 콘도미니엄의 재건축 결의는 구분소유자의 3분의 2 이상 및 의결권의 3분의 2 이상의 결의에 따른다."},{"종류":"요점","등급":"B","제목":"담보책임의 기산점","글":"전유부분에 대한 담보책임은 구분소유자에게 인도한 날부터 기산하고, 공용부분에 대한 담보책임은 사용검사일(사용승인일)부터 기산한다."},{"종류":"참고","글":"담보책임 존속기간의 기산점 = 전유부분은 구분소유자에게 인도한 날, 공용부분은 사용검사일(또는 사용승인일)"}]},"민4-5":{"요약":"명의신탁 3유형(양자 간·3자 간·계약명의신탁)의 효력과 제3자 보호, 배우자·종중 특례를 가장 많이 묻는다.","블록":[{"종류":"소제목","글":"명의신탁의 뜻과 효력"},{"종류":"요점","등급":"B","제목":"명의신탁의 뜻과 소유권의 2원화","글":"당사자 사이의 신탁에 관한 채권계약(명의신탁약정)에 따라, 신탁자가 사실상 자기 소유인 부동산의 등기명의를 실제로는 거래 없는 수탁자 앞으로 매매 등의 형식을 빌려 옮겨 두는 것을 명의신탁이라 한다. 등기가 소유권이전등기든 가등기든, 약정이 명시적이든 묵시적이든, 탈세 등 목적이 있어도 이 법의 규제 대상인 명의신탁에 해당한다. 유효한 명의신탁이라면 대내적 소유권은 신탁자, 대외적 소유권은 수탁자가 가지고, 제3자에 대한 소유권 주장은 대외적 소유자인 수탁자만 할 수 있어 신탁자는 수탁자를 대위해서만 행사할 수 있다."},{"종류":"요점","등급":"C","제목":"배우자 특례","글":"특례가 인정되는 '배우자'는 법률상 배우자만을 뜻하고 사실혼 배우자는 포함되지 않는다. 배우자 한쪽이 사망해 부부관계가 끝났더라도 명의신탁약정은 그 배우자의 다른 상속인과의 관계에서 계속 유효하고, 명의신탁 해지를 원인으로 한 소유권이전등기청구권은 소멸시효에 걸리지 않는다."},{"종류":"구조","제목":"명의신탁인가, 유효한가","갈래":[{"이름":"명의신탁이 아님","항목":["양도담보·가등기담보","구분소유적 공유(상호명의신탁)","신탁법 등에 따른 신탁재산임을 등기"]},{"이름":"유효한 명의신탁(탈법 목적이 없을 때)","항목":["종중 부동산을 종중 외 명의로","법률상 배우자 명의로(사실혼 ×)","종교단체 명의로 산하 조직 부동산을"]},{"이름":"무효인 명의신탁","항목":["양자 간(이전형)","3자 간(중간생략형)","계약명의신탁(위임형)"]}],"결론":"특례에 들지 못하면 약정은 무효 — 무효인 명의신탁은 세 모양으로 갈린다"},{"종류":"참고","글":"대내적 소유권 = 신탁자와 수탁자 사이에서는 신탁자 것으로 보는 것 · 대외적 소유권 = 제3자에게는 등기명의인(수탁자) 것으로 보는 것 — 명의신탁이 유효한 특례의 경우에 쓰는 말이다"},{"종류":"요점","등급":"A","제목":"명의신탁약정의 효력","글":"이 법의 적용 예외에 해당하지 않으면 신탁자와 수탁자 사이의 명의신탁약정은 무효다. 명의신탁약정과 그에 따른 등기가 무효라는 것은 제3자에게 대항하지 못하며, 그 제3자가 선의인지 악의인지는 묻지 않는다."},{"종류":"조문","법":"부동산 실권리자명의 등기에 관한 법률","조":"부동산 실권리자명의 등기에 관한 법률 제4조","글":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"종류":"소제목","글":"무효인 명의신탁 3유형"},{"종류":"구조","제목":"무효인 명의신탁 3유형","갈래":[{"이름":"양자 간(이전형)","항목":["신탁자 소유 부동산을 수탁자 명의로 이전","약정·등기 무효 → 소유자는 신탁자","진정명의회복 이전등기 청구 ○ · 명의신탁 해지·부당이득을 원인으로는 ×"]},{"이름":"3자 간(중간생략형)","항목":["신탁자가 매도인과 계약하고 등기만 수탁자 앞으로","약정·등기 무효, 매매계약은 유효 → 소유자는 매도인","신탁자는 매도인을 대위해 수탁자 등기를 말소시키고 매도인에게 이전등기 청구"]},{"이름":"계약명의신탁(위임형)","항목":["수탁자가 자기 이름으로 매도인과 계약","매도인 선의 → 수탁자 소유, 신탁자는 매수자금만 부당이득 반환 청구","매도인 악의 → 등기 무효, 소유자는 매도인"]}],"결론":"어느 유형이든 수탁자에게서 산 제3자는 선의·악의를 묻지 않고 보호된다(제4조 제3항)"},{"종류":"요점","등급":"A","제목":"양자 간 명의신탁","글":"양자 간 명의신탁에서 신탁자는 수탁자에게 명의신탁 해지를 원인으로 소유권이전등기를 청구할 수 없다. 수탁자 앞으로 된 소유권이전등기는 원인무효라서 말소되어야 하고, 신탁자는 수탁자를 상대로 진정명의회복을 원인으로 한 소유권이전등기를 청구할 수 있다."},{"종류":"요점","등급":"A","제목":"계약명의신탁 — 매도인이 선의인 경우","글":"매도인이 선의라면 매도인과 수탁자 사이의 매매계약은 유효해 수탁자가 확정적으로 유효한 소유권을 얻는다. 신탁자는 수탁자에게 건넨 매매대금 등을 부당이득으로 돌려 달라고 청구할 수 있을 뿐 부동산 자체의 반환은 청구할 수 없고, 수탁자가 소유물반환을 청구할 때 신탁자는 매매대금반환청구권으로 유치권을 주장할 수 없다."},{"종류":"요점","등급":"B","제목":"계약명의신탁 — 매도인이 악의인 경우","글":"매도인이 악의라면 수탁자 명의의 등기(물권변동)는 무효고 부동산 소유자는 매도인으로 남는다. 다만 경매로 이루어진 계약명의신탁은 매도인 쪽(채무자·소유자)이 명의신탁 사실을 알았더라도 예외적으로 유효로 본다. 명의수탁자가 제3자에게 그 부동산을 처분하면 매도인의 소유권을 침해한 것이어서 불법행위가 된다."},{"종류":"비교","제목":"한방 정리 — 명의신탁 3유형","머리":["구분","양자 간","3자 간","계약명의신탁"],"행":[["매도인과 계약한 사람","없음(신탁자 자기 부동산)","신탁자","수탁자"],["수탁자 명의 등기","무효","무효","매도인 선의면 유효 · 악의면 무효"],["소유자","신탁자","매도인","매도인 선의: 수탁자 · 악의: 매도인"],["신탁자가 청구할 것","수탁자에게 진정명의회복 이전등기(또는 말소)","매도인을 대위해 수탁자 등기 말소 + 매도인에게 이전등기","수탁자에게 매수자금 부당이득 반환(부동산 자체 ×)"],["수탁자가 제3자에게 팔면","제3자 소유 · 수탁자는 신탁자에게 불법행위 책임","제3자 소유","제3자 소유 · 매도인 악의면 매도인에 대한 불법행위"]],"결론":"약정은 셋 다 무효, 제3자는 셋 다 보호 — 갈리는 것은 소유권이 어디 있고 신탁자가 무엇을 청구하느냐다"},{"종류":"비유","글":"3자 간이냐 계약명의신탁이냐는 매매의 효과를 누구에게 돌리기로 했느냐로 가른다. 계약서에 수탁자 이름이 적혀 있어도 매도인이 신탁자에게 효과를 돌릴 뜻이었다면 3자 간이고, 수탁자 자신을 매수인으로 삼았다면 계약명의신탁이다."},{"종류":"비유","글":"무효인 명의신탁은 내 가방에 남의 이름표를 붙여 둔 것과 같다. 이름표가 무효라 가방은 여전히 내 것이지만(양자 간), 이름표 주인(수탁자)에게서 가방을 산 사람은 사정을 알았든 몰랐든 가방을 갖는다."},{"종류":"소제목","글":"특례와 용어"},{"종류":"조문","법":"부동산 실권리자명의 등기에 관한 법률","조":"부동산 실권리자명의 등기에 관한 법률 제8조","글":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 1. 종중(宗中)이 보유한 부동산에 관한 물권을 종중(종중과 그 대표자를 같이 표시하여 등기한 경우를 포함한다) 외의 자의 명의로 등기한 경우 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우 3. 종교단체의 명의로 그 산하 조직이 보유한 부동산에 관한 물권을 등기한 경우"},{"종류":"참고","글":"진정명의회복 = 무효 등기를 지우는 대신 진짜 소유자 앞으로 이전등기를 새로 받는 방법 · 선의·악의 불문 = 사정을 알았든 몰랐든 결과가 같다는 뜻 · 배우자 특례 = 법률상 배우자만, 명의신탁 뒤 혼인하면 그때부터 유효, 배우자가 사망해도 상속인과의 관계에서 유효하게 남는다"}]}};